  guide_slugs = excluded.guide_slugs,
  categories = excluded.categories;

insert into public.editorial_guides (
  id,
  slug,
  category,
  country,
  city,
  neighborhood,
  list
)
values
  ('list-paris-1st-arrondissement-restaurants', 'paris-1st-arrondissement-restaurants', 'Food', 'France', 'Paris', '1st Arrondissement', '{"id":"list-paris-1st-arrondissement-restaurants","slug":"paris-1st-arrondissement-restaurants","seoSlug":"best-restaurants","seoTitle":"Best Restaurants in 1st Arrondissement, Paris","seoDescription":"Best restaurants in 1st Arrondissement, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Museum-Day Meals Around the Royal Core","description":"The 1st needs meals that can survive Louvre timing, Tuileries walks, and central crowds. This guide mixes tea-room ritual, udon, polished dining, and a classic cafe so the day has food options without leaving the royal core.","url":"https://www.google.com/maps/search/1st%20Arrondissement%20Restaurants%20Paris","category":"Food","location":{"city":"Paris","neighborhood":"1st Arrondissement","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-food","name":"R Food","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"first-food-angelina","name":"Angelina","coordinates":[48.8651,2.3286],"description":"Angelina is the Tuileries-side tea-room ritual for hot chocolate, pastries, and a seated pause between the Louvre, Rue de Rivoli, and Concorde. Use it when the stop is about classic Paris room tone as much as sugar.","price":"$$","priceSource":"Google Maps / Paris dining guides","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-angelina"},{"id":"first-food-sanukiya","name":"Sanukiya","coordinates":[48.8648,2.3339],"description":"Sanukiya gives the 1st a practical Japanese noodle stop near Pyramides, useful when the day needs speed, warmth, and value instead of another long French meal. It is best for lunch windows around Palais Royal or the Louvre.","price":"$","priceSource":"Google Maps / Paris dining guides","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-sanukiya"},{"id":"first-food-verjus","name":"Verjus","coordinates":[48.8634,2.3381],"description":"Verjus is the small reservation dinner for travelers who want the Louvre area to end with a proper modern meal rather than a tourist-corridor compromise. Save it for a more deliberate evening near Palais Royal.","price":"$$$","priceSource":"MICHELIN Guide / Google Maps","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-verjus"},{"id":"first-food-le-nemours","name":"Le Nemours","coordinates":[48.8639,2.3359],"description":"Le Nemours is the cafe-brasserie hinge between the Louvre, Palais Royal, and Comedie-Francaise. It works for breakfast, coffee, or a simple lunch when location and terrace rhythm matter more than discovery.","price":"$$","priceSource":"Google Maps / local dining guides","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-le-nemours"}],"sources":[{"name":"Eater - Best Restaurants in Paris","url":"https://www.eater.com/maps/best-restaurants-paris-france"},{"name":"Eater - Paris","url":"https://www.eater.com/paris"},{"name":"The Infatuation - Paris","url":"https://www.theinfatuation.com/paris"},{"name":"The Infatuation - Le Marais","url":"https://www.theinfatuation.com/paris/neighborhoods/le-marais"},{"name":"MICHELIN Guide - Paris restaurants","url":"https://guide.michelin.com/us/en/ile-de-france/paris/restaurants"},{"name":"Time Out - Paris restaurants","url":"https://www.timeout.com/paris/en/restaurants"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-1st-arrondissement-bars', 'paris-1st-arrondissement-bars', 'Nightlife', 'France', 'Paris', '1st Arrondissement', '{"id":"list-paris-1st-arrondissement-bars","slug":"paris-1st-arrondissement-bars","seoSlug":"best-bars","seoTitle":"Best Bars in 1st Arrondissement, Paris","seoDescription":"Best bars in 1st Arrondissement, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Central Cocktails and Museum-Edge Bars","description":"Nights in the 1st work best as a polished first or final drink near galleries, passages, and palace hotels. This guide keeps the route central with cocktail rooms, hotel bars, and cafe-bars that do not pull the night across town.","url":"https://www.google.com/maps/search/1st%20Arrondissement%20Bars%20Paris","category":"Nightlife","location":{"city":"Paris","neighborhood":"1st Arrondissement","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nightlife","name":"R Nightlife","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"first-nightlife-danico","name":"Danico","coordinates":[48.8666,2.3399],"description":"Danico is the Galerie Vivienne cocktail destination with World 50 Best support and a hidden-room feel that fits a polished Right Bank night. Use it when the evening needs one serious drink near Palais Royal or Bourse.","price":"$$$","priceSource":"World''s 50 Best Bars / Google Maps","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-danico"},{"id":"first-nightlife-bar-228","name":"Bar 228","coordinates":[48.865,2.3286],"description":"Bar 228 at Le Meurice gives the Tuileries edge a grand-hotel drink with dark wood, deep seats, and classic service. It is strongest for a special-occasion nightcap after museums, dinner, or a river walk.","price":"$$$","priceSource":"Official hotel site / Google Maps","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-bar-228"},{"id":"first-nightlife-le-fumoir","name":"Le Fumoir","coordinates":[48.8606,2.3407],"description":"Le Fumoir is the Louvre-adjacent cocktail and wine-room fallback that still feels composed enough for a central night. Save it for a drink that can follow the museum without turning into a full bar crawl.","price":"$$","priceSource":"Google Maps / local nightlife guides","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-le-fumoir"},{"id":"first-nightlife-juveniles","name":"Juveniles","coordinates":[48.8669,2.3373],"description":"Juveniles is the wine-bar and small-plates option that keeps the covered-passage area relaxed. It works when the plan wants bottles, food, and conversation instead of a formal hotel bar.","price":"$$","priceSource":"Google Maps / local wine guides","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-juveniles"}],"sources":[{"name":"The World''s 50 Best Bars - Bar Nouveau","url":"https://www.theworlds50best.com/bars/the-list/bar-nouveau.html"},{"name":"The World''s 50 Best Bars - The Cambridge Public House","url":"https://www.theworlds50best.com/bars/the-list/the-cambridge-public-house.html"},{"name":"The World''s 50 Best Bars - Danico","url":"https://www.theworlds50best.com/bars/the-list/danico.html"},{"name":"Time Out - Best cocktail bars in Paris","url":"https://www.timeout.com/paris/en/bars-pubs/best-cocktail-bars-in-paris"},{"name":"Time Out - Canal Saint-Martin bars","url":"https://www.timeout.com/paris/en/bars-pubs/bars-in-canal-saint-martin-ourcq-villette"},{"name":"Visit Paris Region - La Gare / Le Gore","url":"https://www.visitparisregion.com/en/la-gare-le-gore"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-1st-arrondissement-parks-and-walks', 'paris-1st-arrondissement-parks-and-walks', 'Nature', 'France', 'Paris', '1st Arrondissement', '{"id":"list-paris-1st-arrondissement-parks-and-walks","slug":"paris-1st-arrondissement-parks-and-walks","seoSlug":"best-parks","seoTitle":"Best Parks and Walks in 1st Arrondissement, Paris","seoDescription":"Best parks and walks in 1st Arrondissement, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Gardens, River Edges, and Central Air","description":"Nature in the 1st is not wilderness; it is the breathing room around heavyweight sights. This guide links palace gardens, island edges, and the Seine so museum days can reset without adding another metro ride.","url":"https://www.google.com/maps/search/1st%20Arrondissement%20Parks%20and%20Walks%20Paris","category":"Nature","location":{"city":"Paris","neighborhood":"1st Arrondissement","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nature","name":"R Nature","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"first-nature-tuileries","name":"Jardin des Tuileries","coordinates":[48.8635,2.327],"description":"Jardin des Tuileries turns the Louvre-Orangerie corridor into a paced walk with chairs, fountains, and broad sightlines. Use it between timed tickets or as the soft landing after a crowded museum block.","photo":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-jardin-des-tuileries"},{"id":"first-nature-palais-royal-garden","name":"Jardin du Palais Royal","coordinates":[48.8637,2.3377],"description":"Jardin du Palais Royal is the quieter garden pause behind arcades and columns, useful when the Louvre side feels too exposed. It is a compact reset before covered passages, shopping, or dinner.","photo":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-jardin-du-palais-royal"},{"id":"first-nature-vert-galant","name":"Square du Vert-Galant","coordinates":[48.8571,2.3413],"description":"Square du Vert-Galant gives the 1st a low island viewpoint at the tip of Ile de la Cite. Use it for a short Seine pause between Sainte-Chapelle, Pont Neuf, and the Louvre.","photo":"https://images.unsplash.com/photo-1508050919630-b135583b29ab?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-square-du-vert-galant"},{"id":"first-nature-seine-quays","name":"Seine Quays by the Louvre","coordinates":[48.8589,2.3408],"description":"The Seine quays make the 1st feel walkable instead of monument-heavy, especially between Pont Neuf, the Louvre, and Orsay views. Save this stop when the route needs light, orientation, and movement.","photo":"https://images.unsplash.com/photo-1508050919630-b135583b29ab?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-seine-quays-by-the-louvre"}],"sources":[{"name":"Ville de Paris - Parc des Buttes-Chaumont","url":"https://www.paris.fr/equipements/parc-des-buttes-chaumont-1757"},{"name":"Ville de Paris - Coulee verte Rene Dumont","url":"https://www.paris.fr/lieux/coulee-verte-rene-dumont-1772"},{"name":"Ville de Paris - Pere-Lachaise","url":"https://www.paris.fr/lieux/cimetiere-du-pere-lachaise-4080"},{"name":"Paris je t''aime - Pere-Lachaise","url":"https://parisjetaime.com/eng/paris-museum-monument/71470/Cimetiere-du-Pere-Lachaise"},{"name":"Louvre - Tuileries Garden hours","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-1st-arrondissement-culture', 'paris-1st-arrondissement-culture', 'Culture', 'France', 'Paris', '1st Arrondissement', '{"id":"list-paris-1st-arrondissement-culture","slug":"paris-1st-arrondissement-culture","seoSlug":"best-culture","seoTitle":"Best Culture in 1st Arrondissement, Paris","seoDescription":"Best culture in 1st Arrondissement, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Royal Core and Museum Weight","description":"The 1st can overload a day if the Louvre is treated as the only point. This guide links the museum with Palais Royal, Orangerie, Sainte-Chapelle, and the surrounding gardens so the central core feels routeable.","url":"https://www.google.com/maps/search/1st%20Arrondissement%20Culture%20Paris","category":"Culture","location":{"city":"Paris","neighborhood":"1st Arrondissement","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-culture","name":"R Culture","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"first-culture-louvre","name":"Musee du Louvre","coordinates":[48.8606,2.3376],"description":"The Louvre is the 1st Arrondissement heavyweight, but it works best as a bounded museum plan rather than a full-day endurance test. Choose a wing, book a time slot, and leave room for the garden or Palais Royal.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-musee-du-louvre"},{"id":"first-culture-palais-royal","name":"Palais Royal","coordinates":[48.8637,2.3377],"description":"Palais Royal gives the Louvre area a quieter architectural and garden pause, with arcades, columns, and a clean route toward covered passages. It is useful when the district needs a reset without leaving the core.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-palais-royal"},{"id":"first-culture-orangerie","name":"Musee de l''Orangerie","coordinates":[48.8638,2.3227],"description":"Musee de l''Orangerie is the compact art stop that can balance or replace a larger museum block. Monet''s rooms and the Tuileries setting make it a powerful but manageable cultural anchor.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-musee-de-l-orangerie"},{"id":"first-culture-sainte-chapelle","name":"Sainte-Chapelle","coordinates":[48.8554,2.345],"description":"Sainte-Chapelle adds a short, high-impact Gothic stop on the Ile de la Cite edge of the 1st. Timed entry helps it pair cleanly with the Louvre, Conciergerie, river walks, or a Marais continuation.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-sainte-chapelle"}],"sources":[{"name":"Louvre - Hours and admission","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Musee d''Orsay - Visit","url":"https://www.musee-orsay.fr/en/visit"},{"name":"Paris je t''aime - Place des Vosges","url":"https://parisjetaime.com/eng/transport/place-des-vosges-p1907"},{"name":"Sacre-Coeur Montmartre official","url":"https://www.sacre-coeur-montmartre.com/"},{"name":"Paris Opera - Visit the Palais Garnier","url":"https://www.operadeparis.fr/en/visits/visit-and-explore/visit-the-palais-garnier"},{"name":"Paris Catacombs official","url":"https://www.catacombes.paris.fr/en"},{"name":"Musee Rodin - Plan your visit","url":"https://www.musee-rodin.fr/en/plan-your-visit/plan-your-visit-musee-rodin"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-1st-arrondissement-hotels-and-hostels', 'paris-1st-arrondissement-hotels-and-hostels', 'Stay', 'France', 'Paris', '1st Arrondissement', '{"id":"list-paris-1st-arrondissement-hotels-and-hostels","slug":"paris-1st-arrondissement-hotels-and-hostels","seoSlug":"best-hotels","seoTitle":"Best Hotels and Hostels in 1st Arrondissement, Paris","seoDescription":"Best hotels and hostels in 1st Arrondissement, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Palace Hotels and Central Sleep","description":"Staying in the 1st is about paying for centrality: palace service, Louvre access, shopping arcades, and short walks to the Seine. This guide keeps the picks honest for travelers who want the hotel to be part of the trip.","url":"https://www.google.com/maps/search/1st%20Arrondissement%20Hotels%20and%20Hostels%20Paris","category":"Stay","location":{"city":"Paris","neighborhood":"1st Arrondissement","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-stay","name":"R Stay","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"first-stay-cheval-blanc","name":"Cheval Blanc Paris","coordinates":[48.8588,2.342],"description":"Cheval Blanc Paris is the Seine-facing luxury base for travelers who want palace-level service, Samaritaine access, and immediate Right Bank positioning. It is best when the hotel experience matters as much as the route.","price":"$$$","priceSource":"Conde Nast Traveler / Google Travel","photo":"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-cheval-blanc-paris"},{"id":"first-stay-le-meurice","name":"Le Meurice","coordinates":[48.865,2.3286],"description":"Le Meurice gives the 1st classic palace gravity on Rue de Rivoli, with Tuileries and the Louvre almost outside the door. Choose it for grand-service travel and museum-heavy days.","price":"$$$","priceSource":"Official hotel site / Google Travel","photo":"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-le-meurice"},{"id":"first-stay-regina-louvre","name":"Hotel Regina Louvre","coordinates":[48.8638,2.3322],"description":"Hotel Regina Louvre is the heritage stay for travelers who want Tuileries, Palais Royal, and Louvre access without the newest design-hotel mood. It fits first-time Paris routes that prize address and view corridors.","price":"$$$","priceSource":"Google Travel / Tripadvisor","photo":"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-hotel-regina-louvre"},{"id":"first-stay-madame-reve","name":"Hotel Madame Reve","coordinates":[48.8626,2.3428],"description":"Hotel Madame Reve gives the 1st a newer design-led base in the former post-office building near Les Halles and the Louvre. It works when central access, rooftop energy, and contemporary rooms matter.","price":"$$$","priceSource":"Conde Nast Traveler / Google Travel","photo":"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-hotel-madame-reve"}],"sources":[{"name":"Conde Nast Traveler - Best hotels in Paris","url":"https://www.cntraveler.com/gallery/best-hotels-in-paris"},{"name":"Hostelworld - Paris hostels","url":"https://www.hostelworld.com/hostels/Paris"},{"name":"The Times - Best hotels in Paris 2026","url":"https://www.thetimes.com/travel/destinations/europe-travel/france/paris/best-hotels-in-paris-65dngr3zt"},{"name":"Tripadvisor - Paris hotels","url":"https://www.tripadvisor.com/Hotels-g187147-Paris_Ile_de_France-Hotels.html"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-1st-arrondissement-things-to-do', 'paris-1st-arrondissement-things-to-do', 'Activities', 'France', 'Paris', '1st Arrondissement', '{"id":"list-paris-1st-arrondissement-things-to-do","slug":"paris-1st-arrondissement-things-to-do","seoSlug":"best-things-to-do","seoTitle":"Best Things to Do in 1st Arrondissement, Paris","seoDescription":"Best things to do in 1st Arrondissement, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"A Central Day That Does Not Spiral","description":"The 1st is strongest when it becomes a tight route rather than a list of famous errands. This guide groups museum time, gardens, island glass, passages, and Seine walks into manageable activity blocks.","url":"https://www.google.com/maps/search/1st%20Arrondissement%20Things%20to%20Do%20Paris","category":"Activities","location":{"city":"Paris","neighborhood":"1st Arrondissement","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-activities","name":"R Activities","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"first-activity-louvre-tuileries","name":"Louvre and Tuileries Block","coordinates":[48.8612,2.3376],"description":"The Louvre and Tuileries block is the central activity anchor: one planned museum theme, then garden air and a clean westward walk. Use it as a half-day structure instead of trying to solve the whole museum.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-louvre-and-tuileries-block"},{"id":"first-activity-sainte-chapelle-cite","name":"Sainte-Chapelle and Ile de la Cite","coordinates":[48.8554,2.345],"description":"Sainte-Chapelle and Ile de la Cite turn the edge of the 1st into a short Gothic-and-river activity. It is best with timed entry, Pont Neuf, and a slow move back toward the Louvre.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-sainte-chapelle-and-ile-de-la-cite"},{"id":"first-activity-palais-royal-passages","name":"Palais Royal and Covered Passages","coordinates":[48.8642,2.3381],"description":"Palais Royal and the nearby covered passages make a weather-proof walk with arcades, shops, and architecture. Use it when the day needs detail and browsing after a major sight.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-palais-royal-and-covered-passages"},{"id":"first-activity-samaritaine-seine","name":"Samaritaine and the Seine","coordinates":[48.8591,2.3426],"description":"Samaritaine and the Seine give the 1st a shopping-and-river activity that stays compact. It works for a lighter block between meals, hotel check-in, and central evening plans.","photo":"https://images.unsplash.com/photo-1508050919630-b135583b29ab?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-samaritaine-and-the-seine"}],"sources":[{"name":"Louvre - Hours and admission","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Musee d''Orsay - Visit","url":"https://www.musee-orsay.fr/en/visit"},{"name":"Paris je t''aime - Place des Vosges","url":"https://parisjetaime.com/eng/transport/place-des-vosges-p1907"},{"name":"Sacre-Coeur Montmartre official","url":"https://www.sacre-coeur-montmartre.com/"},{"name":"Paris Opera - Visit the Palais Garnier","url":"https://www.operadeparis.fr/en/visits/visit-and-explore/visit-the-palais-garnier"},{"name":"Paris Catacombs official","url":"https://www.catacombes.paris.fr/en"},{"name":"Musee Rodin - Plan your visit","url":"https://www.musee-rodin.fr/en/plan-your-visit/plan-your-visit-musee-rodin"},{"name":"Google Maps","url":"https://maps.google.com"},{"name":"Eater - Best Restaurants in Paris","url":"https://www.eater.com/maps/best-restaurants-paris-france"},{"name":"Eater - Paris","url":"https://www.eater.com/paris"},{"name":"The Infatuation - Paris","url":"https://www.theinfatuation.com/paris"},{"name":"The Infatuation - Le Marais","url":"https://www.theinfatuation.com/paris/neighborhoods/le-marais"},{"name":"MICHELIN Guide - Paris restaurants","url":"https://guide.michelin.com/us/en/ile-de-france/paris/restaurants"},{"name":"Time Out - Paris restaurants","url":"https://www.timeout.com/paris/en/restaurants"},{"name":"Google Maps","url":"https://maps.google.com"},{"name":"Ville de Paris - Parc des Buttes-Chaumont","url":"https://www.paris.fr/equipements/parc-des-buttes-chaumont-1757"},{"name":"Ville de Paris - Coulee verte Rene Dumont","url":"https://www.paris.fr/lieux/coulee-verte-rene-dumont-1772"},{"name":"Ville de Paris - Pere-Lachaise","url":"https://www.paris.fr/lieux/cimetiere-du-pere-lachaise-4080"},{"name":"Paris je t''aime - Pere-Lachaise","url":"https://parisjetaime.com/eng/paris-museum-monument/71470/Cimetiere-du-Pere-Lachaise"},{"name":"Louvre - Tuileries Garden hours","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-le-marais-restaurants', 'paris-le-marais-restaurants', 'Food', 'France', 'Paris', 'Le Marais', '{"id":"list-paris-le-marais-restaurants","slug":"paris-le-marais-restaurants","seoSlug":"best-restaurants","seoTitle":"Best Restaurants in Le Marais, Paris","seoDescription":"Best restaurants in Le Marais, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Old-Quarter Meals With a Point","description":"Le Marais food works when each stop has a job: a bistro, falafel counter, market lunch, or polished wine-led room. This guide keeps the old quarter from becoming only boutiques, dessert lines, and vague cafe wandering.","url":"https://www.google.com/maps/search/Le%20Marais%20Restaurants%20Paris","category":"Food","location":{"city":"Paris","neighborhood":"Le Marais","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-food","name":"R Food","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"marais-food-bistrot-tournelles","name":"Bistrot des Tournelles","coordinates":[48.8555,2.366],"description":"Bistrot des Tournelles is the Marais bistro pick for travelers who want a real sit-down meal near Place des Vosges. The throwback room and classic plates make it useful when the neighborhood needs dinner, not just snacks.","price":"$$","priceSource":"The Infatuation / Google Maps","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-bistrot-des-tournelles"},{"id":"marais-food-las-fallafel","name":"L''As du Fallafel","coordinates":[48.8574,2.3591],"description":"L''As du Fallafel is the Rue des Rosiers counter stop that still deserves a save because it solves a different Marais meal: fast, iconic, and better treated as a focused lunch or snack than a full restaurant plan.","price":"$","priceSource":"The Infatuation / Google Maps","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-l-as-du-fallafel"},{"id":"marais-food-parcelles","name":"Parcelles","coordinates":[48.8612,2.3568],"description":"Parcelles is the polished bistro choice for a Marais meal that should feel current but still French. It fits travelers who want a reservation, wine, and careful cooking without leaving the gallery-and-boutique route.","price":"$$$","priceSource":"The Infatuation / Google Maps","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-parcelles"},{"id":"marais-food-enfants-rouges","name":"Marche des Enfants Rouges","coordinates":[48.8627,2.3612],"description":"Marche des Enfants Rouges gives the guide a flexible market format for casual lunches and uneven appetites. Treat it as a grazing stop with neighborhood texture rather than a quiet meal.","price":"$","priceSource":"Eater / Google Maps","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-marche-des-enfants-rouges"}],"sources":[{"name":"Eater - Best Restaurants in Paris","url":"https://www.eater.com/maps/best-restaurants-paris-france"},{"name":"Eater - Paris","url":"https://www.eater.com/paris"},{"name":"The Infatuation - Paris","url":"https://www.theinfatuation.com/paris"},{"name":"The Infatuation - Le Marais","url":"https://www.theinfatuation.com/paris/neighborhoods/le-marais"},{"name":"MICHELIN Guide - Paris restaurants","url":"https://guide.michelin.com/us/en/ile-de-france/paris/restaurants"},{"name":"Time Out - Paris restaurants","url":"https://www.timeout.com/paris/en/restaurants"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-le-marais-bars', 'paris-le-marais-bars', 'Nightlife', 'France', 'Paris', 'Le Marais', '{"id":"list-paris-le-marais-bars","slug":"paris-le-marais-bars","seoSlug":"best-bars","seoTitle":"Best Bars in Le Marais, Paris","seoDescription":"Best bars in Le Marais, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Cocktails, Pubs, and Old-Quarter Rooms","description":"Le Marais nightlife works because serious cocktail rooms, pub ease, queer-friendly terraces, and late cafes sit close together. This guide keeps the night walkable around the old quarter instead of scattering drinks across Paris.","url":"https://www.google.com/maps/search/Le%20Marais%20Bars%20Paris","category":"Nightlife","location":{"city":"Paris","neighborhood":"Le Marais","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nightlife","name":"R Nightlife","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"marais-nightlife-bar-nouveau","name":"Bar Nouveau","coordinates":[48.8623,2.3579],"description":"Bar Nouveau is the Art Nouveau cocktail trophy with World 50 Best recognition and a small-room format that rewards early timing. Use it for one focused drink before the night spreads into dinner or another bar.","price":"$$$","priceSource":"World''s 50 Best Bars / Google Maps","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-bar-nouveau"},{"id":"marais-nightlife-cambridge","name":"The Cambridge Public House","coordinates":[48.8618,2.3632],"description":"The Cambridge Public House bridges pub ease and Paris cocktail precision, making it useful for groups that want serious drinks without whispery formality. It can start or end a wider Marais night.","price":"$$","priceSource":"World''s 50 Best Bars / Time Out","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-the-cambridge-public-house"},{"id":"marais-nightlife-candelaria","name":"Candelaria","coordinates":[48.8631,2.3615],"description":"Candelaria keeps the Marais bar route playful with a taqueria-front, cocktail-back format that still feels useful near Rue de Saintonge. Save it when the night needs food-adjacent energy and a hidden-room mood.","price":"$$","priceSource":"Time Out / Google Maps","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-candelaria"},{"id":"marais-nightlife-la-perle","name":"La Perle","coordinates":[48.8608,2.3614],"description":"La Perle is the sidewalk-crowd Marais standby for a looser drink between galleries, dinner, and late wandering. Its value is social texture and location, not a perfectly quiet cocktail.","price":"$$","priceSource":"Time Out / Google Maps","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-la-perle"}],"sources":[{"name":"The World''s 50 Best Bars - Bar Nouveau","url":"https://www.theworlds50best.com/bars/the-list/bar-nouveau.html"},{"name":"The World''s 50 Best Bars - The Cambridge Public House","url":"https://www.theworlds50best.com/bars/the-list/the-cambridge-public-house.html"},{"name":"The World''s 50 Best Bars - Danico","url":"https://www.theworlds50best.com/bars/the-list/danico.html"},{"name":"Time Out - Best cocktail bars in Paris","url":"https://www.timeout.com/paris/en/bars-pubs/best-cocktail-bars-in-paris"},{"name":"Time Out - Canal Saint-Martin bars","url":"https://www.timeout.com/paris/en/bars-pubs/bars-in-canal-saint-martin-ourcq-villette"},{"name":"Visit Paris Region - La Gare / Le Gore","url":"https://www.visitparisregion.com/en/la-gare-le-gore"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-le-marais-parks-and-walks', 'paris-le-marais-parks-and-walks', 'Nature', 'France', 'Paris', 'Le Marais', '{"id":"list-paris-le-marais-parks-and-walks","slug":"paris-le-marais-parks-and-walks","seoSlug":"best-parks","seoTitle":"Best Parks and Walks in Le Marais, Paris","seoDescription":"Best parks and walks in Le Marais, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Squares and Quiet Edges Between Streets","description":"Le Marais is dense, so the useful green stops are squares, courtyards, and river edges that break up shopping and museums. This guide gives the old quarter small pauses without leaving the neighborhood route.","url":"https://www.google.com/maps/search/Le%20Marais%20Parks%20and%20Walks%20Paris","category":"Nature","location":{"city":"Paris","neighborhood":"Le Marais","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nature","name":"R Nature","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"marais-nature-place-vosges","name":"Place des Vosges","coordinates":[48.8556,2.3655],"description":"Place des Vosges is the Marais garden-square anchor, useful for a pause between arcades, Victor Hugo, Rue des Rosiers, and a bistro meal. It gives the old quarter symmetry and air.","photo":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-place-des-vosges"},{"id":"marais-nature-square-temple","name":"Square du Temple - Elie Wiesel","coordinates":[48.8648,2.3605],"description":"Square du Temple - Elie Wiesel is the north Marais green reset near Enfants Rouges and Rue de Bretagne. Use it when the route needs shade and local rhythm away from the busiest lanes.","photo":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-square-du-temple-elie-wiesel"},{"id":"marais-nature-jardin-anne-frank","name":"Jardin Anne Frank","coordinates":[48.861,2.3547],"description":"Jardin Anne Frank is a tucked-away pocket garden that helps the western Marais slow down near museums and shopping streets. It is best as a short decompression stop, not a destination park.","photo":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-jardin-anne-frank"},{"id":"marais-nature-seine-hotel-ville","name":"Seine Quays by Hotel de Ville","coordinates":[48.8567,2.3522],"description":"The Seine quays by Hotel de Ville pull Le Marais toward the river and give the neighborhood a scenic exit. Use them before crossing to the islands or looping back into the old streets.","photo":"https://images.unsplash.com/photo-1508050919630-b135583b29ab?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-seine-quays-by-hotel-de-ville"}],"sources":[{"name":"Ville de Paris - Parc des Buttes-Chaumont","url":"https://www.paris.fr/equipements/parc-des-buttes-chaumont-1757"},{"name":"Ville de Paris - Coulee verte Rene Dumont","url":"https://www.paris.fr/lieux/coulee-verte-rene-dumont-1772"},{"name":"Ville de Paris - Pere-Lachaise","url":"https://www.paris.fr/lieux/cimetiere-du-pere-lachaise-4080"},{"name":"Paris je t''aime - Pere-Lachaise","url":"https://parisjetaime.com/eng/paris-museum-monument/71470/Cimetiere-du-Pere-Lachaise"},{"name":"Louvre - Tuileries Garden hours","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-le-marais-culture', 'paris-le-marais-culture', 'Culture', 'France', 'Paris', 'Le Marais', '{"id":"list-paris-le-marais-culture","slug":"paris-le-marais-culture","seoSlug":"best-culture","seoTitle":"Best Culture in Le Marais, Paris","seoDescription":"Best culture in Le Marais, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Mansion Museums and Old-Quarter Memory","description":"Le Marais culture is built from historic houses, civic memory, courtyards, and squares rather than one blockbuster. This guide keeps Picasso, Carnavalet, Victor Hugo, and Hotel de Sully tied to a walkable old-quarter day.","url":"https://www.google.com/maps/search/Le%20Marais%20Culture%20Paris","category":"Culture","location":{"city":"Paris","neighborhood":"Le Marais","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-culture","name":"R Culture","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"marais-culture-picasso","name":"Musee Picasso Paris","coordinates":[48.8599,2.3623],"description":"Musee Picasso Paris keeps Le Marais from becoming only shopping and falafel. The Hotel Sale setting and collection depth make it a strong museum block for a neighborhood day.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-musee-picasso-paris"},{"id":"marais-culture-carnavalet","name":"Musee Carnavalet","coordinates":[48.8575,2.3629],"description":"Musee Carnavalet is the Paris-history anchor for Le Marais, with free permanent collections and a mansion setting that rewards a slower visit. Use it to add civic context before Place des Vosges or Rue des Rosiers.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-musee-carnavalet"},{"id":"marais-culture-victor-hugo","name":"Maison de Victor Hugo","coordinates":[48.8549,2.3661],"description":"Maison de Victor Hugo turns Place des Vosges into more than a pretty square, giving the route literary rooms and domestic scale. It is best as a compact cultural add-on rather than a full museum day.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-maison-de-victor-hugo"},{"id":"marais-culture-hotel-sully","name":"Hotel de Sully","coordinates":[48.8547,2.3642],"description":"Hotel de Sully gives the Marais one of its best courtyard passages and a clean hinge toward Place des Vosges. Use it when the walk needs architecture and a quieter transition.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-hotel-de-sully"}],"sources":[{"name":"Louvre - Hours and admission","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Musee d''Orsay - Visit","url":"https://www.musee-orsay.fr/en/visit"},{"name":"Paris je t''aime - Place des Vosges","url":"https://parisjetaime.com/eng/transport/place-des-vosges-p1907"},{"name":"Sacre-Coeur Montmartre official","url":"https://www.sacre-coeur-montmartre.com/"},{"name":"Paris Opera - Visit the Palais Garnier","url":"https://www.operadeparis.fr/en/visits/visit-and-explore/visit-the-palais-garnier"},{"name":"Paris Catacombs official","url":"https://www.catacombes.paris.fr/en"},{"name":"Musee Rodin - Plan your visit","url":"https://www.musee-rodin.fr/en/plan-your-visit/plan-your-visit-musee-rodin"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-le-marais-hotels-and-hostels', 'paris-le-marais-hotels-and-hostels', 'Stay', 'France', 'Paris', 'Le Marais', '{"id":"list-paris-le-marais-hotels-and-hostels","slug":"paris-le-marais-hotels-and-hostels","seoSlug":"best-hotels","seoTitle":"Best Hotels and Hostels in Le Marais, Paris","seoDescription":"Best hotels and hostels in Le Marais, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Boutique Bases in the Old Quarter","description":"Staying in Le Marais means prioritizing restaurants, bars, galleries, and walkable old-center streets over large-room calm. This guide mixes design hotels and practical budget bases that honestly serve the neighborhood.","url":"https://www.google.com/maps/search/Le%20Marais%20Hotels%20and%20Hostels%20Paris","category":"Stay","location":{"city":"Paris","neighborhood":"Le Marais","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-stay","name":"R Stay","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"marais-stay-grand-mazarin","name":"Le Grand Mazarin","coordinates":[48.858,2.3546],"description":"Le Grand Mazarin gives Le Marais a maximalist boutique stay close to Hotel de Ville, galleries, restaurants, and late bars. It suits travelers who want old-center access with design-forward energy.","price":"$$$","priceSource":"Conde Nast Traveler / Vogue","photo":"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-le-grand-mazarin"},{"id":"marais-stay-sookie","name":"Hotel Sookie","coordinates":[48.8628,2.3606],"description":"Hotel Sookie is the smaller north Marais base for travelers who want Rue de Bretagne, Enfants Rouges, and gallery streets nearby. It fits a boutique-stay trip better than a palace-service trip.","price":"$$","priceSource":"Google Travel / Tripadvisor","photo":"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-hotel-sookie"},{"id":"marais-stay-jules-jim","name":"Hotel Jules and Jim","coordinates":[48.8632,2.3567],"description":"Hotel Jules and Jim gives the upper Marais a design-hotel option with a courtyard bar and quick access to Arts et Metiers. Use it when nightlife and central movement matter.","price":"$$","priceSource":"Google Travel / Tripadvisor","photo":"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-hotel-jules-and-jim"},{"id":"marais-stay-mije","name":"MIJE Marais","coordinates":[48.8564,2.3615],"description":"MIJE Marais is the budget-friendly historic-house option for travelers who want the old quarter without hotel pricing. It works best for simple rooms, school-group energy, and maximum location value.","price":"$","priceSource":"Hostelworld / Google Maps","photo":"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-mije-marais"}],"sources":[{"name":"Conde Nast Traveler - Best hotels in Paris","url":"https://www.cntraveler.com/gallery/best-hotels-in-paris"},{"name":"Hostelworld - Paris hostels","url":"https://www.hostelworld.com/hostels/Paris"},{"name":"The Times - Best hotels in Paris 2026","url":"https://www.thetimes.com/travel/destinations/europe-travel/france/paris/best-hotels-in-paris-65dngr3zt"},{"name":"Tripadvisor - Paris hotels","url":"https://www.tripadvisor.com/Hotels-g187147-Paris_Ile_de_France-Hotels.html"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-le-marais-things-to-do', 'paris-le-marais-things-to-do', 'Activities', 'France', 'Paris', 'Le Marais', '{"id":"list-paris-le-marais-things-to-do","slug":"paris-le-marais-things-to-do","seoSlug":"best-things-to-do","seoTitle":"Best Things to Do in Le Marais, Paris","seoDescription":"Best things to do in Le Marais, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Old Streets, Squares, and Late Stops","description":"Le Marais activities are about density: a mansion museum, a square, food streets, boutiques, and a bar can all fit without transit. This guide turns the neighborhood into a flexible half-day or evening route.","url":"https://www.google.com/maps/search/Le%20Marais%20Things%20to%20Do%20Paris","category":"Activities","location":{"city":"Paris","neighborhood":"Le Marais","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-activities","name":"R Activities","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"marais-activity-vosges-picasso","name":"Place des Vosges to Musee Picasso","coordinates":[48.8578,2.364],"description":"Place des Vosges to Musee Picasso is the classic Marais culture walk, pairing a square, mansion museum, and old streets. Use it as the backbone of a daytime route.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-place-des-vosges-to-musee-picasso"},{"id":"marais-activity-rue-rosiers","name":"Rue des Rosiers Food Walk","coordinates":[48.8574,2.3591],"description":"Rue des Rosiers turns a Marais wander into a food-and-history stop with falafel counters, bakeries, and Jewish-quarter context. It is best as a focused lunch or snack block.","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-rue-des-rosiers-food-walk"},{"id":"marais-activity-rue-bretagne","name":"Rue de Bretagne and Enfants Rouges","coordinates":[48.8627,2.3612],"description":"Rue de Bretagne and Enfants Rouges keep the north Marais useful for market grazing, shopping, and cafe stops. Use it when the route needs flexible pacing.","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-rue-de-bretagne-and-enfants-rouges"},{"id":"marais-activity-cocktail-loop","name":"Marais Cocktail Loop","coordinates":[48.862,2.36],"description":"The Marais cocktail loop links Bar Nouveau, Cambridge, Candelaria, and sidewalk cafes without requiring a cross-town night. It works when dinner and drinks should stay close.","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-marais-cocktail-loop"}],"sources":[{"name":"Louvre - Hours and admission","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Musee d''Orsay - Visit","url":"https://www.musee-orsay.fr/en/visit"},{"name":"Paris je t''aime - Place des Vosges","url":"https://parisjetaime.com/eng/transport/place-des-vosges-p1907"},{"name":"Sacre-Coeur Montmartre official","url":"https://www.sacre-coeur-montmartre.com/"},{"name":"Paris Opera - Visit the Palais Garnier","url":"https://www.operadeparis.fr/en/visits/visit-and-explore/visit-the-palais-garnier"},{"name":"Paris Catacombs official","url":"https://www.catacombes.paris.fr/en"},{"name":"Musee Rodin - Plan your visit","url":"https://www.musee-rodin.fr/en/plan-your-visit/plan-your-visit-musee-rodin"},{"name":"Google Maps","url":"https://maps.google.com"},{"name":"Eater - Best Restaurants in Paris","url":"https://www.eater.com/maps/best-restaurants-paris-france"},{"name":"Eater - Paris","url":"https://www.eater.com/paris"},{"name":"The Infatuation - Paris","url":"https://www.theinfatuation.com/paris"},{"name":"The Infatuation - Le Marais","url":"https://www.theinfatuation.com/paris/neighborhoods/le-marais"},{"name":"MICHELIN Guide - Paris restaurants","url":"https://guide.michelin.com/us/en/ile-de-france/paris/restaurants"},{"name":"Time Out - Paris restaurants","url":"https://www.timeout.com/paris/en/restaurants"},{"name":"Google Maps","url":"https://maps.google.com"},{"name":"Ville de Paris - Parc des Buttes-Chaumont","url":"https://www.paris.fr/equipements/parc-des-buttes-chaumont-1757"},{"name":"Ville de Paris - Coulee verte Rene Dumont","url":"https://www.paris.fr/lieux/coulee-verte-rene-dumont-1772"},{"name":"Ville de Paris - Pere-Lachaise","url":"https://www.paris.fr/lieux/cimetiere-du-pere-lachaise-4080"},{"name":"Paris je t''aime - Pere-Lachaise","url":"https://parisjetaime.com/eng/paris-museum-monument/71470/Cimetiere-du-Pere-Lachaise"},{"name":"Louvre - Tuileries Garden hours","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-saint-germain-des-pres-restaurants', 'paris-saint-germain-des-pres-restaurants', 'Food', 'France', 'Paris', 'Saint-Germain-des-Pres', '{"id":"list-paris-saint-germain-des-pres-restaurants","slug":"paris-saint-germain-des-pres-restaurants","seoSlug":"best-restaurants","seoTitle":"Best Restaurants in Saint-Germain-des-Pres, Paris","seoDescription":"Best restaurants in Saint-Germain-des-Pres, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Left Bank Tables and Cafe Rituals","description":"Saint-Germain food should not be only cafe mythology. This guide gives the area meal roles: brasserie history, oysters, a modern bistro, a quick sandwich, and one iconic terrace for Left Bank days that need food with context.","url":"https://www.google.com/maps/search/Saint-Germain-des-Pres%20Restaurants%20Paris","category":"Food","location":{"city":"Paris","neighborhood":"Saint-Germain-des-Pres","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-food","name":"R Food","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"saint-germain-food-lipp","name":"Brasserie Lipp","coordinates":[48.8535,2.3332],"description":"Brasserie Lipp is the Saint-Germain institution for a literary, polished boulevard meal. It is useful when the plan wants old Left Bank atmosphere and classic cooking that can carry lunch or dinner.","price":"$$$","priceSource":"The Infatuation / Google Maps","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-brasserie-lipp"},{"id":"saint-germain-food-huitrerie-regis","name":"Huitrerie Regis","coordinates":[48.8532,2.3351],"description":"Huitrerie Regis gives Saint-Germain a precise seafood stop with oysters, white wine, and a compact room. Use it when the route needs a clean focused meal rather than a long brasserie sitting.","price":"$$","priceSource":"Eater / Google Maps","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-huitrerie-regis"},{"id":"saint-germain-food-semilla","name":"Semilla","coordinates":[48.8535,2.3374],"description":"Semilla is the modern Left Bank bistro for travelers who want Saint-Germain without only heritage rooms. It fits an evening around galleries, the river, and Odeon.","price":"$$","priceSource":"Eater / Google Maps","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-semilla"},{"id":"saint-germain-food-cafe-flore","name":"Cafe de Flore","coordinates":[48.8542,2.3322],"description":"Cafe de Flore belongs as a context stop, not because it is hidden. Use it when the traveler wants the ritual of Saint-Germain cafe history and understands that the value is room and address.","price":"$$","priceSource":"Conde Nast Traveler / Google Maps","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-cafe-de-flore"}],"sources":[{"name":"Eater - Best Restaurants in Paris","url":"https://www.eater.com/maps/best-restaurants-paris-france"},{"name":"Eater - Paris","url":"https://www.eater.com/paris"},{"name":"The Infatuation - Paris","url":"https://www.theinfatuation.com/paris"},{"name":"The Infatuation - Le Marais","url":"https://www.theinfatuation.com/paris/neighborhoods/le-marais"},{"name":"MICHELIN Guide - Paris restaurants","url":"https://guide.michelin.com/us/en/ile-de-france/paris/restaurants"},{"name":"Time Out - Paris restaurants","url":"https://www.timeout.com/paris/en/restaurants"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-saint-germain-des-pres-bars', 'paris-saint-germain-des-pres-bars', 'Nightlife', 'France', 'Paris', 'Saint-Germain-des-Pres', '{"id":"list-paris-saint-germain-des-pres-bars","slug":"paris-saint-germain-des-pres-bars","seoSlug":"best-bars","seoTitle":"Best Bars in Saint-Germain-des-Pres, Paris","seoDescription":"Best bars in Saint-Germain-des-Pres, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Left Bank Cocktails, Jazz, and Hotel Bars","description":"Saint-Germain nightlife is best when it stays elegant but not sleepy: cocktail rooms, hotel bars, market-street terraces, and cellar energy. This guide keeps the Left Bank evening close to dinner and river walks.","url":"https://www.google.com/maps/search/Saint-Germain-des-Pres%20Bars%20Paris","category":"Nightlife","location":{"city":"Paris","neighborhood":"Saint-Germain-des-Pres","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nightlife","name":"R Nightlife","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"saint-germain-nightlife-prescription","name":"Prescription Cocktail Club","coordinates":[48.8538,2.3372],"description":"Prescription Cocktail Club gives Saint-Germain a proper cocktail-room option near Odeon and Rue Mazarine. It is best when the night wants low light, careful drinks, and a short walk from dinner.","price":"$$","priceSource":"Time Out / Google Maps","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-prescription-cocktail-club"},{"id":"saint-germain-nightlife-josephine","name":"Bar Josephine","coordinates":[48.8517,2.327],"description":"Bar Josephine at Hotel Lutetia brings grand Left Bank hotel energy with live-music polish and a room that can carry the whole evening. Use it for a composed nightcap or a more dressed-up start.","price":"$$$","priceSource":"Official hotel site / Google Maps","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-bar-josephine"},{"id":"saint-germain-nightlife-bar-marche","name":"Le Bar du Marche","coordinates":[48.8532,2.3362],"description":"Le Bar du Marche is the casual terrace choice near Rue de Buci, useful when the group wants a simple drink in the middle of the Saint-Germain evening flow. It is more social hinge than destination cocktail bar.","price":"$$","priceSource":"Google Maps / local nightlife guides","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-le-bar-du-marche"},{"id":"saint-germain-nightlife-castor-club","name":"Castor Club","coordinates":[48.8539,2.3392],"description":"Castor Club gives the Left Bank a small, polished cocktail stop close to the river and Odeon. Save it for a focused drink when the night should stay intimate and walkable.","price":"$$","priceSource":"Time Out / Google Maps","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-castor-club"}],"sources":[{"name":"The World''s 50 Best Bars - Bar Nouveau","url":"https://www.theworlds50best.com/bars/the-list/bar-nouveau.html"},{"name":"The World''s 50 Best Bars - The Cambridge Public House","url":"https://www.theworlds50best.com/bars/the-list/the-cambridge-public-house.html"},{"name":"The World''s 50 Best Bars - Danico","url":"https://www.theworlds50best.com/bars/the-list/danico.html"},{"name":"Time Out - Best cocktail bars in Paris","url":"https://www.timeout.com/paris/en/bars-pubs/best-cocktail-bars-in-paris"},{"name":"Time Out - Canal Saint-Martin bars","url":"https://www.timeout.com/paris/en/bars-pubs/bars-in-canal-saint-martin-ourcq-villette"},{"name":"Visit Paris Region - La Gare / Le Gore","url":"https://www.visitparisregion.com/en/la-gare-le-gore"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-saint-germain-des-pres-parks-and-walks', 'paris-saint-germain-des-pres-parks-and-walks', 'Nature', 'France', 'Paris', 'Saint-Germain-des-Pres', '{"id":"list-paris-saint-germain-des-pres-parks-and-walks","slug":"paris-saint-germain-des-pres-parks-and-walks","seoSlug":"best-parks","seoTitle":"Best Parks and Walks in Saint-Germain-des-Pres, Paris","seoDescription":"Best parks and walks in Saint-Germain-des-Pres, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Luxembourg Chairs and River Walks","description":"Saint-Germain nature is mostly elegant pause space: Luxembourg chairs, small squares, and Seine edges. This guide keeps the Left Bank route breathable between galleries, cafes, Orsay, and dinner.","url":"https://www.google.com/maps/search/Saint-Germain-des-Pres%20Parks%20and%20Walks%20Paris","category":"Nature","location":{"city":"Paris","neighborhood":"Saint-Germain-des-Pres","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nature","name":"R Nature","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"saint-germain-nature-luxembourg","name":"Jardin du Luxembourg","coordinates":[48.8462,2.3372],"description":"Jardin du Luxembourg is the Left Bank reset that works between Saint-Germain, the Latin Quarter, and museum days. Chairs, fountains, and palace views make it a practical pause rather than a detour.","photo":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-jardin-du-luxembourg"},{"id":"saint-germain-nature-laurent-prache","name":"Square Laurent-Prache","coordinates":[48.8543,2.3342],"description":"Square Laurent-Prache is the small garden beside the church, useful when the boulevard needs a quiet minute. It works as a compact pause between cafes, shops, and the Delacroix museum.","photo":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-square-laurent-prache"},{"id":"saint-germain-nature-gabriel-pierne","name":"Square Gabriel-Pierne","coordinates":[48.8548,2.3375],"description":"Square Gabriel-Pierne gives Rue de Seine and the galleries a leafy pocket with benches and a quieter rhythm. Use it when the Left Bank walk needs shade without turning into a park visit.","photo":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-square-gabriel-pierne"},{"id":"saint-germain-nature-quai-malaquais","name":"Quai Malaquais Seine Walk","coordinates":[48.858,2.335],"description":"Quai Malaquais pulls Saint-Germain to the river, with views toward the Louvre and easy movement to Pont des Arts. It is the best reset between galleries, Orsay, and a central dinner.","photo":"https://images.unsplash.com/photo-1508050919630-b135583b29ab?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-quai-malaquais-seine-walk"}],"sources":[{"name":"Ville de Paris - Parc des Buttes-Chaumont","url":"https://www.paris.fr/equipements/parc-des-buttes-chaumont-1757"},{"name":"Ville de Paris - Coulee verte Rene Dumont","url":"https://www.paris.fr/lieux/coulee-verte-rene-dumont-1772"},{"name":"Ville de Paris - Pere-Lachaise","url":"https://www.paris.fr/lieux/cimetiere-du-pere-lachaise-4080"},{"name":"Paris je t''aime - Pere-Lachaise","url":"https://parisjetaime.com/eng/paris-museum-monument/71470/Cimetiere-du-Pere-Lachaise"},{"name":"Louvre - Tuileries Garden hours","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-saint-germain-des-pres-culture', 'paris-saint-germain-des-pres-culture', 'Culture', 'France', 'Paris', 'Saint-Germain-des-Pres', '{"id":"list-paris-saint-germain-des-pres-culture","slug":"paris-saint-germain-des-pres-culture","seoSlug":"best-culture","seoTitle":"Best Culture in Saint-Germain-des-Pres, Paris","seoDescription":"Best culture in Saint-Germain-des-Pres, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Abbey, Galleries, and Left Bank Rooms","description":"Saint-Germain culture works at a smaller scale than the Louvre: church history, artist rooms, institutions, galleries, and the river. This guide keeps the neighborhood intellectual without making it feel like homework.","url":"https://www.google.com/maps/search/Saint-Germain-des-Pres%20Culture%20Paris","category":"Culture","location":{"city":"Paris","neighborhood":"Saint-Germain-des-Pres","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-culture","name":"R Culture","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"saint-germain-culture-eglise","name":"Eglise Saint-Germain-des-Pres","coordinates":[48.8539,2.3346],"description":"Eglise Saint-Germain-des-Pres anchors the neighborhood with early-medieval depth and a direct link to the Left Bank''s name. Use it as the compact cultural start before cafes or galleries.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-eglise-saint-germain-des-pres"},{"id":"saint-germain-culture-delacroix","name":"Musee national Eugene-Delacroix","coordinates":[48.8541,2.3356],"description":"Musee national Eugene-Delacroix is a small artist-house museum that rewards a slower Saint-Germain day. It pairs naturally with the church, Rue de Furstenberg, and a cafe stop.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-musee-national-eugene-delacroix"},{"id":"saint-germain-culture-monnaie","name":"Monnaie de Paris","coordinates":[48.8567,2.3391],"description":"Monnaie de Paris gives the Seine edge an institution with exhibitions, craft history, and a strong courtyard setting. Use it when the neighborhood needs a cultural stop beyond literary cafes.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-monnaie-de-paris"},{"id":"saint-germain-culture-institut","name":"Institut de France","coordinates":[48.8572,2.3376],"description":"Institut de France is a landmark exterior and riverfront orientation point across from the Louvre. It works as a cultural marker on a gallery-and-quay walk rather than a long visit.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-institut-de-france"}],"sources":[{"name":"Louvre - Hours and admission","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Musee d''Orsay - Visit","url":"https://www.musee-orsay.fr/en/visit"},{"name":"Paris je t''aime - Place des Vosges","url":"https://parisjetaime.com/eng/transport/place-des-vosges-p1907"},{"name":"Sacre-Coeur Montmartre official","url":"https://www.sacre-coeur-montmartre.com/"},{"name":"Paris Opera - Visit the Palais Garnier","url":"https://www.operadeparis.fr/en/visits/visit-and-explore/visit-the-palais-garnier"},{"name":"Paris Catacombs official","url":"https://www.catacombes.paris.fr/en"},{"name":"Musee Rodin - Plan your visit","url":"https://www.musee-rodin.fr/en/plan-your-visit/plan-your-visit-musee-rodin"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-saint-germain-des-pres-hotels-and-hostels', 'paris-saint-germain-des-pres-hotels-and-hostels', 'Stay', 'France', 'Paris', 'Saint-Germain-des-Pres', '{"id":"list-paris-saint-germain-des-pres-hotels-and-hostels","slug":"paris-saint-germain-des-pres-hotels-and-hostels","seoSlug":"best-hotels","seoTitle":"Best Hotels and Hostels in Saint-Germain-des-Pres, Paris","seoDescription":"Best hotels and hostels in Saint-Germain-des-Pres, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Grand Left Bank and Quiet Boutique Bases","description":"Saint-Germain stays are for travelers who want cafe mornings, galleries, Luxembourg access, and calm returns after museum days. This guide balances palace heritage with smaller hotels close to the Left Bank route.","url":"https://www.google.com/maps/search/Saint-Germain-des-Pres%20Hotels%20and%20Hostels%20Paris","category":"Stay","location":{"city":"Paris","neighborhood":"Saint-Germain-des-Pres","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-stay","name":"R Stay","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"saint-germain-stay-lutetia","name":"Hotel Lutetia","coordinates":[48.8517,2.327],"description":"Hotel Lutetia is the grand Left Bank pick, useful for Saint-Germain, Orsay, Luxembourg, and polished cafe routes. Choose it when heritage and walkable calm matter more than immediate Marais nightlife.","price":"$$$","priceSource":"Conde Nast Traveler / The Times","photo":"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-hotel-lutetia"},{"id":"saint-germain-stay-relais-christine","name":"Relais Christine","coordinates":[48.8541,2.3403],"description":"Relais Christine gives Saint-Germain a tucked-away luxury base near the river and Odeon. It fits travelers who want quiet, romance, and historic-street access rather than lobby scene.","price":"$$$","priceSource":"Conde Nast Traveler / Google Travel","photo":"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-relais-christine"},{"id":"saint-germain-stay-aubusson","name":"Hotel d''Aubusson","coordinates":[48.8545,2.3396],"description":"Hotel d''Aubusson is a polished Left Bank hotel with jazz-bar energy and easy access to Rue de Buci, the Seine, and galleries. It works when the stay should support both culture and evenings.","price":"$$$","priceSource":"Google Travel / Tripadvisor","photo":"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-hotel-d-aubusson"},{"id":"saint-germain-stay-madison","name":"Madison Hotel","coordinates":[48.8534,2.3338],"description":"Madison Hotel gives the boulevard a practical boutique base beside the church and classic cafes. Use it when location, metro access, and Saint-Germain identity matter more than resort amenities.","price":"$$","priceSource":"Google Travel / Tripadvisor","photo":"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-madison-hotel"}],"sources":[{"name":"Conde Nast Traveler - Best hotels in Paris","url":"https://www.cntraveler.com/gallery/best-hotels-in-paris"},{"name":"Hostelworld - Paris hostels","url":"https://www.hostelworld.com/hostels/Paris"},{"name":"The Times - Best hotels in Paris 2026","url":"https://www.thetimes.com/travel/destinations/europe-travel/france/paris/best-hotels-in-paris-65dngr3zt"},{"name":"Tripadvisor - Paris hotels","url":"https://www.tripadvisor.com/Hotels-g187147-Paris_Ile_de_France-Hotels.html"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-saint-germain-des-pres-things-to-do', 'paris-saint-germain-des-pres-things-to-do', 'Activities', 'France', 'Paris', 'Saint-Germain-des-Pres', '{"id":"list-paris-saint-germain-des-pres-things-to-do","slug":"paris-saint-germain-des-pres-things-to-do","seoSlug":"best-things-to-do","seoTitle":"Best Things to Do in Saint-Germain-des-Pres, Paris","seoDescription":"Best things to do in Saint-Germain-des-Pres, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Cafe Rituals, Galleries, and Garden Time","description":"Saint-Germain activities are best built as a slow Left Bank sequence: coffee, church, galleries, garden, river, and dinner. This guide keeps the neighborhood polished without turning it into a postcard cafe crawl.","url":"https://www.google.com/maps/search/Saint-Germain-des-Pres%20Things%20to%20Do%20Paris","category":"Activities","location":{"city":"Paris","neighborhood":"Saint-Germain-des-Pres","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-activities","name":"R Activities","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"saint-germain-activity-cafe-abbey","name":"Cafe and Abbey Loop","coordinates":[48.854,2.334],"description":"The cafe and abbey loop links Cafe de Flore, Brasserie Lipp, and Eglise Saint-Germain-des-Pres into one compact Left Bank ritual. Use it early, before the boulevard gets too crowded.","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-cafe-and-abbey-loop"},{"id":"saint-germain-activity-rue-seine","name":"Rue de Seine Gallery Walk","coordinates":[48.8547,2.3367],"description":"Rue de Seine gives Saint-Germain a browsable gallery spine between the church and river. It works when the day needs looking, wandering, and small cultural stops without another ticket.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-rue-de-seine-gallery-walk"},{"id":"saint-germain-activity-luxembourg-odeon","name":"Luxembourg to Odeon","coordinates":[48.8488,2.339],"description":"Luxembourg to Odeon is the soft walking block that connects garden chairs, bookshops, cinemas, and dinner streets. Use it to keep the Left Bank day relaxed.","photo":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-luxembourg-to-odeon"},{"id":"saint-germain-activity-orsay-bridge","name":"Orsay Bridge Walk","coordinates":[48.8585,2.3295],"description":"The Orsay bridge walk connects Saint-Germain to the museum side through the Seine instead of the metro. It is a useful activity when art, views, and dinner need to stay aligned.","photo":"https://images.unsplash.com/photo-1508050919630-b135583b29ab?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-orsay-bridge-walk"}],"sources":[{"name":"Louvre - Hours and admission","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Musee d''Orsay - Visit","url":"https://www.musee-orsay.fr/en/visit"},{"name":"Paris je t''aime - Place des Vosges","url":"https://parisjetaime.com/eng/transport/place-des-vosges-p1907"},{"name":"Sacre-Coeur Montmartre official","url":"https://www.sacre-coeur-montmartre.com/"},{"name":"Paris Opera - Visit the Palais Garnier","url":"https://www.operadeparis.fr/en/visits/visit-and-explore/visit-the-palais-garnier"},{"name":"Paris Catacombs official","url":"https://www.catacombes.paris.fr/en"},{"name":"Musee Rodin - Plan your visit","url":"https://www.musee-rodin.fr/en/plan-your-visit/plan-your-visit-musee-rodin"},{"name":"Google Maps","url":"https://maps.google.com"},{"name":"Eater - Best Restaurants in Paris","url":"https://www.eater.com/maps/best-restaurants-paris-france"},{"name":"Eater - Paris","url":"https://www.eater.com/paris"},{"name":"The Infatuation - Paris","url":"https://www.theinfatuation.com/paris"},{"name":"The Infatuation - Le Marais","url":"https://www.theinfatuation.com/paris/neighborhoods/le-marais"},{"name":"MICHELIN Guide - Paris restaurants","url":"https://guide.michelin.com/us/en/ile-de-france/paris/restaurants"},{"name":"Time Out - Paris restaurants","url":"https://www.timeout.com/paris/en/restaurants"},{"name":"Google Maps","url":"https://maps.google.com"},{"name":"Ville de Paris - Parc des Buttes-Chaumont","url":"https://www.paris.fr/equipements/parc-des-buttes-chaumont-1757"},{"name":"Ville de Paris - Coulee verte Rene Dumont","url":"https://www.paris.fr/lieux/coulee-verte-rene-dumont-1772"},{"name":"Ville de Paris - Pere-Lachaise","url":"https://www.paris.fr/lieux/cimetiere-du-pere-lachaise-4080"},{"name":"Paris je t''aime - Pere-Lachaise","url":"https://parisjetaime.com/eng/paris-museum-monument/71470/Cimetiere-du-Pere-Lachaise"},{"name":"Louvre - Tuileries Garden hours","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-latin-quarter-restaurants', 'paris-latin-quarter-restaurants', 'Food', 'France', 'Paris', 'Latin Quarter', '{"id":"list-paris-latin-quarter-restaurants","slug":"paris-latin-quarter-restaurants","seoSlug":"best-restaurants","seoTitle":"Best Restaurants in Latin Quarter, Paris","seoDescription":"Best restaurants in Latin Quarter, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Student Streets and Serious Tables","description":"Latin Quarter food should cover more than tourist menus: bakeries, historic dining rooms, student-value plates, and one serious river-edge meal. This guide keeps meals tied to the Pantheon, Mouffetard, Cluny, and the Seine.","url":"https://www.google.com/maps/search/Latin%20Quarter%20Restaurants%20Paris","category":"Food","location":{"city":"Paris","neighborhood":"Latin Quarter","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-food","name":"R Food","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"latin-food-coupe-chou","name":"Le Coupe-Chou","coordinates":[48.8485,2.3483],"description":"Le Coupe-Chou gives the Latin Quarter a candlelit old-house meal near the Sorbonne and Pantheon. Use it when the route wants atmosphere and a slower dinner without leaving the university streets.","price":"$$","priceSource":"Google Maps / local dining guides","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-le-coupe-chou"},{"id":"latin-food-bouillon-racine","name":"Bouillon Racine","coordinates":[48.849,2.341],"description":"Bouillon Racine is the Art Nouveau dining-room choice near Odeon and Cluny, useful when the day needs a historic room at a more accessible format. It is best for groups that want setting and classic comfort.","price":"$$","priceSource":"Google Maps / local dining guides","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-bouillon-racine"},{"id":"latin-food-maison-isabelle","name":"La Maison d''Isabelle","coordinates":[48.8498,2.3486],"description":"La Maison d''Isabelle is the croissant and bakery stop that makes a Latin Quarter morning feel planned. Use it before the Pantheon, Mouffetard, or a museum block when breakfast should be quick and good.","price":"$","priceSource":"Google Maps / Paris bakery guides","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-la-maison-d-isabelle"},{"id":"latin-food-tour-argent","name":"La Tour d''Argent","coordinates":[48.8499,2.3544],"description":"La Tour d''Argent is the formal river-edge splurge for travelers who want old Paris ceremony and a view-backed meal. It belongs as a deliberate booking, not a casual neighborhood dinner.","price":"$$$","priceSource":"MICHELIN Guide / Google Maps","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-la-tour-d-argent"}],"sources":[{"name":"Eater - Best Restaurants in Paris","url":"https://www.eater.com/maps/best-restaurants-paris-france"},{"name":"Eater - Paris","url":"https://www.eater.com/paris"},{"name":"The Infatuation - Paris","url":"https://www.theinfatuation.com/paris"},{"name":"The Infatuation - Le Marais","url":"https://www.theinfatuation.com/paris/neighborhoods/le-marais"},{"name":"MICHELIN Guide - Paris restaurants","url":"https://guide.michelin.com/us/en/ile-de-france/paris/restaurants"},{"name":"Time Out - Paris restaurants","url":"https://www.timeout.com/paris/en/restaurants"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-latin-quarter-bars', 'paris-latin-quarter-bars', 'Nightlife', 'France', 'Paris', 'Latin Quarter', '{"id":"list-paris-latin-quarter-bars","slug":"paris-latin-quarter-bars","seoSlug":"best-bars","seoTitle":"Best Bars in Latin Quarter, Paris","seoDescription":"Best bars in Latin Quarter, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Cellars, Student Bars, and Late Jazz","description":"Latin Quarter nights work when the student energy and old-cellar culture are used deliberately. This guide gives the neighborhood jazz, pubs, and casual bars that fit after bookshops, dinner, or a Pantheon day.","url":"https://www.google.com/maps/search/Latin%20Quarter%20Bars%20Paris","category":"Nightlife","location":{"city":"Paris","neighborhood":"Latin Quarter","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nightlife","name":"R Nightlife","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"latin-nightlife-huchette","name":"Le Caveau de la Huchette","coordinates":[48.8525,2.3468],"description":"Le Caveau de la Huchette is the Latin Quarter jazz-cellar anchor, useful when nightlife should be music and dancing rather than another cocktail list. Check the program before building the night around it.","price":"$$","priceSource":"Official venue site / Google Maps","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-le-caveau-de-la-huchette"},{"id":"latin-nightlife-piano-vache","name":"Le Piano Vache","coordinates":[48.8503,2.3488],"description":"Le Piano Vache gives the area a student-bar institution with posters, inexpensive drinks, and a looser mood near the Sorbonne. Use it when the night should stay casual and local-feeling.","price":"$","priceSource":"Google Maps / local nightlife guides","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-le-piano-vache"},{"id":"latin-nightlife-teddys","name":"Teddy''s Bar","coordinates":[48.8473,2.3443],"description":"Teddy''s Bar is a compact cocktail and beer stop near Mouffetard, useful for a low-pressure drink after dinner. It works best as part of a small Latin Quarter bar sequence.","price":"$$","priceSource":"Google Maps / local nightlife guides","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-teddy-s-bar"},{"id":"latin-nightlife-requin","name":"Le Requin Chagrin","coordinates":[48.8465,2.3478],"description":"Le Requin Chagrin is the pub-style stop near the Pantheon and student streets, good for groups that want easy drinks without a reservation ritual. Save it for a casual second stop.","price":"$","priceSource":"Google Maps / local nightlife guides","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-le-requin-chagrin"}],"sources":[{"name":"The World''s 50 Best Bars - Bar Nouveau","url":"https://www.theworlds50best.com/bars/the-list/bar-nouveau.html"},{"name":"The World''s 50 Best Bars - The Cambridge Public House","url":"https://www.theworlds50best.com/bars/the-list/the-cambridge-public-house.html"},{"name":"The World''s 50 Best Bars - Danico","url":"https://www.theworlds50best.com/bars/the-list/danico.html"},{"name":"Time Out - Best cocktail bars in Paris","url":"https://www.timeout.com/paris/en/bars-pubs/best-cocktail-bars-in-paris"},{"name":"Time Out - Canal Saint-Martin bars","url":"https://www.timeout.com/paris/en/bars-pubs/bars-in-canal-saint-martin-ourcq-villette"},{"name":"Visit Paris Region - La Gare / Le Gore","url":"https://www.visitparisregion.com/en/la-gare-le-gore"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-latin-quarter-parks-and-walks', 'paris-latin-quarter-parks-and-walks', 'Nature', 'France', 'Paris', 'Latin Quarter', '{"id":"list-paris-latin-quarter-parks-and-walks","slug":"paris-latin-quarter-parks-and-walks","seoSlug":"best-parks","seoTitle":"Best Parks and Walks in Latin Quarter, Paris","seoDescription":"Best parks and walks in Latin Quarter, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Gardens, Arenas, and River Breathing Room","description":"The Latin Quarter has real green relief if the route steps off the lecture-hall streets. This guide links Luxembourg, Jardin des Plantes, Arenes de Lutece, and the Seine for pauses between culture and food.","url":"https://www.google.com/maps/search/Latin%20Quarter%20Parks%20and%20Walks%20Paris","category":"Nature","location":{"city":"Paris","neighborhood":"Latin Quarter","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nature","name":"R Nature","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"latin-nature-luxembourg","name":"Jardin du Luxembourg","coordinates":[48.8462,2.3372],"description":"Jardin du Luxembourg is the western green anchor for Latin Quarter days, especially before or after the Pantheon and Sorbonne. Chairs, fountains, and paths make it the easiest long pause.","photo":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-jardin-du-luxembourg"},{"id":"latin-nature-jardin-plantes","name":"Jardin des Plantes","coordinates":[48.8439,2.3599],"description":"Jardin des Plantes stretches the Latin Quarter east toward natural history, garden paths, and family-friendly museum time. It is best when the day needs greenery and a quieter rhythm.","photo":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-jardin-des-plantes"},{"id":"latin-nature-arenes","name":"Arenes de Lutece","coordinates":[48.8451,2.3522],"description":"Arenes de Lutece gives the neighborhood a Roman open-air pocket tucked behind ordinary streets. Use it as a short historical and green stop between Mouffetard and Jardin des Plantes.","photo":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-arenes-de-lutece"},{"id":"latin-nature-seine-bookstalls","name":"Seine Bookstalls and Quays","coordinates":[48.8527,2.347],"description":"The Seine bookstalls and quays are the Latin Quarter''s river reset, linking Shakespeare and Company, Notre-Dame views, and slow browsing. It is the easiest way to add air to a bookish route.","photo":"https://images.unsplash.com/photo-1508050919630-b135583b29ab?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-seine-bookstalls-and-quays"}],"sources":[{"name":"Ville de Paris - Parc des Buttes-Chaumont","url":"https://www.paris.fr/equipements/parc-des-buttes-chaumont-1757"},{"name":"Ville de Paris - Coulee verte Rene Dumont","url":"https://www.paris.fr/lieux/coulee-verte-rene-dumont-1772"},{"name":"Ville de Paris - Pere-Lachaise","url":"https://www.paris.fr/lieux/cimetiere-du-pere-lachaise-4080"},{"name":"Paris je t''aime - Pere-Lachaise","url":"https://parisjetaime.com/eng/paris-museum-monument/71470/Cimetiere-du-Pere-Lachaise"},{"name":"Louvre - Tuileries Garden hours","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-latin-quarter-culture', 'paris-latin-quarter-culture', 'Culture', 'France', 'Paris', 'Latin Quarter', '{"id":"list-paris-latin-quarter-culture","slug":"paris-latin-quarter-culture","seoSlug":"best-culture","seoTitle":"Best Culture in Latin Quarter, Paris","seoDescription":"Best culture in Latin Quarter, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Books, Domes, and Medieval Rooms","description":"The Latin Quarter deserves its own cultural map because university streets, bookshops, medieval rooms, civic monuments, and gardens sit close enough to walk. Use this for history without turning the day into lectures and plaques.","url":"https://www.google.com/maps/search/Latin%20Quarter%20Culture%20Paris","category":"Culture","location":{"city":"Paris","neighborhood":"Latin Quarter","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-culture","name":"R Culture","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"latin-culture-pantheon","name":"Pantheon","coordinates":[48.8462,2.346],"description":"The Pantheon is the Latin Quarter''s civic-history anchor, connecting republican memory, architecture, and the Sorbonne-side street grid. It is best paired with Luxembourg or Cluny rather than rushed as a dome photo.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-pantheon"},{"id":"latin-culture-cluny","name":"Musee de Cluny","coordinates":[48.8506,2.3431],"description":"Musee de Cluny is the medieval counterweight to the big art museums, with tapestries, Roman bath remains, and a scale that suits a slower Left Bank day. It is useful when the group needs culture without Louvre sprawl.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-musee-de-cluny"},{"id":"latin-culture-shakespeare","name":"Shakespeare and Company","coordinates":[48.8526,2.3471],"description":"Shakespeare and Company is touristy for a reason, but it still gives the Latin Quarter its English-language literary stop near Notre-Dame and the Seine. Save it for a short browse and river walk.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-shakespeare-and-company"},{"id":"latin-culture-sorbonne","name":"Place de la Sorbonne","coordinates":[48.8487,2.3437],"description":"Place de la Sorbonne turns the area''s academic identity into a simple walking anchor. It works as connective tissue between the Pantheon, cafes, bookshops, and Luxembourg.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-place-de-la-sorbonne"}],"sources":[{"name":"Louvre - Hours and admission","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Musee d''Orsay - Visit","url":"https://www.musee-orsay.fr/en/visit"},{"name":"Paris je t''aime - Place des Vosges","url":"https://parisjetaime.com/eng/transport/place-des-vosges-p1907"},{"name":"Sacre-Coeur Montmartre official","url":"https://www.sacre-coeur-montmartre.com/"},{"name":"Paris Opera - Visit the Palais Garnier","url":"https://www.operadeparis.fr/en/visits/visit-and-explore/visit-the-palais-garnier"},{"name":"Paris Catacombs official","url":"https://www.catacombes.paris.fr/en"},{"name":"Musee Rodin - Plan your visit","url":"https://www.musee-rodin.fr/en/plan-your-visit/plan-your-visit-musee-rodin"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-latin-quarter-hotels-and-hostels', 'paris-latin-quarter-hotels-and-hostels', 'Stay', 'France', 'Paris', 'Latin Quarter', '{"id":"list-paris-latin-quarter-hotels-and-hostels","slug":"paris-latin-quarter-hotels-and-hostels","seoSlug":"best-hotels","seoTitle":"Best Hotels and Hostels in Latin Quarter, Paris","seoDescription":"Best hotels and hostels in Latin Quarter, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Bookish Bases Near the Pantheon","description":"Latin Quarter stays work for travelers who want student streets, bookshops, gardens, and easy RER or metro access. This guide balances boutique hotels, older quiet rooms, and one budget base that honestly serves the area.","url":"https://www.google.com/maps/search/Latin%20Quarter%20Hotels%20and%20Hostels%20Paris","category":"Stay","location":{"city":"Paris","neighborhood":"Latin Quarter","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-stay","name":"R Stay","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"latin-stay-dames-pantheon","name":"Hotel Les Dames du Pantheon","coordinates":[48.846,2.3459],"description":"Hotel Les Dames du Pantheon is the location-first boutique stay with Pantheon views and direct access to the Sorbonne side. It fits travelers who want literary Left Bank mood and short walks.","price":"$$","priceSource":"Google Travel / Tripadvisor","photo":"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-hotel-les-dames-du-pantheon"},{"id":"latin-stay-grandes-ecoles","name":"Hotel des Grandes Ecoles","coordinates":[48.8434,2.3509],"description":"Hotel des Grandes Ecoles gives the Latin Quarter a courtyard-garden hotel near Mouffetard. Use it when calm, charm, and neighborhood feel matter more than large luxury services.","price":"$$","priceSource":"Google Travel / Tripadvisor","photo":"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-hotel-des-grandes-ecoles"},{"id":"latin-stay-monte-cristo","name":"Hotel Monte Cristo","coordinates":[48.8377,2.3523],"description":"Hotel Monte Cristo is the southern Latin Quarter boutique base with a more styled, tucked-away mood. It works for travelers who want access to Mouffetard, Jardin des Plantes, and quieter nights.","price":"$$","priceSource":"Google Travel / Tripadvisor","photo":"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-hotel-monte-cristo"},{"id":"latin-stay-young-happy","name":"Young and Happy Latin Quarter","coordinates":[48.8446,2.3507],"description":"Young and Happy Latin Quarter is the budget hostel pick for travelers who want Mouffetard, student bars, and simple access to the Pantheon area. It is strongest for social, low-cost stays.","price":"$","priceSource":"Hostelworld / Google Maps","photo":"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-young-and-happy-latin-quarter"}],"sources":[{"name":"Conde Nast Traveler - Best hotels in Paris","url":"https://www.cntraveler.com/gallery/best-hotels-in-paris"},{"name":"Hostelworld - Paris hostels","url":"https://www.hostelworld.com/hostels/Paris"},{"name":"The Times - Best hotels in Paris 2026","url":"https://www.thetimes.com/travel/destinations/europe-travel/france/paris/best-hotels-in-paris-65dngr3zt"},{"name":"Tripadvisor - Paris hotels","url":"https://www.tripadvisor.com/Hotels-g187147-Paris_Ile_de_France-Hotels.html"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-latin-quarter-things-to-do', 'paris-latin-quarter-things-to-do', 'Activities', 'France', 'Paris', 'Latin Quarter', '{"id":"list-paris-latin-quarter-things-to-do","slug":"paris-latin-quarter-things-to-do","seoSlug":"best-things-to-do","seoTitle":"Best Things to Do in Latin Quarter, Paris","seoDescription":"Best things to do in Latin Quarter, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"A Bookish Left Bank Day","description":"Latin Quarter activities should move between books, civic history, gardens, and student streets. This guide turns the neighborhood into a walkable day with culture, browsing, food, and river edges.","url":"https://www.google.com/maps/search/Latin%20Quarter%20Things%20to%20Do%20Paris","category":"Activities","location":{"city":"Paris","neighborhood":"Latin Quarter","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-activities","name":"R Activities","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"latin-activity-pantheon-cluny","name":"Pantheon and Cluny Route","coordinates":[48.8484,2.3447],"description":"The Pantheon and Cluny route gives the Latin Quarter its civic and medieval backbone in one compact walk. Use it when the day needs two strong cultural anchors without cross-town travel.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-pantheon-and-cluny-route"},{"id":"latin-activity-bookshops-seine","name":"Bookshops and the Seine","coordinates":[48.8526,2.3471],"description":"Bookshops and the Seine link Shakespeare and Company, bouquinistes, Notre-Dame views, and river walking. It is the classic short activity when the neighborhood needs romance and browsing.","photo":"https://images.unsplash.com/photo-1508050919630-b135583b29ab?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-bookshops-and-the-seine"},{"id":"latin-activity-jardin-plantes","name":"Jardin des Plantes Afternoon","coordinates":[48.8439,2.3599],"description":"A Jardin des Plantes afternoon adds gardens, natural-history museums, and family-friendly pacing to the Latin Quarter. It works especially well after dense historic streets.","photo":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-jardin-des-plantes-afternoon"},{"id":"latin-activity-mouffetard","name":"Rue Mouffetard Food Walk","coordinates":[48.8427,2.3494],"description":"Rue Mouffetard gives the area a market-street activity with bakeries, cheese shops, cafes, and casual dinner options. Use it when the day needs food texture rather than another ticket.","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-rue-mouffetard-food-walk"}],"sources":[{"name":"Louvre - Hours and admission","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Musee d''Orsay - Visit","url":"https://www.musee-orsay.fr/en/visit"},{"name":"Paris je t''aime - Place des Vosges","url":"https://parisjetaime.com/eng/transport/place-des-vosges-p1907"},{"name":"Sacre-Coeur Montmartre official","url":"https://www.sacre-coeur-montmartre.com/"},{"name":"Paris Opera - Visit the Palais Garnier","url":"https://www.operadeparis.fr/en/visits/visit-and-explore/visit-the-palais-garnier"},{"name":"Paris Catacombs official","url":"https://www.catacombes.paris.fr/en"},{"name":"Musee Rodin - Plan your visit","url":"https://www.musee-rodin.fr/en/plan-your-visit/plan-your-visit-musee-rodin"},{"name":"Google Maps","url":"https://maps.google.com"},{"name":"Eater - Best Restaurants in Paris","url":"https://www.eater.com/maps/best-restaurants-paris-france"},{"name":"Eater - Paris","url":"https://www.eater.com/paris"},{"name":"The Infatuation - Paris","url":"https://www.theinfatuation.com/paris"},{"name":"The Infatuation - Le Marais","url":"https://www.theinfatuation.com/paris/neighborhoods/le-marais"},{"name":"MICHELIN Guide - Paris restaurants","url":"https://guide.michelin.com/us/en/ile-de-france/paris/restaurants"},{"name":"Time Out - Paris restaurants","url":"https://www.timeout.com/paris/en/restaurants"},{"name":"Google Maps","url":"https://maps.google.com"},{"name":"Ville de Paris - Parc des Buttes-Chaumont","url":"https://www.paris.fr/equipements/parc-des-buttes-chaumont-1757"},{"name":"Ville de Paris - Coulee verte Rene Dumont","url":"https://www.paris.fr/lieux/coulee-verte-rene-dumont-1772"},{"name":"Ville de Paris - Pere-Lachaise","url":"https://www.paris.fr/lieux/cimetiere-du-pere-lachaise-4080"},{"name":"Paris je t''aime - Pere-Lachaise","url":"https://parisjetaime.com/eng/paris-museum-monument/71470/Cimetiere-du-Pere-Lachaise"},{"name":"Louvre - Tuileries Garden hours","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-montmartre-restaurants', 'paris-montmartre-restaurants', 'Food', 'France', 'Paris', 'Montmartre', '{"id":"list-paris-montmartre-restaurants","slug":"paris-montmartre-restaurants","seoSlug":"best-restaurants","seoTitle":"Best Restaurants in Montmartre, Paris","seoDescription":"Best restaurants in Montmartre, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Hill Meals Beyond the View","description":"Montmartre food is strongest when the meal has a purpose: a poultry room, a tiny bistro, a brunch stop, or a village-street dinner. This guide keeps the hill from becoming only crepes, views, and souvenir lanes.","url":"https://www.google.com/maps/search/Montmartre%20Restaurants%20Paris","category":"Food","location":{"city":"Paris","neighborhood":"Montmartre","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-food","name":"R Food","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"montmartre-food-coq-fils","name":"Le Coq and Fils","coordinates":[48.887,2.3383],"description":"Le Coq and Fils gives Montmartre a poultry-focused destination meal near the upper hill without leaning on postcard atmosphere alone. Use it for a planned lunch or dinner after the museum lanes.","price":"$$$","priceSource":"MICHELIN Guide / Google Maps","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-le-coq-and-fils"},{"id":"montmartre-food-boite-lettres","name":"La Boite aux Lettres","coordinates":[48.8878,2.3356],"description":"La Boite aux Lettres is the small bistro pick for travelers who want a neighborhood dinner near Lamarck-Caulaincourt. It works when the hill needs warmth, wine, and a room that feels local.","price":"$$","priceSource":"Google Maps / Paris dining guides","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-la-boite-aux-lettres"},{"id":"montmartre-food-hardware","name":"Hardware Societe","coordinates":[48.886,2.3438],"description":"Hardware Societe is the brunch and coffee stop that makes a Sacre-Coeur morning more useful. It is best before the crowds thicken or after an early hill walk.","price":"$$","priceSource":"Google Maps / local dining guides","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-hardware-societe"},{"id":"montmartre-food-poulbot","name":"Le Poulbot","coordinates":[48.8866,2.3404],"description":"Le Poulbot gives the central hill a compact French meal close to Place du Tertre without fully surrendering to the tourist strip. Use it when staying on the summit matters.","price":"$$","priceSource":"Google Maps / local dining guides","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-le-poulbot"}],"sources":[{"name":"Eater - Best Restaurants in Paris","url":"https://www.eater.com/maps/best-restaurants-paris-france"},{"name":"Eater - Paris","url":"https://www.eater.com/paris"},{"name":"The Infatuation - Paris","url":"https://www.theinfatuation.com/paris"},{"name":"The Infatuation - Le Marais","url":"https://www.theinfatuation.com/paris/neighborhoods/le-marais"},{"name":"MICHELIN Guide - Paris restaurants","url":"https://guide.michelin.com/us/en/ile-de-france/paris/restaurants"},{"name":"Time Out - Paris restaurants","url":"https://www.timeout.com/paris/en/restaurants"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-montmartre-bars', 'paris-montmartre-bars', 'Nightlife', 'France', 'Paris', 'Montmartre', '{"id":"list-paris-montmartre-bars","slug":"paris-montmartre-bars","seoSlug":"best-bars","seoTitle":"Best Bars in Montmartre, Paris","seoDescription":"Best bars in Montmartre, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Hilltop Nightcaps and Old Cabaret Energy","description":"Montmartre nights work when they lean into the hill: rooftop views, old cabaret rooms, intimate hotel bars, and lower-hill dives. This guide keeps after-dark plans tied to the neighborhood''s slope and mood.","url":"https://www.google.com/maps/search/Montmartre%20Bars%20Paris","category":"Nightlife","location":{"city":"Paris","neighborhood":"Montmartre","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nightlife","name":"R Nightlife","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"montmartre-nightlife-terrass","name":"Terrass Hotel Rooftop","coordinates":[48.8852,2.3326],"description":"Terrass Hotel Rooftop gives Montmartre a view-led drink without climbing back to the basilica steps. Use it for sunset, an early aperitif, or a calmer nightcap on the west side of the hill.","price":"$$$","priceSource":"Official hotel site / Google Maps","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-terrass-hotel-rooftop"},{"id":"montmartre-nightlife-lapin-agile","name":"Au Lapin Agile","coordinates":[48.8888,2.3401],"description":"Au Lapin Agile is the historic cabaret stop that keeps Montmartre connected to song, performance, and artist lore. Check the schedule and treat it as a planned show, not a drop-in bar.","price":"$$","priceSource":"Official venue site / Google Maps","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-au-lapin-agile"},{"id":"montmartre-nightlife-tres-particulier","name":"Le Tres Particulier","coordinates":[48.8882,2.3339],"description":"Le Tres Particulier is the hidden cocktail bar inside Hotel Particulier Montmartre, useful when the night wants garden secrecy and a more refined hilltop mood. Book or confirm access before relying on it.","price":"$$$","priceSource":"Official hotel site / Google Maps","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-le-tres-particulier"},{"id":"montmartre-nightlife-marlusse","name":"Marlusse et Lapin","coordinates":[48.8842,2.3364],"description":"Marlusse et Lapin is the lower-hill bar for a looser, playful drink near Abbesses. It works when Montmartre should end social and casual rather than polished.","price":"$$","priceSource":"Google Maps / local nightlife guides","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-marlusse-et-lapin"}],"sources":[{"name":"The World''s 50 Best Bars - Bar Nouveau","url":"https://www.theworlds50best.com/bars/the-list/bar-nouveau.html"},{"name":"The World''s 50 Best Bars - The Cambridge Public House","url":"https://www.theworlds50best.com/bars/the-list/the-cambridge-public-house.html"},{"name":"The World''s 50 Best Bars - Danico","url":"https://www.theworlds50best.com/bars/the-list/danico.html"},{"name":"Time Out - Best cocktail bars in Paris","url":"https://www.timeout.com/paris/en/bars-pubs/best-cocktail-bars-in-paris"},{"name":"Time Out - Canal Saint-Martin bars","url":"https://www.timeout.com/paris/en/bars-pubs/bars-in-canal-saint-martin-ourcq-villette"},{"name":"Visit Paris Region - La Gare / Le Gore","url":"https://www.visitparisregion.com/en/la-gare-le-gore"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-montmartre-parks-and-walks', 'paris-montmartre-parks-and-walks', 'Nature', 'France', 'Paris', 'Montmartre', '{"id":"list-paris-montmartre-parks-and-walks","slug":"paris-montmartre-parks-and-walks","seoSlug":"best-parks","seoTitle":"Best Parks and Walks in Montmartre, Paris","seoDescription":"Best parks and walks in Montmartre, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Steps, Slopes, and Quiet Hill Corners","description":"Montmartre''s outdoor value is slope, view, and small green pockets rather than big parks. This guide links the basilica steps, squares, cemetery paths, and quieter hill corners into a route with real pauses.","url":"https://www.google.com/maps/search/Montmartre%20Parks%20and%20Walks%20Paris","category":"Nature","location":{"city":"Paris","neighborhood":"Montmartre","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nature","name":"R Nature","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"montmartre-nature-sacre-steps","name":"Sacre-Coeur Steps","coordinates":[48.8867,2.3431],"description":"The Sacre-Coeur steps are the obvious view point, but they work best early or late when the hill has room to breathe. Use them as a timed outdoor stop, not an all-day hangout.","photo":"https://images.unsplash.com/photo-1539650116574-75c0c6d73f6e?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-sacre-coeur-steps"},{"id":"montmartre-nature-louise-michel","name":"Square Louise Michel","coordinates":[48.8846,2.3443],"description":"Square Louise Michel gives the climb to Sacre-Coeur a garden frame, with switchback paths, lawns, and changing city views. It is useful when the route needs a slower ascent.","photo":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-square-louise-michel"},{"id":"montmartre-nature-suzanne-buisson","name":"Square Suzanne Buisson","coordinates":[48.8886,2.3369],"description":"Square Suzanne Buisson is a quieter green pocket on the back side of the hill, away from the busiest summit lanes. Use it between Lamarck-Caulaincourt and the old mills.","photo":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-square-suzanne-buisson"},{"id":"montmartre-nature-cemetery","name":"Cimetiere de Montmartre","coordinates":[48.8875,2.3306],"description":"Cimetiere de Montmartre adds a leafy, reflective walk below the hill and works as a calmer counterpoint to Sacre-Coeur crowds. It is best for a slow route toward Pigalle or Rue Caulaincourt.","photo":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-cimetiere-de-montmartre"}],"sources":[{"name":"Ville de Paris - Parc des Buttes-Chaumont","url":"https://www.paris.fr/equipements/parc-des-buttes-chaumont-1757"},{"name":"Ville de Paris - Coulee verte Rene Dumont","url":"https://www.paris.fr/lieux/coulee-verte-rene-dumont-1772"},{"name":"Ville de Paris - Pere-Lachaise","url":"https://www.paris.fr/lieux/cimetiere-du-pere-lachaise-4080"},{"name":"Paris je t''aime - Pere-Lachaise","url":"https://parisjetaime.com/eng/paris-museum-monument/71470/Cimetiere-du-Pere-Lachaise"},{"name":"Louvre - Tuileries Garden hours","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-montmartre-culture', 'paris-montmartre-culture', 'Culture', 'France', 'Paris', 'Montmartre', '{"id":"list-paris-montmartre-culture","slug":"paris-montmartre-culture","seoSlug":"best-culture","seoTitle":"Best Culture in Montmartre, Paris","seoDescription":"Best culture in Montmartre, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Hilltop Views Without the Rush","description":"Montmartre needs a guide because the famous stops can overwhelm the village texture. This route keeps Sacre-Coeur, artist history, old mills, and quieter lanes together without turning the hill into a photo queue.","url":"https://www.google.com/maps/search/Montmartre%20Culture%20Paris","category":"Culture","location":{"city":"Paris","neighborhood":"Montmartre","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-culture","name":"R Culture","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"montmartre-culture-sacre-coeur","name":"Basilique du Sacre-Coeur","coordinates":[48.8867,2.3431],"description":"Sacre-Coeur is the hilltop anchor, but the best visit treats the basilica, dome, steps, and view as one timed block. Go early or late, then leave room for side streets.","photo":"https://images.unsplash.com/photo-1539650116574-75c0c6d73f6e?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-basilique-du-sacre-coeur"},{"id":"montmartre-culture-musee-montmartre","name":"Musee de Montmartre","coordinates":[48.8872,2.3408],"description":"Musee de Montmartre gives the hill context beyond the basilica, with artist history, gardens, and a calmer pace near the busiest lanes. It is useful when the route needs texture instead of another viewpoint.","photo":"https://images.unsplash.com/photo-1539650116574-75c0c6d73f6e?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-musee-de-montmartre"},{"id":"montmartre-culture-place-tertre","name":"Place du Tertre","coordinates":[48.8865,2.3407],"description":"Place du Tertre is crowded and commercial, but it still explains the neighborhood''s artist-brand mythology. Pass through briefly, then use it as a hinge toward quieter lanes.","photo":"https://images.unsplash.com/photo-1539650116574-75c0c6d73f6e?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-place-du-tertre"},{"id":"montmartre-culture-moulin-galette","name":"Moulin de la Galette","coordinates":[48.8873,2.3367],"description":"Moulin de la Galette helps turn Montmartre from postcard into neighborhood history: mills, artists, and winding streets. Use it as a walking marker between Lamarck-Caulaincourt, Abbesses, and the summit.","photo":"https://images.unsplash.com/photo-1539650116574-75c0c6d73f6e?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-moulin-de-la-galette"}],"sources":[{"name":"Louvre - Hours and admission","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Musee d''Orsay - Visit","url":"https://www.musee-orsay.fr/en/visit"},{"name":"Paris je t''aime - Place des Vosges","url":"https://parisjetaime.com/eng/transport/place-des-vosges-p1907"},{"name":"Sacre-Coeur Montmartre official","url":"https://www.sacre-coeur-montmartre.com/"},{"name":"Paris Opera - Visit the Palais Garnier","url":"https://www.operadeparis.fr/en/visits/visit-and-explore/visit-the-palais-garnier"},{"name":"Paris Catacombs official","url":"https://www.catacombes.paris.fr/en"},{"name":"Musee Rodin - Plan your visit","url":"https://www.musee-rodin.fr/en/plan-your-visit/plan-your-visit-musee-rodin"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-montmartre-hotels-and-hostels', 'paris-montmartre-hotels-and-hostels', 'Stay', 'France', 'Paris', 'Montmartre', '{"id":"list-paris-montmartre-hotels-and-hostels","slug":"paris-montmartre-hotels-and-hostels","seoSlug":"best-hotels","seoTitle":"Best Hotels and Hostels in Montmartre, Paris","seoDescription":"Best hotels and hostels in Montmartre, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Hilltop Hotels and Social Budget Bases","description":"Montmartre stays are for travelers who want village streets, north-side evenings, and views more than central monument access. This guide balances rooftop hotels, small boutiques, and hostel bases near the hill.","url":"https://www.google.com/maps/search/Montmartre%20Hotels%20and%20Hostels%20Paris","category":"Stay","location":{"city":"Paris","neighborhood":"Montmartre","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-stay","name":"R Stay","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"montmartre-stay-terrass","name":"Terrass Hotel","coordinates":[48.8852,2.3326],"description":"Terrass Hotel is the view-led Montmartre stay with rooftop drinks and easy access to Rue Caulaincourt and Abbesses. Use it when the hill should shape mornings and evenings.","price":"$$$","priceSource":"Conde Nast Traveler / Google Travel","photo":"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-terrass-hotel"},{"id":"montmartre-stay-arts","name":"Hotel des Arts Montmartre","coordinates":[48.8853,2.3348],"description":"Hotel des Arts Montmartre is a smaller neighborhood hotel close to Abbesses, restaurants, and hill walks. It fits travelers who want Montmartre charm without a big hotel scene.","price":"$$","priceSource":"Google Travel / Tripadvisor","photo":"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-hotel-des-arts-montmartre"},{"id":"montmartre-stay-village","name":"Le Village Montmartre","coordinates":[48.8842,2.3446],"description":"Le Village Montmartre is the hostel base near Anvers and Sacre-Coeur for budget travelers who want the hill within minutes. It works for simple dorms or privates with social energy.","price":"$","priceSource":"Hostelworld / HostelsClub","photo":"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-le-village-montmartre"},{"id":"montmartre-stay-momart","name":"Mom''Art Hotel","coordinates":[48.8846,2.3432],"description":"Mom''Art Hotel gives the lower hill a compact boutique option near Anvers and Sacre-Coeur. Use it when convenience to the climb matters more than a quiet residential pocket.","price":"$$","priceSource":"Google Travel / Tripadvisor","photo":"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-mom-art-hotel"}],"sources":[{"name":"Conde Nast Traveler - Best hotels in Paris","url":"https://www.cntraveler.com/gallery/best-hotels-in-paris"},{"name":"Hostelworld - Paris hostels","url":"https://www.hostelworld.com/hostels/Paris"},{"name":"The Times - Best hotels in Paris 2026","url":"https://www.thetimes.com/travel/destinations/europe-travel/france/paris/best-hotels-in-paris-65dngr3zt"},{"name":"Tripadvisor - Paris hotels","url":"https://www.tripadvisor.com/Hotels-g187147-Paris_Ile_de_France-Hotels.html"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-montmartre-things-to-do', 'paris-montmartre-things-to-do', 'Activities', 'France', 'Paris', 'Montmartre', '{"id":"list-paris-montmartre-things-to-do","slug":"paris-montmartre-things-to-do","seoSlug":"best-things-to-do","seoTitle":"Best Things to Do in Montmartre, Paris","seoDescription":"Best things to do in Montmartre, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"A Hill Walk With Timing","description":"Montmartre activities need timing because the famous lanes crowd quickly. This guide builds the hill as a route: basilica, museum, old streets, lower-hill cafes, and an evening that does not depend on one viewpoint.","url":"https://www.google.com/maps/search/Montmartre%20Things%20to%20Do%20Paris","category":"Activities","location":{"city":"Paris","neighborhood":"Montmartre","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-activities","name":"R Activities","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"montmartre-activity-sacre-sunrise","name":"Sacre-Coeur Early or Late","coordinates":[48.8867,2.3431],"description":"Sacre-Coeur early or late is the best way to make the hill feel spacious rather than hectic. Use the timing to pair the basilica, steps, and view with quieter lanes.","photo":"https://images.unsplash.com/photo-1539650116574-75c0c6d73f6e?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-sacre-coeur-early-or-late"},{"id":"montmartre-activity-artist-lanes","name":"Musee de Montmartre and Artist Lanes","coordinates":[48.8872,2.3408],"description":"Musee de Montmartre and the artist lanes give the neighborhood context beyond Place du Tertre. It is a useful activity block for travelers who want history with the walk.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-musee-de-montmartre-and-artist-lanes"},{"id":"montmartre-activity-abbesses-lamarck","name":"Abbesses to Lamarck-Caulaincourt","coordinates":[48.886,2.3365],"description":"Abbesses to Lamarck-Caulaincourt is the calmer slope walk through cafes, shops, and back-of-hill streets. Use it when the route needs Montmartre texture without staying on the summit.","photo":"https://images.unsplash.com/photo-1539650116574-75c0c6d73f6e?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-abbesses-to-lamarck-caulaincourt"},{"id":"montmartre-activity-cabaret-night","name":"Cabaret and Hill Night","coordinates":[48.8888,2.3401],"description":"A cabaret and hill night uses Au Lapin Agile, rooftop drinks, or lower-hill bars to keep Montmartre after dark. It works when the evening is planned around a show or view.","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-cabaret-and-hill-night"}],"sources":[{"name":"Louvre - Hours and admission","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Musee d''Orsay - Visit","url":"https://www.musee-orsay.fr/en/visit"},{"name":"Paris je t''aime - Place des Vosges","url":"https://parisjetaime.com/eng/transport/place-des-vosges-p1907"},{"name":"Sacre-Coeur Montmartre official","url":"https://www.sacre-coeur-montmartre.com/"},{"name":"Paris Opera - Visit the Palais Garnier","url":"https://www.operadeparis.fr/en/visits/visit-and-explore/visit-the-palais-garnier"},{"name":"Paris Catacombs official","url":"https://www.catacombes.paris.fr/en"},{"name":"Musee Rodin - Plan your visit","url":"https://www.musee-rodin.fr/en/plan-your-visit/plan-your-visit-musee-rodin"},{"name":"Google Maps","url":"https://maps.google.com"},{"name":"Eater - Best Restaurants in Paris","url":"https://www.eater.com/maps/best-restaurants-paris-france"},{"name":"Eater - Paris","url":"https://www.eater.com/paris"},{"name":"The Infatuation - Paris","url":"https://www.theinfatuation.com/paris"},{"name":"The Infatuation - Le Marais","url":"https://www.theinfatuation.com/paris/neighborhoods/le-marais"},{"name":"MICHELIN Guide - Paris restaurants","url":"https://guide.michelin.com/us/en/ile-de-france/paris/restaurants"},{"name":"Time Out - Paris restaurants","url":"https://www.timeout.com/paris/en/restaurants"},{"name":"Google Maps","url":"https://maps.google.com"},{"name":"Ville de Paris - Parc des Buttes-Chaumont","url":"https://www.paris.fr/equipements/parc-des-buttes-chaumont-1757"},{"name":"Ville de Paris - Coulee verte Rene Dumont","url":"https://www.paris.fr/lieux/coulee-verte-rene-dumont-1772"},{"name":"Ville de Paris - Pere-Lachaise","url":"https://www.paris.fr/lieux/cimetiere-du-pere-lachaise-4080"},{"name":"Paris je t''aime - Pere-Lachaise","url":"https://parisjetaime.com/eng/paris-museum-monument/71470/Cimetiere-du-Pere-Lachaise"},{"name":"Louvre - Tuileries Garden hours","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-canal-saint-martin-restaurants', 'paris-canal-saint-martin-restaurants', 'Food', 'France', 'Paris', 'Canal Saint-Martin', '{"id":"list-paris-canal-saint-martin-restaurants","slug":"paris-canal-saint-martin-restaurants","seoSlug":"best-restaurants","seoTitle":"Best Restaurants in Canal Saint-Martin, Paris","seoDescription":"Best restaurants in Canal Saint-Martin, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Bakery Mornings and Canal Tables","description":"Canal Saint-Martin food is best when it follows the water: bakery starts, brunch queues, rotating kitchens, and terrace meals. This guide keeps the meal plan walkable along the locks and north-south canal spine.","url":"https://www.google.com/maps/search/Canal%20Saint-Martin%20Restaurants%20Paris","category":"Food","location":{"city":"Paris","neighborhood":"Canal Saint-Martin","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-food","name":"R Food","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"canal-food-du-pain","name":"Du Pain et des Idees","coordinates":[48.8719,2.3622],"description":"Du Pain et des Idees is the bakery stop that makes canal mornings feel intentional. Use it for pastries and bread before the locks, Republique, or a north Marais route.","price":"$","priceSource":"Eater / Google Maps","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-du-pain-et-des-idees"},{"id":"canal-food-holybelly","name":"Holybelly 5","coordinates":[48.8723,2.3606],"description":"Holybelly 5 is the brunch-and-coffee anchor near the canal, useful when the morning needs a proper seated meal before walking. Expect demand and build timing around it.","price":"$$","priceSource":"Google Maps / Paris dining guides","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-holybelly-5"},{"id":"canal-food-early-june","name":"Early June","coordinates":[48.8739,2.3621],"description":"Early June gives the canal a wine-led, rotating-kitchen meal that feels current and neighborhood-specific. Save it for travelers who like seasonal plates and a less formal dinner rhythm.","price":"$$","priceSource":"Eater / Google Maps","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-early-june"},{"id":"canal-food-chez-prune","name":"Chez Prune","coordinates":[48.8726,2.3634],"description":"Chez Prune is the canal-side cafe standby for lunch, aperitif, or a simple meal with the water close by. Its value is meeting-point energy and location rather than culinary surprise.","price":"$$","priceSource":"Time Out / Google Maps","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-chez-prune"}],"sources":[{"name":"Eater - Best Restaurants in Paris","url":"https://www.eater.com/maps/best-restaurants-paris-france"},{"name":"Eater - Paris","url":"https://www.eater.com/paris"},{"name":"The Infatuation - Paris","url":"https://www.theinfatuation.com/paris"},{"name":"The Infatuation - Le Marais","url":"https://www.theinfatuation.com/paris/neighborhoods/le-marais"},{"name":"MICHELIN Guide - Paris restaurants","url":"https://guide.michelin.com/us/en/ile-de-france/paris/restaurants"},{"name":"Time Out - Paris restaurants","url":"https://www.timeout.com/paris/en/restaurants"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-canal-saint-martin-bars', 'paris-canal-saint-martin-bars', 'Nightlife', 'France', 'Paris', 'Canal Saint-Martin', '{"id":"list-paris-canal-saint-martin-bars","slug":"paris-canal-saint-martin-bars","seoSlug":"best-bars","seoTitle":"Best Bars in Canal Saint-Martin, Paris","seoDescription":"Best bars in Canal Saint-Martin, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Canal Drinks With a Route","description":"Canal Saint-Martin nights are strongest when they stay walkable: one proper cocktail, a music terrace, an atmospheric indoor bar, and a casual meeting-point cafe. The guide keeps the canal from becoming only bank-side wandering.","url":"https://www.google.com/maps/search/Canal%20Saint-Martin%20Bars%20Paris","category":"Nightlife","location":{"city":"Paris","neighborhood":"Canal Saint-Martin","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nightlife","name":"R Nightlife","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"canal-nightlife-gravity","name":"Gravity Bar","coordinates":[48.8728,2.3622],"description":"Gravity Bar is the cocktail stop for a canal night that wants design and sharper drinks before the route loosens up. It is best for a focused first drink near Rue des Vinaigriers.","price":"$$","priceSource":"Time Out / Google Maps","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-gravity-bar"},{"id":"canal-nightlife-la-meduse","name":"La Meduse","coordinates":[48.8791,2.3671],"description":"La Meduse gives the canal a cocktail-and-natural-wine option right by the water, with enough food to keep the evening flexible. Use it when the night should stay canal-side but still feel deliberate.","price":"$$","priceSource":"Time Out / Google Maps","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-la-meduse"},{"id":"canal-nightlife-point-ephemere","name":"Point Ephemere","coordinates":[48.8819,2.3686],"description":"Point Ephemere gives the canal a music, terrace, and art-space anchor farther north. It works when the night needs programming or a looser crowd instead of another polished cocktail room.","price":"$$","priceSource":"Time Out / Google Maps","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-point-ephemere"},{"id":"canal-nightlife-comptoir-general","name":"Le Comptoir General","coordinates":[48.8727,2.3638],"description":"Le Comptoir General is the eclectic canal room for groups that want decor, drinks, and a moodier indoor option after the banks get crowded. It is best saved for atmosphere-forward evenings.","price":"$$","priceSource":"Time Out / Google Maps","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-le-comptoir-general"}],"sources":[{"name":"The World''s 50 Best Bars - Bar Nouveau","url":"https://www.theworlds50best.com/bars/the-list/bar-nouveau.html"},{"name":"The World''s 50 Best Bars - The Cambridge Public House","url":"https://www.theworlds50best.com/bars/the-list/the-cambridge-public-house.html"},{"name":"The World''s 50 Best Bars - Danico","url":"https://www.theworlds50best.com/bars/the-list/danico.html"},{"name":"Time Out - Best cocktail bars in Paris","url":"https://www.timeout.com/paris/en/bars-pubs/best-cocktail-bars-in-paris"},{"name":"Time Out - Canal Saint-Martin bars","url":"https://www.timeout.com/paris/en/bars-pubs/bars-in-canal-saint-martin-ourcq-villette"},{"name":"Visit Paris Region - La Gare / Le Gore","url":"https://www.visitparisregion.com/en/la-gare-le-gore"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-canal-saint-martin-parks-and-walks', 'paris-canal-saint-martin-parks-and-walks', 'Nature', 'France', 'Paris', 'Canal Saint-Martin', '{"id":"list-paris-canal-saint-martin-parks-and-walks","slug":"paris-canal-saint-martin-parks-and-walks","seoSlug":"best-parks","seoTitle":"Best Parks and Walks in Canal Saint-Martin, Paris","seoDescription":"Best parks and walks in Canal Saint-Martin, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Locks, Banks, and East-Side Air","description":"Canal Saint-Martin''s outdoor value is linear: locks, bridges, pocket gardens, and a walk north toward wider water. This guide gives the neighborhood air without pretending it is a park district.","url":"https://www.google.com/maps/search/Canal%20Saint-Martin%20Parks%20and%20Walks%20Paris","category":"Nature","location":{"city":"Paris","neighborhood":"Canal Saint-Martin","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nature","name":"R Nature","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"canal-nature-locks","name":"Canal Saint-Martin Locks","coordinates":[48.8721,2.3648],"description":"The Canal Saint-Martin locks are the neighborhood''s outdoor spine, turning a simple walk into a sequence of bridges, water, and street corners. Use them between bakery, lunch, and evening drinks.","photo":"https://images.unsplash.com/photo-1511739001486-6bfe10ce785f?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-canal-saint-martin-locks"},{"id":"canal-nature-villemin","name":"Jardin Villemin","coordinates":[48.8764,2.3614],"description":"Jardin Villemin gives the canal a practical green pause near Gare de l''Est and the central banks. It is useful for shade, families, or a break from narrow sidewalks.","photo":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-jardin-villemin"},{"id":"canal-nature-frederic-lemaitre","name":"Square Frederic-Lemaitre","coordinates":[48.871,2.367],"description":"Square Frederic-Lemaitre is a small green stop by the canal and Republique edge, helpful when the route needs a quieter bench between bars and water. It is a pause, not a destination.","photo":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-square-frederic-lemaitre"},{"id":"canal-nature-bassin-villette","name":"Bassin de la Villette","coordinates":[48.884,2.371],"description":"Bassin de la Villette extends the canal walk into wider water, picnic edges, and summer activity. Use it when the route can continue north instead of looping back immediately.","photo":"https://images.unsplash.com/photo-1511739001486-6bfe10ce785f?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-bassin-de-la-villette"}],"sources":[{"name":"Ville de Paris - Parc des Buttes-Chaumont","url":"https://www.paris.fr/equipements/parc-des-buttes-chaumont-1757"},{"name":"Ville de Paris - Coulee verte Rene Dumont","url":"https://www.paris.fr/lieux/coulee-verte-rene-dumont-1772"},{"name":"Ville de Paris - Pere-Lachaise","url":"https://www.paris.fr/lieux/cimetiere-du-pere-lachaise-4080"},{"name":"Paris je t''aime - Pere-Lachaise","url":"https://parisjetaime.com/eng/paris-museum-monument/71470/Cimetiere-du-Pere-Lachaise"},{"name":"Louvre - Tuileries Garden hours","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-canal-saint-martin-culture', 'paris-canal-saint-martin-culture', 'Culture', 'France', 'Paris', 'Canal Saint-Martin', '{"id":"list-paris-canal-saint-martin-culture","slug":"paris-canal-saint-martin-culture","seoSlug":"best-culture","seoTitle":"Best Culture in Canal Saint-Martin, Paris","seoDescription":"Best culture in Canal Saint-Martin, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Art Spaces, Courtyards, and Republique Edges","description":"Canal Saint-Martin culture is informal: music rooms, event spaces, old hospital courtyards, and civic squares. This guide keeps the neighborhood''s creative stops tied to the water and evening route.","url":"https://www.google.com/maps/search/Canal%20Saint-Martin%20Culture%20Paris","category":"Culture","location":{"city":"Paris","neighborhood":"Canal Saint-Martin","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-culture","name":"R Culture","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"canal-culture-point-ephemere","name":"Point Ephemere","coordinates":[48.8819,2.3686],"description":"Point Ephemere is the canal''s art-and-music anchor, with exhibitions, concerts, and terrace energy beside the water. Check the program before making it the center of the route.","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-point-ephemere"},{"id":"canal-culture-comptoir-general","name":"Le Comptoir General","coordinates":[48.8727,2.3638],"description":"Le Comptoir General works as a cultural room as much as a bar, with decor, events, and an atmospheric courtyard feel. Use it for a night that wants setting and social energy.","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-le-comptoir-general"},{"id":"canal-culture-hopital-saint-louis","name":"Hopital Saint-Louis Courtyard","coordinates":[48.8738,2.3687],"description":"The Hopital Saint-Louis courtyard is a historic architectural pause close to the canal, useful for travelers who want a quieter layer of the neighborhood. Respect access rules and keep the stop brief.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-hopital-saint-louis-courtyard"},{"id":"canal-culture-republique","name":"Place de la Republique","coordinates":[48.8675,2.363],"description":"Place de la Republique gives the canal route civic scale and a clear southern meeting point. It works as orientation before moving north toward the locks and bars.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-place-de-la-republique"}],"sources":[{"name":"Louvre - Hours and admission","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Musee d''Orsay - Visit","url":"https://www.musee-orsay.fr/en/visit"},{"name":"Paris je t''aime - Place des Vosges","url":"https://parisjetaime.com/eng/transport/place-des-vosges-p1907"},{"name":"Sacre-Coeur Montmartre official","url":"https://www.sacre-coeur-montmartre.com/"},{"name":"Paris Opera - Visit the Palais Garnier","url":"https://www.operadeparis.fr/en/visits/visit-and-explore/visit-the-palais-garnier"},{"name":"Paris Catacombs official","url":"https://www.catacombes.paris.fr/en"},{"name":"Musee Rodin - Plan your visit","url":"https://www.musee-rodin.fr/en/plan-your-visit/plan-your-visit-musee-rodin"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-canal-saint-martin-hotels-and-hostels', 'paris-canal-saint-martin-hotels-and-hostels', 'Stay', 'France', 'Paris', 'Canal Saint-Martin', '{"id":"list-paris-canal-saint-martin-hotels-and-hostels","slug":"paris-canal-saint-martin-hotels-and-hostels","seoSlug":"best-hotels","seoTitle":"Best Hotels and Hostels in Canal Saint-Martin, Paris","seoDescription":"Best hotels and hostels in Canal Saint-Martin, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Canal Hotels and Social Bases","description":"Staying around Canal Saint-Martin is about east-side food, bars, train access, and social energy. This guide mixes canal-facing hotels, design hostels, and practical bases that serve the waterline route.","url":"https://www.google.com/maps/search/Canal%20Saint-Martin%20Hotels%20and%20Hostels%20Paris","category":"Stay","location":{"city":"Paris","neighborhood":"Canal Saint-Martin","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-stay","name":"R Stay","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"canal-stay-citizen","name":"Le Citizen Hotel","coordinates":[48.8726,2.3643],"description":"Le Citizen Hotel is the canal-facing boutique stay for travelers who want the water, cafes, and bars directly outside. It is best when the canal is the daily base, not just one evening plan.","price":"$$","priceSource":"Google Travel / Tripadvisor","photo":"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-le-citizen-hotel"},{"id":"canal-stay-generator","name":"Generator Paris","coordinates":[48.8795,2.3696],"description":"Generator Paris is the design-hostel option near Canal Saint-Martin, with dorms, private rooms, and social common spaces. It fits budget travelers who value canal access over old-city charm.","price":"$","priceSource":"Hostelworld / Google Maps","photo":"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-generator-paris"},{"id":"canal-stay-providence","name":"Hotel Providence","coordinates":[48.8701,2.3568],"description":"Hotel Providence gives the canal-Republique edge a design-led hotel with strong food and bar access nearby. Use it when the stay should bridge the canal, the 10th, and central Right Bank routes.","price":"$$$","priceSource":"Conde Nast Traveler / Google Travel","photo":"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-hotel-providence"},{"id":"canal-stay-st-christophers","name":"St Christopher''s Inn Canal","coordinates":[48.8868,2.3756],"description":"St Christopher''s Inn Canal is the larger social-hostel base north on the waterline, useful for budget travelers who want dorms, events, and Villette access. It is more canal extension than old-center stay.","price":"$","priceSource":"Hostelworld / Google Maps","photo":"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-st-christopher-s-inn-canal"}],"sources":[{"name":"Conde Nast Traveler - Best hotels in Paris","url":"https://www.cntraveler.com/gallery/best-hotels-in-paris"},{"name":"Hostelworld - Paris hostels","url":"https://www.hostelworld.com/hostels/Paris"},{"name":"The Times - Best hotels in Paris 2026","url":"https://www.thetimes.com/travel/destinations/europe-travel/france/paris/best-hotels-in-paris-65dngr3zt"},{"name":"Tripadvisor - Paris hotels","url":"https://www.tripadvisor.com/Hotels-g187147-Paris_Ile_de_France-Hotels.html"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-canal-saint-martin-things-to-do', 'paris-canal-saint-martin-things-to-do', 'Activities', 'France', 'Paris', 'Canal Saint-Martin', '{"id":"list-paris-canal-saint-martin-things-to-do","slug":"paris-canal-saint-martin-things-to-do","seoSlug":"best-things-to-do","seoTitle":"Best Things to Do in Canal Saint-Martin, Paris","seoDescription":"Best things to do in Canal Saint-Martin, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"A Waterline Day Into Night","description":"Canal Saint-Martin activities work as a sequence: bakery, locks, shopping streets, Republique, wider water, and music or drinks. This guide keeps the day linear so the neighborhood feels easy to follow.","url":"https://www.google.com/maps/search/Canal%20Saint-Martin%20Things%20to%20Do%20Paris","category":"Activities","location":{"city":"Paris","neighborhood":"Canal Saint-Martin","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-activities","name":"R Activities","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"canal-activity-bakery-locks","name":"Bakery and Locks Morning","coordinates":[48.8721,2.3648],"description":"A bakery and locks morning starts at Du Pain et des Idees, then follows bridges and water north. It is the easiest way to make the canal feel like a route, not a single photo stop.","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-bakery-and-locks-morning"},{"id":"canal-activity-vinaigriers","name":"Rue des Vinaigriers and Canal Shops","coordinates":[48.873,2.362],"description":"Rue des Vinaigriers and the canal shops give the neighborhood a browsing spine with cafes, small retailers, and bars nearby. Use it between brunch and aperitif.","photo":"https://images.unsplash.com/photo-1511739001486-6bfe10ce785f?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-rue-des-vinaigriers-and-canal-shops"},{"id":"canal-activity-republique-canal","name":"Republique to the Canal","coordinates":[48.8675,2.363],"description":"Republique to the canal is the practical southern approach, linking a major square to quieter bridges and water. It works when friends need an easy meeting point before wandering.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-republique-to-the-canal"},{"id":"canal-activity-point-ephemere-night","name":"Point Ephemere Night","coordinates":[48.8819,2.3686],"description":"A Point Ephemere night turns the canal into music, terrace, and late programming. Check the event calendar and build dinner or drinks around the show rather than hoping something is on.","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-point-ephemere-night"}],"sources":[{"name":"Louvre - Hours and admission","url