  ('list-rome-centro-storico-culture', 'rome-centro-storico-culture', 'Culture', 'Italy', 'Rome', 'Centro Storico', '{"id":"list-rome-centro-storico-culture","slug":"rome-centro-storico-culture","seoSlug":"best-culture","seoTitle":"Best Culture in Centro Storico, Rome","seoDescription":"Best culture in Centro Storico, Rome, selected for neighborhood fit, current source support, and useful saved-map routing.","title":"Piazzas, Domes, and Palace Rooms","description":"Centro culture is dense enough to blur; this guide uses a few anchors to make the historic core readable without chasing every church facade.","url":"https://www.google.com/maps/search/Centro%20Storico%20Culture%20Rome","category":"Culture","location":{"city":"Rome","neighborhood":"Centro Storico","country":"Italy","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-culture","name":"R Culture","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"centro-pantheon","name":"Pantheon","coordinates":[41.8986,12.4769],"description":"The Pantheon is the essential Centro Storico stop because it explains Roman engineering, church continuity, and piazza life in one short visit. The experience gives the area more context than a surface-level walk, whether through architecture, collections, street history, or a quieter interior. Check current opening days and ticket needs, then place it where the route can slow down enough to absorb it.","photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Pantheon_Rom_1_cropped.jpg","hours":{"default":"Hours vary; confirm current opening times before visiting."},"poiId":"poi-italy-rome-pantheon"},{"id":"centro-piazza-navona","name":"Piazza Navona","coordinates":[41.8992,12.4731],"description":"Piazza Navona gives the route Baroque theater and everyday central-Rome pressure at once. Use it as a connector between churches, cafes, and side streets.","photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Piazza_Navona%2C_Rome.jpg","hours":{"default":"Hours vary; confirm current opening times before visiting."},"poiId":"poi-italy-rome-piazza-navona"},{"id":"centro-trevi","name":"Trevi Fountain","coordinates":[41.9009,12.4833],"description":"Trevi Fountain belongs because even the crowds tell the truth about Rome''s spectacle. Go early or late and treat it as one beat, not the whole route.","photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Trevi_Fountain%2C_Rome%2C_Italy_2_-_May_2007.jpg","hours":{"default":"Hours vary; confirm current opening times before visiting."},"poiId":"poi-italy-rome-trevi-fountain"},{"id":"centro-doria","name":"Galleria Doria Pamphilj","coordinates":[41.8976,12.4813],"description":"Galleria Doria Pamphilj adds palace interiors and painting depth to a neighborhood otherwise dominated by outdoor icons. It is a strong bad-weather or heat escape.","photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Ceiling_in_Galleria_Doria_Pamphilj_(Rome).jpg","hours":{"default":"Hours vary; confirm current opening times before visiting."},"poiId":"poi-italy-rome-galleria-doria-pamphilj"}],"sources":[{"name":"Turismo Roma","url":"https://www.turismoroma.it/en"},{"name":"Parco archeologico del Colosseo","url":"https://colosseo.it/en/"},{"name":"Vatican Museums","url":"https://www.museivaticani.va/content/museivaticani/en.html"},{"name":"Time Out - Things to do in Rome","url":"https://www.timeout.com/rome/things-to-do"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-rome-trastevere-culture', 'rome-trastevere-culture', 'Culture', 'Italy', 'Rome', 'Trastevere', '{"id":"list-rome-trastevere-culture","slug":"rome-trastevere-culture","seoSlug":"best-culture","seoTitle":"Best Culture in Trastevere, Rome","seoDescription":"Best culture in Trastevere, Rome, selected for neighborhood fit, current source support, and useful saved-map routing.","title":"Mosaics, Frescoes, and Quiet Gardens","description":"Trastevere culture works best when it balances famous atmosphere with real interiors: basilica mosaics, villa frescoes, social history, and green space.","url":"https://www.google.com/maps/search/Trastevere%20Culture%20Rome","category":"Culture","location":{"city":"Rome","neighborhood":"Trastevere","country":"Italy","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-culture","name":"R Culture","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"trastevere-santa-maria","name":"Basilica di Santa Maria in Trastevere","coordinates":[41.8894,12.4698],"description":"Santa Maria in Trastevere is the neighborhood''s cultural anchor, with mosaics, piazza life, and a scale that fits before dinner or drinks. The draw is the way the church turns Trastevere from atmosphere into history, especially if you slow down inside instead of only crossing the piazza. Confirm open hours and dress expectations before planning it as the route''s main interior stop.","photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Exterior_Santa_Maria_in_Trastevere.jpg","hours":{"default":"Hours vary; confirm current opening times before visiting."},"poiId":"poi-italy-rome-basilica-di-santa-maria-in-trastevere"},{"id":"trastevere-villa-farnesina","name":"Villa Farnesina","coordinates":[41.8931,12.4677],"description":"Villa Farnesina brings Renaissance frescoes and a calmer cultural stop to Trastevere. It works especially well before a Janiculum or Botanical Garden walk.","photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Villa_Farnesina%2C_Rome.jpg","hours":{"default":"Hours vary; confirm current opening times before visiting."},"poiId":"poi-italy-rome-villa-farnesina"},{"id":"trastevere-museo-roma","name":"Museo di Roma in Trastevere","coordinates":[41.8898,12.4717],"description":"Museo di Roma in Trastevere gives the area social-history context instead of leaving it as only pretty lanes and nightlife. It is compact enough for a neighborhood route.","photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Trastevere.JPG","hours":{"default":"Hours vary; confirm current opening times before visiting."},"poiId":"poi-italy-rome-museo-di-roma-in-trastevere"},{"id":"trastevere-botanical","name":"Orto Botanico di Roma","coordinates":[41.8933,12.4664],"description":"The Botanical Garden sits on the edge of Trastevere and gives the guide a shaded cultural-landscape stop when the streets feel too tight. The experience gives the area more context than a surface-level walk, whether through architecture, collections, street history, or a quieter interior. Check current opening days and ticket needs, then place it where the route can slow down enough to absorb it.","photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Orto_botanico_-_ingresso_2704.JPG","hours":{"default":"Hours vary; confirm current opening times before visiting."},"poiId":"poi-italy-rome-orto-botanico-di-roma"}],"sources":[{"name":"Turismo Roma","url":"https://www.turismoroma.it/en"},{"name":"Parco archeologico del Colosseo","url":"https://colosseo.it/en/"},{"name":"Vatican Museums","url":"https://www.museivaticani.va/content/museivaticani/en.html"},{"name":"Time Out - Things to do in Rome","url":"https://www.timeout.com/rome/things-to-do"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-rome-monti-culture', 'rome-monti-culture', 'Culture', 'Italy', 'Rome', 'Monti', '{"id":"list-rome-monti-culture","slug":"rome-monti-culture","seoSlug":"best-culture","seoTitle":"Best Culture in Monti, Rome","seoDescription":"Best culture in Monti, Rome, selected for neighborhood fit, current source support, and useful saved-map routing.","title":"Basilicas and Buried Rome","description":"Monti''s culture guide connects imperial remains, major churches, and exhibition space so the area does not become only a Colosseum approach.","url":"https://www.google.com/maps/search/Monti%20Culture%20Rome","category":"Culture","location":{"city":"Rome","neighborhood":"Monti","country":"Italy","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-culture","name":"R Culture","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"monti-santa-maria-maggiore","name":"Basilica Papale di Santa Maria Maggiore","coordinates":[41.8975,12.4985],"description":"Santa Maria Maggiore gives Monti one of Rome''s major basilica interiors, making the neighborhood more than a shopping-and-dinner pocket. The value is its scale, mosaics, and position between Termini and Monti, which can anchor a route before smaller churches or food stops. Confirm current access rules and give the interior enough time to register.","photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Basilica_Papale_di_Santa_Maria_Maggiore_02.jpg","hours":{"default":"Hours vary; confirm current opening times before visiting."},"poiId":"poi-italy-rome-basilica-papale-di-santa-maria-maggiore"},{"id":"monti-domus-aurea","name":"Domus Aurea","coordinates":[41.8903,12.4955],"description":"Domus Aurea is the deep-history Monti stop, best for travelers who want imperial Rome below the surface rather than only the Colosseum exterior. The value is the guided archaeological format, which makes Nero''s palace feel legible instead of abstract. Check current tour days and ticket availability before building the route around it.","photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Colosseo_2020.jpg","hours":{"default":"Hours vary; confirm current opening times before visiting."},"poiId":"poi-italy-rome-domus-aurea"},{"id":"monti-san-pietro-vincoli","name":"San Pietro in Vincoli","coordinates":[41.8932,12.4922],"description":"San Pietro in Vincoli earns a saved-map spot for Michelangelo''s Moses and the way it hides major art on a quieter Monti slope. The value is its role in the route: it adds a concrete experience, a timing choice, and a reason to save the stop rather than wander past it. Check current hours and fit it into the nearby cluster instead of treating it as a standalone errand.","photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Michelangelo''s_Moses.jpg","hours":{"default":"Hours vary; confirm current opening times before visiting."},"poiId":"poi-italy-rome-san-pietro-in-vincoli"},{"id":"monti-palazzo-esposizioni","name":"Palazzo delle Esposizioni","coordinates":[41.8992,12.4902],"description":"Palazzo delle Esposizioni gives Monti a contemporary exhibition counterweight to ancient and church-heavy routes. The experience gives the area more context than a surface-level walk, whether through architecture, collections, street history, or a quieter interior. Check current opening days and ticket needs, then place it where the route can slow down enough to absorb it.","photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Palazzo_delle_Esposizioni.jpg","hours":{"default":"Hours vary; confirm current opening times before visiting."},"poiId":"poi-italy-rome-palazzo-delle-esposizioni"}],"sources":[{"name":"Turismo Roma","url":"https://www.turismoroma.it/en"},{"name":"Parco archeologico del Colosseo","url":"https://colosseo.it/en/"},{"name":"Vatican Museums","url":"https://www.museivaticani.va/content/museivaticani/en.html"},{"name":"Time Out - Things to do in Rome","url":"https://www.timeout.com/rome/things-to-do"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-rome-testaccio-culture', 'rome-testaccio-culture', 'Culture', 'Italy', 'Rome', 'Testaccio', '{"id":"list-rome-testaccio-culture","slug":"rome-testaccio-culture","seoSlug":"best-culture","seoTitle":"Best Culture in Testaccio, Rome","seoDescription":"Best culture in Testaccio, Rome, selected for neighborhood fit, current source support, and useful saved-map routing.","title":"Mattatoio, Monte, and Memory","description":"Testaccio culture is material: amphora hill, slaughterhouse reuse, cemetery quiet, and ancient edges that explain the neighborhood''s food and working-city identity.","url":"https://www.google.com/maps/search/Testaccio%20Culture%20Rome","category":"Culture","location":{"city":"Rome","neighborhood":"Testaccio","country":"Italy","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-culture","name":"R Culture","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"testaccio-macro","name":"MACRO Mattatoio","coordinates":[41.8767,12.475],"description":"MACRO Mattatoio turns Testaccio''s former slaughterhouse into the neighborhood''s contemporary-culture anchor. It belongs because the building history and current programming speak to each other.","photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Monte_Testaccio.jpg","hours":{"default":"Hours vary; confirm current opening times before visiting."},"poiId":"poi-italy-rome-macro-mattatoio"},{"id":"testaccio-monte","name":"Monte Testaccio","coordinates":[41.8767,12.4776],"description":"Monte Testaccio makes the district''s food and trade history visible as landscape. Even when access is limited, it explains why the neighborhood eats the way it does.","photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Monte_Testaccio.jpg","hours":{"default":"Hours vary; confirm current opening times before visiting."},"poiId":"poi-italy-rome-monte-testaccio"},{"id":"testaccio-cimitero-acattolico","name":"Non-Catholic Cemetery for Foreigners","coordinates":[41.8763,12.4804],"description":"The Non-Catholic Cemetery adds quiet literary and expatriate history near the Pyramid. It is one of Testaccio''s best slow cultural stops.","photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Cimitero_Acattolico_Roma.jpg","hours":{"default":"Hours vary; confirm current opening times before visiting."},"poiId":"poi-italy-rome-non-catholic-cemetery-for-foreigners"},{"id":"testaccio-porta-san-paolo","name":"Porta San Paolo","coordinates":[41.8766,12.4803],"description":"Porta San Paolo and the Pyramid edge give Testaccio an ancient-gate frame, useful before moving toward Ostiense or the cemetery. The value is its role in the route: it adds a concrete experience, a timing choice, and a reason to save the stop rather than wander past it. Check current hours and fit it into the nearby cluster instead of treating it as a standalone errand.","photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Porta_San_Paolo_(Rome).jpg","hours":{"default":"Hours vary; confirm current opening times before visiting."},"poiId":"poi-italy-rome-porta-san-paolo"}],"sources":[{"name":"Turismo Roma","url":"https://www.turismoroma.it/en"},{"name":"Parco archeologico del Colosseo","url":"https://colosseo.it/en/"},{"name":"Vatican Museums","url":"https://www.museivaticani.va/content/museivaticani/en.html"},{"name":"Time Out - Things to do in Rome","url":"h