  ('list-rome-celio-hostels', 'rome-celio-hostels', 'Stay', 'Italy', 'Rome', 'Celio', '{"id":"list-rome-celio-hostels","slug":"rome-celio-hostels","seoSlug":"best-hostels","seoTitle":"Best Hostels in Celio, Rome","seoDescription":"Best hostels in Celio, Rome, with source-backed picks for location, sleep style, room type, and value.","title":"Hostels Around the Colosseum","description":"Celio is one of the easier Rome areas for hostel travelers because Monti, Termini, and the Colosseum corridor create a useful cluster of budget beds.","url":"https://www.google.com/maps/search/Celio%20Hostels%20Rome","category":"Stay","location":{"city":"Rome","neighborhood":"Celio","country":"Italy","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-stay","name":"R Stay","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"celio-hostel-ostello-bello","name":"Ostello Bello Roma Colosseo","coordinates":[41.8954,12.4996],"description":"Ostello Bello Roma Colosseo is the natural Celio hostel pick because it sits close to the Colosseum and Monti while still offering a strong social setup. Choose it for dorm/private flexibility near ancient Rome.","price":"$","priceSource":"Hostelworld / Google Maps","photo":"https://ostellobello.com/wp-content/uploads/2021/10/OBR_1x1_Full.jpg","hours":{"default":"Reception/check-in hours vary; confirm directly before booking."},"poiId":"poi-italy-rome-ostello-bello-roma-colosseo"},{"id":"celio-hostel-sandy","name":"Sandy Hostel","coordinates":[41.8956,12.4988],"description":"Sandy Hostel is a budget-minded Colosseum-area fallback, useful for travelers who want the ancient core close and accept simpler facilities. It is a price/location pick.","price":"$","priceSource":"Hostelworld / Google Maps","photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Roma_-_via_Panisperna_-_01.jpg","hours":{"default":"Reception/check-in hours vary; confirm directly before booking."},"poiId":"poi-italy-rome-sandy-hostel"},{"id":"celio-hostel-new-generation","name":"New Generation Hostel Rome Center","coordinates":[41.8959,12.4997],"description":"New Generation Hostel Rome Center works for Celio routes that also use Monti and Termini. It is best when access and cost matter more than a distinctive neighborhood stay.","price":"$","priceSource":"Hostelworld / Google Maps","photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Basilica_Papale_di_Santa_Maria_Maggiore_02.jpg","hours":{"default":"Reception/check-in hours vary; confirm directly before booking."},"poiId":"poi-italy-rome-new-generation-hostel-rome-center"}],"sources":[{"name":"Hostelworld - Rome hostels","url":"https://www.hostelworld.com/hostels/Rome"},{"name":"Condé Nast Traveler - Best hotels in Rome","url":"https://www.cntraveler.com/gallery/best-hotels-in-rome"},{"name":"Time Out - Best hotels in Rome","url":"https://www.timeout.com/rome/hotels"},{"name":"Booking.com - Rome","url":"https://www.booking.com/city/it/rome.html"},{"name":"Tripadvisor - Rome hotels","url":"https://www.tripadvisor.com/Hotels-g187791-Rome_Lazio-Hotels.html"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-madrid-citywide-restaurants', 'madrid-citywide-restaurants', 'Food', 'Spain', 'Madrid', null, '{"id":"list-madrid-citywide-restaurants","slug":"madrid-citywide-restaurants","seoSlug":"best-restaurants","seoTitle":"Best Restaurants in Madrid","seoDescription":"Best restaurants in Madrid, from tapas counters and market tortillas to modern Spanish rooms, wine-led Chueca dining, and destination tasting menus.","title":"Tapas Streets, Markets, and Modern Rooms","description":"Madrid food works best when the route respects local timing: late lunches, vermouth pauses, tapas counters, market stalls, and a few serious reservations. This guide gives the city a first restaurant spine across Sol, Las Letras, Malasana, Chueca, Salamanca, and the bigger destination-dining circuit.","url":"https://www.google.com/maps/search/best+restaurants+madrid","category":"Food","location":{"city":"Madrid","country":"Spain","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-food","name":"R Food","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-06T00:00:00.000Z","stops":[{"id":"madrid-food-casa-dani","name":"Casa Dani","coordinates":[40.4255,-3.6869],"description":"Casa Dani is the Salamanca market anchor because Madrid food planning needs at least one stop that is about the everyday tortilla ritual rather than a formal reservation. The Infatuation highlights it inside Mercado de la Paz, and its sustained market-stall demand makes it a practical lunch or bar-seat stop when the day is moving through Serrano or Retiro-adjacent neighborhoods.","price":"$","priceSource":"The Infatuation / Google Maps","hours":{"mon":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","tue":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","wed":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","thu":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","fri":"12:30 PM-4:00 PM, 7:30 PM-11:30 PM","sat":"12:30 PM-4:00 PM, 7:30 PM-11:30 PM","sun":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM"},"photo":"https://static.wixstatic.com/media/ffa181_13e0b9bd9cb043488dabb7ecf16a0370~mv2.jpg/v1/fill/w_1405,h_667,al_c,q_85,enc_avif,quality_auto/ffa181_13e0b9bd9cb043488dabb7ecf16a0370~mv2","poiId":"poi-spain-madrid-casa-dani"},{"id":"madrid-food-la-malontina","name":"La Malontina","coordinates":[40.4144,-3.6981],"description":"La Malontina gives Barrio de las Letras a compact, food-first dinner that is more useful than a generic Huertas tapas crawl. The Infatuation points to the Cortes room for casual Spanish cooking, and the size of the restaurant keeps it in the date-night, pre-theater, and neighborhood-dinner lane rather than the big occasion lane.","price":"$","priceSource":"The Infatuation / Google Maps","hours":{"mon":"Closed","tue":"7:00 PM-10:30 PM","wed":"7:00 PM-10:30 PM","thu":"7:00 PM-10:30 PM","fri":"7:00 PM-10:30 PM","sat":"7:00 PM-10:30 PM","sun":"Closed"},"photo":"https://images.squarespace-cdn.com/content/v1/5f8c4ebce7e6c83bd00bdac4/1738692480370-VCSG7Q1DPJ0X4VOI7X1F/Almeja+rubia+gallega+a+la+marinera+2.jpg?format=1000w","poiId":"poi-spain-madrid-la-malontina"},{"id":"madrid-food-angelita","name":"Angelita","coordinates":[40.4208,-3.7005],"description":"Angelita works in both Food and Nightlife, but the restaurant earns a food slot because Chueca needs a wine-led dining room with serious produce behind it. The Infatuation and World''s 50 Best Bars both support the address: upstairs for farm-driven plates and a huge wine program, downstairs for the cocktail bar after dinner.","price":"$$","priceSource":"The Infatuation / World''s 50 Best Bars","hours":{"mon":"1:00 PM-4:00 PM, 8:00 PM-11:00 PM","tue":"1:00 PM-4:00 PM, 8:00 PM-11:00 PM","wed":"1:00 PM-4:00 PM, 8:00 PM-11:00 PM","thu":"1:00 PM-4:00 PM, 8:00 PM-11:00 PM","fri":"1:00 PM-4:00 PM, 8:00 PM-11:30 PM","sat":"1:00 PM-4:00 PM, 8:00 PM-11:30 PM","sun":"1:00 PM-4:00 PM, 8:00 PM-11:00 PM"},"photo":"https://www.theworlds50best.com/discovery/filestore/jpg/BARRA%20DE%20VINOS_ANGELITA%20(1)","poiId":"poi-spain-madrid-angelita"},{"id":"madrid-food-playing-solo","name":"Playing Solo","coordinates":[40.4285,-3.7041],"description":"Playing Solo gives Malasana a destination reservation without losing neighborhood scale. The Infatuation frames it as an eight-seat, kitchen-facing tasting-menu experience, so it belongs here for travelers who want Madrid''s modern restaurant energy in a small room instead of a grand-hotel fine-dining setting.","price":"$$","priceSource":"The Infatuation","hours":{"mon":"Closed","tue":"7:00 PM-10:30 PM","wed":"7:00 PM-10:30 PM","thu":"7:00 PM-10:30 PM","fri":"7:00 PM-10:30 PM","sat":"7:00 PM-10:30 PM","sun":"Closed"},"photo":"https://images.unsplash.com/photo-1414235077428-338989a2e8c0?auto=format&fit=crop&w=900&q=80","poiId":"poi-spain-madrid-playing-solo"},{"id":"madrid-food-lhardy","name":"Lhardy","coordinates":[40.4172,-3.7003],"description":"Lhardy is the central classic: old Madrid dining room, croquetas and consomme history, and a useful bridge between Puerta del Sol sightseeing and a proper sit-down meal. It keeps the guide from becoming only contemporary restaurants and helps explain the formal, old-capital side of Madrid eating.","price":"$$","priceSource":"The Infatuation / Google Maps","hours":{"mon":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","tue":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","wed":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","thu":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","fri":"12:30 PM-4:00 PM, 7:30 PM-11:30 PM","sat":"12:30 PM-4:00 PM, 7:30 PM-11:30 PM","sun":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM"},"photo":"https://lhardy.com/wp-content/uploads/Lhardy-Primera-20","poiId":"poi-spain-madrid-lhardy"},{"id":"madrid-food-diverxo","name":"DiverXO","coordinates":[40.4585,-3.6856],"description":"DiverXO is the trip-defining fine-dining entry, backed by MICHELIN''s three-star rating and World''s 50 Best''s No. 4 placement in 2025. It is expensive, theatrical, and north of the usual central route, so use it as a protected reservation rather than a casual Madrid dinner.","price":"$$","priceSource":"MICHELIN Guide / World''s 50 Best","hours":{"mon":"Closed","tue":"1:00 PM-6:30 PM, 7:30 PM-12:00 AM","wed":"1:00 PM-6:30 PM, 7:30 PM-12:00 AM","thu":"1:00 PM-6:30 PM, 7:30 PM-12:00 AM","fri":"1:00 PM-6:30 PM, 7:30 PM-12:00 AM","sat":"Closed","sun":"Closed"},"photo":"https://diverso.it.com/assets/img/DSC_6171","poiId":"poi-spain-madrid-diverxo"},{"id":"madrid-food-smoked-room","name":"Smoked Room","coordinates":[40.4381,-3.6918],"description":"Smoked Room is the intimate high-end counterpoint to DiverXO: MICHELIN gives it two stars and describes a highly exclusive, smoke-and-charcoal-focused dining room inside Hyatt Regency Hesperia Madrid. It belongs in the guide for travelers who want a luxury tasting menu with fewer seats, more kitchen contact, and a quieter mood.","price":"$$","priceSource":"MICHELIN Guide","hours":{"mon":"Closed","tue":"1:00 PM-4:00 PM, 8:30 PM-1:00 AM","wed":"1:00 PM-4:00 PM, 8:30 PM-1:00 AM","thu":"1:00 PM-4:00 PM, 8:30 PM-1:00 AM","fri":"1:00 PM-4:00 PM, 8:30 PM-1:00 AM","sat":"1:00 PM-4:00 PM, 8:30 PM-1:00 AM","sun":"Closed"},"photo":"https://smokedroomrestaurants.com/wp-content/uploads/2025/07/SR_home_carrusel-2","poiId":"poi-spain-madrid-smoked-room"}],"sources":[{"name":"The Infatuation - Best Restaurants in Madrid","url":"https://www.theinfatuation.com/madrid/guides/best-madrid-restaurants"},{"name":"The Infatuation - Best Tapas Spots in Madrid","url":"https://www.theinfatuation.com/madrid/guides/best-tapas-spots-madrid"},{"name":"MICHELIN Guide - DiverXO","url":"https://guide.michelin.com/us/en/comunidad-de-madrid/madrid/restaurant/diverxo"},{"name":"MICHELIN Guide - Smoked Room","url":"https://guide.michelin.com/us/en/comunidad-de-madrid/madrid/restaurant/smoked-room"},{"name":"World''s 50 Best Restaurants - DiverXO","url":"https://www.theworlds50best.com/discovery/Establishments/Spain/Madrid/DiverXO.html"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-madrid-citywide-popular-bars', 'madrid-best-bars-citywide', 'Nightlife', 'Spain', 'Madrid', null, '{"id":"list-madrid-citywide-popular-bars","slug":"madrid-best-bars-citywide","seoSlug":"best-bars","seoTitle":"Best Bars in Madrid","seoDescription":"Best bars in Madrid, including vermouth rooms, Chueca cocktail bars, Las Letras destination drinks, Malasana clubs, and late-night Madrid institutions.","title":"Vermouth, Cocktails, and Late Rooms","description":"Madrid nights start earlier than the club but end much later than dinner. This guide separates vermouth and wine, destination cocktails, Chueca''s polished LGBTQ+ and cocktail corridor, Malasana music energy, and club rooms with a real reason to stay out.","url":"https://www.google.com/maps/search/best+bars+madrid","category":"Nightlife","location":{"city":"Madrid","country":"Spain","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nightlife","name":"R Nightlife","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-06T00:00:00.000Z","stops":[{"id":"madrid-nightlife-salmon-guru","name":"Salmon Guru","coordinates":[40.4159,-3.6997],"description":"Salmon Guru is the Las Letras destination cocktail bar: World''s 50 Best Bars ranks the Madrid flagship in the 2025 list, while Condé Nast Traveler and Time Out both underline the high-energy rooms and Diego Cabrera''s inventive drinks. Use it when the cocktail is the event, not a casual post-dinner afterthought.","hours":{"mon":"6:00 PM-12:30 AM","tue":"6:00 PM-12:30 AM","wed":"6:00 PM-1:00 AM","thu":"6:00 PM-1:30 AM","fri":"6:00 PM-2:30 AM","sat":"6:00 PM-2:30 AM","sun":"6:00 PM-12:00 AM"},"photo":"https://salmonguru.es/wp-content/uploads/2024/07/mad-bunny","poiId":"poi-spain-madrid-salmon-guru"},{"id":"madrid-nightlife-angelita","name":"Angelita","coordinates":[40.4208,-3.7005],"description":"Angelita is the Chueca wine-bar-to-cocktail progression. World''s 50 Best Discovery describes the split between street-level wine bar and basement cocktail lounge, with a strong local-produce and sustainability identity, so it is ideal after dinner when the group wants a serious drink without changing neighborhoods.","hours":{"mon":"6:00 PM-12:30 AM","tue":"6:00 PM-12:30 AM","wed":"6:00 PM-1:00 AM","thu":"6:00 PM-1:30 AM","fri":"6:00 PM-2:30 AM","sat":"6:00 PM-2:30 AM","sun":"6:00 PM-12:00 AM"},"photo":"https://www.theworlds50best.com/discovery/filestore/jpg/BARRA%20DE%20VINOS_ANGELITA%20(1)","poiId":"poi-spain-madrid-angelita"},{"id":"madrid-nightlife-ficus","name":"Ficus Bar","coordinates":[40.4221,-3.6984],"description":"Ficus Bar adds a current Chueca cocktail stop with a more neighborhood-scaled feel than the international trophy bars. Time Out''s 2025 review frames it around author cocktails and an exotic, plant-filled room, making it a good fit for a Chueca night that should stay social and stylish.","hours":{"mon":"6:00 PM-12:30 AM","tue":"6:00 PM-12:30 AM","wed":"6:00 PM-1:00 AM","thu":"6:00 PM-1:30 AM","fri":"6:00 PM-2:30 AM","sat":"6:00 PM-2:30 AM","sun":"6:00 PM-12:00 AM"},"photo":"https://static.wixstatic.com/media/504b29_8a2a776ee62b41fcb512d06189491966~mv2.jpg/v1/fill/w_3360,h_1392,al_c,q_90,usm_0.66_1.00_0.01,enc_avif,quality_auto/504b29_8a2a776ee62b41fcb512d06189491966~mv2","poiId":"poi-spain-madrid-ficus-bar"},{"id":"madrid-nightlife-1862","name":"1862 Dry Bar","coordinates":[40.4234,-3.7036],"description":"1862 Dry Bar is the classic-cocktail Malasana/Tribunal choice, useful when the night needs a quieter, bartender-led drink instead of neon spectacle. It balances Madrid''s newer cocktail reputation with a more restrained room and belongs between dinner and a later Malasana move.","hours":{"mon":"6:00 PM-12:30 AM","tue":"6:00 PM-12:30 AM","wed":"6:00 PM-1:00 AM","thu":"6:00 PM-1:30 AM","fri":"6:00 PM-2:30 AM","sat":"6:00 PM-2:30 AM","sun":"6:00 PM-12:00 AM"},"photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","poiId":"poi-spain-madrid-1862-dry-bar"},{"id":"madrid-nightlife-mondo-disko","name":"Mondo Disko","coordinates":[40.4264,-3.7004],"description":"Mondo Disko is the electronic-music anchor near Barceló: the venue traces its club history back to 1999 and still programs Thursday, Saturday, and holiday-eve nights. Use it when the plan has moved beyond cocktails into tickets, DJs, and a proper late finish.","hours":{"mon":"Event schedule (check venue)","tue":"Event schedule (check venue)","wed":"Event schedule (check venue)","thu":"Event schedule (check venue)","fri":"Event schedule (check venue)","sat":"Event schedule (check venue)","sun":"Event schedule (check venue)"},"photo":"https://www.mondodisko.es/assets/images/mondo-disko-2","poiId":"poi-spain-madrid-mondo-disko"},{"id":"madrid-nightlife-toni2","name":"Toni 2 Piano Bar","coordinates":[40.421,-3.6976],"description":"Toni 2 gives the guide an old Madrid singalong finish near Chueca and Gran Via. It is not the polished cocktail lane; it is a late, theatrical piano-bar institution that works when the night should feel communal, slightly chaotic, and very Madrid.","hours":{"mon":"10:00 PM-2:30 AM","tue":"10:00 PM-2:30 AM","wed":"10:00 PM-3:30 AM","thu":"10:00 PM-4:30 AM","fri":"10:00 PM-5:00 AM","sat":"10:00 PM-5:00 AM","sun":"10:00 PM-2:30 AM"},"photo":"https://toni2.es/wp-content/uploads/2021/09/Barra-Toni-2-madrid-scaled-e1636977700852-2048x1295","poiId":"poi-spain-madrid-toni-2-piano-bar"}],"sources":[{"name":"World''s 50 Best Bars - Salmon Guru","url":"https://www.theworlds50best.com/bars/the-list/salmon-guru.html"},{"name":"World''s 50 Best Discovery - Angelita","url":"https://www.theworlds50best.com/discovery/Establishments/Spain/Madrid/Angelita.html"},{"name":"Condé Nast Traveler - Best Bars in Madrid","url":"https://www.cntraveler.com/gallery/best-bars-in-madrid"},{"name":"Condé Nast Traveler - Salmon Guru","url":"https://www.cntraveler.com/bars/salmon-guru"},{"name":"Time Out - Ficus Bar","url":"https://www.timeout.es/madrid/es/bares-y-pubs/ficus-bar"},{"name":"Mondo Disko official","url":"https://www.mondodisko.es/en/mondo-disko/"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-madrid-citywide-stays', 'madrid-best-hotels-citywide', 'Stay', 'Spain', 'Madrid', null, '{"id":"list-madrid-citywide-stays","slug":"madrid-best-hotels-citywide","seoSlug":"best-hotels","seoTitle":"Best Hotels in Madrid","seoDescription":"Best hotels in Madrid, comparing Sol luxury, Retiro museum hotels, Chueca boutique stays, Malasana design bases, and La Latina old-city access.","title":"Hotels That Match the Madrid Route","description":"Madrid hotel planning should start with the trip shape: museum mornings, late-night neighborhoods, old-city walks, or a quieter reset after dinner. This citywide hotel guide keeps luxury, boutique design, value, and neighborhood fit in separate roles instead of mixing them with hostels.","url":"https://www.google.com/maps/search/best+hotels+madrid","category":"Stay","location":{"city":"Madrid","country":"Spain","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-stay","name":"R Stay","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-06T00:00:00.000Z","stops":[{"id":"stay-four-seasons","name":"Four Seasons Hotel Madrid","coordinates":[40.4172,-3.7015],"description":"Four Seasons Hotel Madrid is the high-budget Canalejas hotel pick because it gives Sol access without asking travelers to accept old-center compromise. Use it when service, dining, spa, and a quieter room standard matter as much as walking to Plaza Mayor, Gran Via, and the Art Walk.","price":"$$","priceSource":"Condé Nast Traveler / Google Maps","hours":{"mon":"24 hours","tue":"24 hours","wed":"24 hours","thu":"24 hours","fri":"24 hours","sat":"24 hours","sun":"24 hours"},"photo":"https://upload.wikimedia.org/wikipedia/commons/4/42/Edificio_del_Banco_Espa%C3%B1ol_de_Cr%C3%A9dito_de_Madrid","poiId":"poi-spain-madrid-four-seasons-hotel-madrid"},{"id":"stay-mandarin-oriental-ritz","name":"Mandarin Oriental Ritz, Madrid","coordinates":[40.4156,-3.6926],"description":"Mandarin Oriental Ritz is the museum-corridor luxury anchor because it sits beside the Prado and Retiro in Madrid''s Golden Triangle of Art. Choose it when Belle Epoque atmosphere, service, dining, and park-museum proximity matter more than nightlife at the door.","price":"$$","priceSource":"Mandarin Oriental / MICHELIN Guide","hours":{"mon":"24 hours","tue":"24 hours","wed":"24 hours","thu":"24 hours","fri":"24 hours","sat":"24 hours","sun":"24 hours"},"photo":"https://cdn-assets-eu.frontify.com/s3/frontify-enterprise-files-eu/eyJvYXV0aCI6eyJjbGllbnRfaWQiOiJzaXRlY29yZSJ9LCJwYXRoIjoibWFuZGFyaW4tb3JpZW50YWwtaG90ZWwtZ3JvdXBcL2ZpbGVcL1Jyc1NpbzZTSzZOTnA5bUdiZTdNLmpwZyJ9:mandarin-oriental-hotel-group:rvzw8tiI3oli4sezJ4kuQj0g-YGtBl87X7AZLmzA-cQ?width=1280&height=560&fp=0.5,0.5&crop=fp&quality=75","poiId":"poi-spain-madrid-mandarin-oriental-ritz-madrid"},{"id":"stay-only-you-boutique","name":"Only YOU Boutique Hotel Madrid","coordinates":[40.4235,-3.6964],"description":"Only YOU Boutique Hotel Madrid is the Chueca hotel anchor because MICHELIN highlights its palace-to-boutique conversion, lively design, and Barquillo address. It is best for travelers who want cocktail bars, shopping, and central movement close while still getting a real hotel reset.","price":"$$","priceSource":"MICHELIN Guide / Google Maps","hours":{"mon":"24 hours","tue":"24 hours","wed":"24 hours","thu":"24 hours","fri":"24 hours","sat":"24 hours","sun":"24 hours"},"photo":"https://www.onlyyouhotels.com/data/webp/galeria-fotos-oyb5872.jpg-577afb9e3b5f0876d20535f0f7b9a1cd.webp","poiId":"poi-spain-madrid-only-you-boutique-hotel-madrid"},{"id":"stay-urso","name":"URSO Hotel & Spa Madrid","coordinates":[40.4252,-3.6999],"description":"URSO is the calmer luxury edge between Malasana, Chamberi, and Chueca, backed by MICHELIN Key attention for a restored-palace stay with spa-level reset. Use it when you want nightlife nearby but do not want to sleep directly inside the loudest blocks.","price":"$$","priceSource":"MICHELIN Key Hotels / Google Maps","hours":{"mon":"24 hours","tue":"24 hours","wed":"24 hours","thu":"24 hours","fri":"24 hours","sat":"24 hours","sun":"24 hours"},"photo":"https://b4411764.smushcdn.com/4411764/wp-content/uploads/2018/10/water-zone-urso-hotel-spa-madrid.jpg?lossy=2&strip=1&webp=1","poiId":"poi-spain-madrid-urso-hotel-and-spa-madrid"},{"id":"stay-edition","name":"The Madrid EDITION","coordinates":[40.4171,-3.7062],"description":"The Madrid EDITION earns a hotel slot for travelers who want central design, rooftop energy, and a polished reset within a few blocks of Plaza Mayor and Sol. It works best when the trip should feel contemporary and social without giving up a full-service hotel base.","price":"$$","priceSource":"Condé Nast Traveler / Google Maps","hours":{"mon":"24 hours","tue":"24 hours","wed":"24 hours","thu":"24 hours","fri":"24 hours","sat":"24 hours","sun":"24 hours"},"photo":"https://www.editionhotels.com/wp-content/uploads/2026/03/EDT_Madrid2_23-_RGB_V1-2-scaled.jpg","poiId":"poi-spain-madrid-the-madrid-edition"},{"id":"stay-pestana-plaza-mayor","name":"Pestana Plaza Mayor Madrid","coordinates":[40.415,-3.7074],"description":"Pestana Plaza Mayor is the historic-center hotel pick for travelers who want to sleep on Madrid de los Austrias rather than commute into it. Tourism Madrid and Pestana both frame the draw clearly: Plaza Mayor frontage, contemporary rooms, spa facilities, and rooftop-season usefulness.","price":"$$","priceSource":"Tourism Madrid / Pestana","hours":{"mon":"24 hours","tue":"24 hours","wed":"24 hours","thu":"24 hours","fri":"24 hours","sat":"24 hours","sun":"24 hours"},"photo":"https://www.pestana.com/content/dam/pestana/en_us/destinations/spain/madrid/pestana-plaza-mayor/gallery/overview/pestana-plaza-mayor-gallery-surroundings-view-outside-night","poiId":"poi-spain-madrid-pestana-plaza-mayor-madrid"},{"id":"stay-seven-islas","name":"7 Islas Hotel","coordinates":[40.4217,-3.7012],"description":"7 Islas Hotel is the Gran Via-to-Malasana design option, useful when the stay should feel independent, art-led, and close to nightlife without becoming a hostel. Its official materials emphasize the Valverde address, gallery feel, restaurant-bar, and slower boutique rhythm between Gran Via and Malasana.","price":"$","priceSource":"7 Islas official / Google Maps","hours":{"mon":"24 hours","tue":"24 hours","wed":"24 hours","thu":"24 hours","fri":"24 hours","sat":"24 hours","sun":"24 hours"},"photo":"https://www.7islashotel.com/wp-content/themes/sieteislas/img/new/LOGO-new.svg","poiId":"poi-spain-madrid-7-islas-hotel"}],"sources":[{"name":"Tourism Madrid - MICHELIN Key Hotels","url":"https://www.esmadrid.com/en/michelin-key-hotels"},{"name":"Condé Nast Traveler - Madrid hotels","url":"https://www.cntraveler.com/hotels/madrid"},{"name":"MICHELIN Guide - Only YOU Boutique Hotel Madrid","url":"https://guide.michelin.com/us/en/hotels-stays/madrid/only-you-boutique-hotel-madrid-8366"},{"name":"Mandarin Oriental Ritz Madrid official","url":"https://www.mandarinoriental.com/en/madrid"},{"name":"Tourism Madrid - Pestana Plaza Mayor","url":"https://www.esmadrid.com/en/accommodation/pestana-plaza-mayor"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-madrid-citywide-hostels', 'madrid-best-hostels-citywide', 'Stay', 'Spain', 'Madrid', null, '{"id":"list-madrid-citywide-hostels","slug":"madrid-best-hostels-citywide","seoSlug":"best-hostels","seoTitle":"Best Hostels in Madrid","seoDescription":"Best hostels in Madrid, comparing Sol, La Latina, Malasana, Chueca, Tirso de Molina, Atocha, social dorms, private rooms, and budget bases.","title":"Social Beds Across the Center","description":"Madrid hostel planning is about choosing the right kind of social base: rooftop central, party-forward, design-hostel, museum-edge, or Tirso/La Latina practical. This citywide hostel guide separates budget beds from hotels and names the tradeoff each hostel asks travelers to make.","url":"https://www.google.com/maps/search/best+hostels+madrid","category":"Stay","location":{"city":"Madrid","country":"Spain","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-stay","name":"R Stay","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-06T00:00:00.000Z","stops":[{"id":"stay-the-hat","name":"The Hat Madrid","coordinates":[40.4145,-3.7073],"description":"The Hat Madrid is the central hostel pick because Hostelworld and the official site both emphasize Plaza Mayor proximity, private-or-dorm flexibility, events, and rooftop social energy. Use it when budget and meeting people matter, but the route still needs Sol, La Latina, and old Madrid on foot.","price":"$","priceSource":"Hostelworld / The Hat official","hours":{"mon":"24 hours","tue":"24 hours","wed":"24 hours","thu":"24 hours","fri":"24 hours","sat":"24 hours","sun":"24 hours"},"photo":"https://thehatmadrid.com/wp-content/uploads/slider/cache/cb3097b9f7bb39d19fd625c1017d58d6/1.the_hat-88-1.webp","poiId":"poi-spain-madrid-the-hat-madrid"},{"id":"stay-onefam-madrid","name":"Onefam Madrid","coordinates":[40.4287,-3.7039],"description":"Onefam Madrid is the Malasana social-hostel pick because Hostelworld describes the chain around family-style dinners, daily activities, and nights out. Use it when the point of the stay is meeting people and using the neighborhood''s bars, not retreating from them.","price":"$","priceSource":"Hostelworld / Google Maps","hours":{"mon":"24 hours","tue":"24 hours","wed":"24 hours","thu":"24 hours","fri":"24 hours","sat":"24 hours","sun":"24 hours"},"photo":"https://onefamhostels.com/wp-content/uploads/2024/09/02Onefam-Madrid-terrace2.webp","poiId":"poi-spain-madrid-onefam-madrid"},{"id":"stay-2060-newton","name":"2060 The Newton Hostel","coordinates":[40.412,-3.7048],"description":"2060 The Newton Hostel gives Madrid hostel planning a Tirso de Molina base with strong center access, rooftop-bar utility, and common areas. Hostelworld lists high review volume and location strength, but the best fit is still budget travelers who can tolerate a busier shared-room setting.","price":"$","priceSource":"Hostelworld / Google Maps","hours":{"mon":"24 hours","tue":"24 hours","wed":"24 hours","thu":"24 hours","fri":"24 hours","sat":"24 hours","sun":"24 hours"},"photo":"https://2060hostelandmarket.com/wp-content/uploads/2023/09/las-mejores-vistas-madrid-hostel-4.jpg.webp","poiId":"poi-spain-madrid-2060-the-newton-hostel"},{"id":"stay-latroupe-prado","name":"Latroupe Prado","coordinates":[40.4119,-3.6943],"description":"Latroupe Prado is the Art Walk hostel because its official site puts it beside Atocha and the Reina Sofia, with coworking, bar, restaurant, and common-space infrastructure. Use it when museums and rail access matter more than sleeping inside the nightlife core.","price":"$","priceSource":"Latroupe official / Hostelworld","hours":{"mon":"24 hours","tue":"24 hours","wed":"24 hours","thu":"24 hours","fri":"24 hours","sat":"24 hours","sun":"24 hours"},"photo":"https://www.latroupe.com/data/webp/hotel1125742-fa85b6f4b8a42e52a10641a84db3f801.webp","poiId":"poi-spain-madrid-latroupe-prado"},{"id":"stay-ok-hostel","name":"Ok Hostel Madrid","coordinates":[40.4113,-3.708],"description":"Ok Hostel Madrid is the La Latina and Tirso de Molina utility hostel, useful for travelers who want central walks, social energy, and a lower nightly rate. Choose it when the plan points toward Cava Baja, Lavapies, and Sol more than Retiro-side quiet.","price":"$","priceSource":"Hostelworld / Google Maps","hours":{"mon":"24 hours","tue":"24 hours","wed":"24 hours","thu":"24 hours","fri":"24 hours","sat":"24 hours","sun":"24 hours"},"photo":"https://a.hwstatic.com/image/upload/f_auto,q_auto,h_720,c_limit,e_sharpen,e_improve,e_vibrance:60/propertyimages/9/94332/nibn7kmmmvkunz0dsq6i.jpg","poiId":"poi-spain-madrid-ok-hostel-madrid"},{"id":"stay-bastardo","name":"Bastardo Hostel","coordinates":[40.4248,-3.7009],"description":"Bastardo Hostel works as the Tribunal design-hostel hybrid, sitting between Malasana and Chueca with private and shared-room flexibility. It fits travelers who want social spaces and style but still need an easier reset than a pure party hostel.","price":"$","priceSource":"Bastardo official / Hostelworld","hours":{"mon":"24 hours","tue":"24 hours","wed":"24 hours","thu":"24 hours","fri":"24 hours","sat":"24 hours","sun":"24 hours"},"photo":"https://a.hwstatic.com/image/upload/f_auto,q_auto,h_720,c_limit,e_sharpen,e_improve,e_vibrance:60/propertyimages/2/295483/mvaxq6golqqla0fyh3jw.jpg","poiId":"poi-spain-madrid-bastardo-hostel"},{"id":"stay-room00-chueca","name":"room00 Chueca Hostel","coordinates":[40.4245,-3.6977],"description":"room00 Chueca Hostel is the Chueca dorm-and-private-room option on Hortaleza, close to Chueca, Malasana, and Gran Via. Hostelworld and local listings make the tradeoff clear: strong location and low price, with simpler atmosphere than the city''s more social hostels.","price":"$","priceSource":"Hostelworld / Visit Chueca","hours":{"mon":"24 hours","tue":"24 hours","wed":"24 hours","thu":"24 hours","fri":"24 hours","sat":"24 hours","sun":"24 hours"},"photo":"https://a.hwstatic.com/image/upload/f_auto,q_auto,h_720,c_limit,e_sharpen,e_improve,e_vibrance:60/propertyimages/8/83795/ohbhqjhitvwpqc14oim1.jpg","poiId":"poi-spain-madrid-room00-chueca-hostel"}],"sources":[{"name":"Hostelworld - Madrid Hostels","url":"https://www.hostelworld.com/hostels/europe/spain/madrid/"},{"name":"The Hat Madrid official","url":"https://www.thehatmadrid.com/en/"},{"name":"Latroupe Prado official","url":"https://www.latroupe.com/en/latroupe-prado/hostel/"},{"name":"Hostelworld - Onefam Madrid","url":"https://www.hostelworld.com/hostels/p/286369/onefam-madrid/"},{"name":"Hostelworld - 2060 The Newton Hostel","url":"https://www.hostelworld.com/hostels/p/282289/2060-the-newton-hostel/"},{"name":"Hostelworld - room00 Chueca Hostel","url":"https://www.hostelworld.com/st/hotels/p/83795/room007-chueca-hostel/"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-madrid-citywide-culture', 'madrid-best-culture-citywide', 'Culture', 'Spain', 'Madrid', null, '{"id":"list-madrid-citywide-culture","slug":"madrid-best-culture-citywide","seoSlug":"best-culture","seoTitle":"Best Culture in Madrid","seoDescription":"Best culture in Madrid, connecting the Prado, Reina Sofia, Thyssen, Royal Palace, literary streets, galleries, and Retiro-area museum days.","title":"Art Walk, Palace Rooms, and Literary Streets","description":"Madrid''s culture spine is unusually walkable: the Prado triangle, royal history, Las Letras, Retiro edges, and smaller gallery streets all sit close enough to combine with long lunches and late dinners. Use this when the day needs structure beyond one museum ticket.","url":"https://www.google.com/maps/search/best+culture+madrid","category":"Culture","location":{"city":"Madrid","country":"Spain","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-culture","name":"R Culture","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-06T00:00:00.000Z","stops":[{"id":"madrid-culture-prado","name":"Museo Nacional del Prado","coordinates":[40.4138,-3.6921],"description":"The Prado is the Art Walk anchor because it holds the city''s deepest Spanish, Italian, and Flemish painting context, from Velazquez and Goya to Bosch. Madrid tourism calls it the crown jewel of Paseo del Arte, and the museum''s own hours make it practical as a morning or late-afternoon plan.","hours":{"mon":"10:00 AM-8:00 PM","tue":"10:00 AM-8:00 PM","wed":"10:00 AM-8:00 PM","thu":"10:00 AM-8:00 PM","fri":"10:00 AM-8:00 PM","sat":"10:00 AM-8:00 PM","sun":"10:00 AM-7:00 PM"},"photo":"https://upload.wikimedia.org/wikipedia/commons/6/68/Museo_del_Prado_2016_%2825185969599%29.jpg","poiId":"poi-spain-madrid-museo-nacional-del-prado"},{"id":"madrid-culture-reina-sofia","name":"Museo Reina Sofia","coordinates":[40.408,-3.694],"description":"Reina Sofia is the modern and contemporary counterweight to the Prado, with Picasso''s Guernica as the central reason many travelers come. Madrid tourism notes the Atocha building''s modern Spanish collection and current renovation caveats around its Retiro park spaces, so it works best as an indoor Art Walk anchor.","hours":{"mon":"Closed","tue":"10:00 AM-7:00 PM","wed":"10:00 AM-7:00 PM","thu":"10:00 AM-7:00 PM","fri":"10:00 AM-7:00 PM","sat":"10:00 AM-7:00 PM","sun":"10:00 AM-7:00 PM"},"photo":"https://upload.wikimedia.org/wikipedia/commons/b/b1/Museo_Reina_Sofia%2C_Madrid_%286394654203%29","poiId":"poi-spain-madrid-museo-reina-sofia"},{"id":"madrid-culture-thyssen","name":"Museo Nacional Thyssen-Bornemisza","coordinates":[40.416,-3.6947],"description":"Thyssen fills the bridge between Prado and Reina Sofia: a collection route through European painting that helps the Art Walk feel like one coherent day rather than two isolated blockbuster museums. It is especially useful when the group wants breadth and a manageable visit length.","hours":{"mon":"10:00 AM-7:00 PM","tue":"10:00 AM-7:00 PM","wed":"10:00 AM-7:00 PM","thu":"10:00 AM-7:00 PM","fri":"10:00 AM-7:00 PM","sat":"10:00 AM-7:00 PM","sun":"10:00 AM-7:00 PM"},"photo":"https://www.esmadrid.com/sites/default/files/styles/content_type_full/public/recursosturisticos/infoturistica/museo_thyssen.jpg?itok=8LiTSzHG","poiId":"poi-spain-madrid-museo-nacional-thyssen-bornemisza"},{"id":"madrid-culture-royal-palace","name":"Royal Palace of Madrid","coordinates":[40.4179,-3.7143],"description":"The Royal Palace pulls the culture route west from Sol into monarchy, ceremony, and plaza-scale Madrid. It pairs naturally with Almudena, Plaza de Oriente, and a La Latina evening, making it the royal-history anchor rather than another museum in the Prado cluster.","hours":{"mon":"9:00 AM-8:00 PM","tue":"9:00 AM-8:00 PM","wed":"9:00 AM-8:00 PM","thu":"9:00 AM-8:00 PM","fri":"9:00 AM-8:00 PM","sat":"9:00 AM-8:00 PM","sun":"9:00 AM-8:00 PM"},"photo":"https://upload.wikimedia.org/wikipedia/commons/9/9b/Palacio_Real_de_Madrid_Julio_2016_%28cropped%29.jpg","poiId":"poi-spain-madrid-royal-palace-of-madrid"},{"id":"madrid-culture-barrio-letras","name":"Barrio de las Letras","coordinates":[40.4143,-3.6986],"description":"Barrio de las Letras turns culture into a walk: Huertas, Plaza de Santa Ana, Teatro Espanol, Lope de Vega context, and the Cervantes/Golden Age literary layer. It is the best bridge between daytime museums and the bars and restaurants that make Madrid feel alive after dark.","hours":{"mon":"Open public space","tue":"Open public space","wed":"Open public space","thu":"Open public space","fri":"Open public space","sat":"Open public space","sun":"Open public space"},"photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Barrio_de_las_Letras_%28Madrid%29_01.jpg","poiId":"poi-spain-madrid-barrio-de-las-letras"},{"id":"madrid-culture-caixaforum","name":"CaixaForum Madrid","coordinates":[40.411,-3.6932],"description":"CaixaForum adds a flexible exhibition stop to the Art Walk, useful when the Prado/Reina Sofia plan needs a shorter contemporary counterpoint. The vertical garden and Herzog & de Meuron building also make it a strong architecture pause between Atocha and Paseo del Prado.","hours":{"mon":"10:00 AM-7:00 PM","tue":"10:00 AM-7:00 PM","wed":"10:00 AM-7:00 PM","thu":"10:00 AM-7:00 PM","fri":"10:00 AM-7:00 PM","sat":"10:00 AM-7:00 PM","sun":"10:00 AM-7:00 PM"},"photo":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRHfgXoQIbluuwowl5GV6fobIFpbrbzX6Pqtw&s","poiId":"poi-spain-madrid-caixaforum-madrid"},{"id":"madrid-culture-matadero","name":"Matadero Madrid","coordinates":[40.3913,-3.6972],"description":"Matadero pushes the guide into Arganzuela and Madrid Rio, which keeps culture from being only the museum triangle. The former slaughterhouse complex is useful for exhibitions, design, performance, and a more industrial contemporary Madrid layer.","hours":{"mon":"Closed","tue":"10:00 AM-7:00 PM","wed":"10:00 AM-7:00 PM","thu":"10:00 AM-7:00 PM","fri":"10:00 AM-7:00 PM","sat":"10:00 AM-7:00 PM","sun":"10:00 AM-7:00 PM"},"photo":"https://live.staticflickr.com/4301/36176921785_f5163eecec_b","poiId":"poi-spain-madrid-matadero-madrid"}],"sources":[{"name":"Tourism Madrid - Prado Museum","url":"https://www.esmadrid.com/en/tourist-information/museo-del-prado"},{"name":"Museo Nacional del Prado - Opening Times","url":"https://www.museodelprado.es/en/visit/opening-times-and-prices"},{"name":"Tourism Madrid - Reina Sofia Museum","url":"https://www.esmadrid.com/en/tourist-information/reina-sofia-museum"},{"name":"Tourism Madrid","url":"https://www.esmadrid.com/en"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-barcelona-one-day-activities', 'barcelona-one-day-itinerary', 'Activities', 'Spain', 'Barcelona', null, '{"id":"list-barcelona-one-day-activities","slug":"barcelona-one-day-itinerary","seoSlug":"best-things-to-do","seoTitle":"Best Things to Do in Barcelona in One Day","seoDescription":"Best one-day Barcelona itinerary, combining one essential culture stop, one restaurant, one neighborhood walk, one low-key bar, and one destination nightlife option.","title":"One Strong Day, No Filler","description":"A focused first-day route that chooses one great architecture stop, a counter lunch, old-city wandering, a salty cava pause, and a final cocktail spectacle. It is built to feel complete without pretending you can see everything in one day.","url":"https://www.google.com/maps/search/best+things+to+do+barcelona+one+day","category":"Activities","location":{"city":"Barcelona","country":"Spain","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-activities","name":"R Activities","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-04-29T00:00:00.000Z","stops":[{"id":"barcelona-day-casa-batllo","name":"Casa Batlló","coordinates":[41.3917,2.1649],"description":"Start with the culture category at Casa Batlló because one day in Barcelona needs a high-impact Modernista anchor. It gives first-time visitors architecture, craft, rooftop drama, and Passeig de Gràcia context without sending them across the city before lunch.","hours":{"mon":"9:00 AM-8:00 PM","tue":"9:00 AM-8:00 PM","wed":"9:00 AM-8:00 PM","thu":"9:00 AM-8:00 PM","fri":"9:00 AM-8:00 PM","sat":"9:00 AM-8:00 PM","sun":"9:00 AM-8:00 PM"},"photo":"https://casa-batllo-barcelona.com/wp-content/uploads/2026/01/19944e616eb84ad3b204463508875f98.jpeg","poiId":"poi-spain-barcelona-casa-batllo"},{"id":"barcelona-day-cal-pep","name":"Cal Pep","coordinates":[41.3835,2.1839],"description":"Use Cal Pep as the food stop because the counter format turns lunch into a Barcelona experience rather than just a meal. Seafood tapas, quick pacing, and Born location make it easy to transition from architecture into the old-city afternoon.","price":"$$$","priceSource":"The Infatuation / Google Maps","hours":{"mon":"Closed","tue":"1:00 PM-3:30 PM, 8:00 PM-11:00 PM","wed":"1:00 PM-3:30 PM, 8:00 PM-11:00 PM","thu":"1:00 PM-3:30 PM, 8:00 PM-11:00 PM","fri":"1:00 PM-3:30 PM, 8:00 PM-11:30 PM","sat":"1:00 PM-3:30 PM, 8:00 PM-11:30 PM","sun":"Closed"},"photo":"https://static.wixstatic.com/media/57144e_89f865012fdb4db8bc8bec1b2fdeede3~mv2.jpg","poiId":"poi-spain-barcelona-cal-pep"},{"id":"barcelona-day-santa-maria","name":"Basílica de Santa Maria del Mar","coordinates":[41.3839,2.1822],"description":"Make Santa Maria del Mar the afternoon culture stop because it is close to lunch, short enough for a one-day route, and central to the Born''s merchant history. It gives the itinerary a clear architectural pause before the evening shifts into cava counters and cocktail rooms.","hours":{"mon":"9:00 AM-8:00 PM","tue":"9:00 AM-8:00 PM","wed":"9:00 AM-8:00 PM","thu":"9:00 AM-8:00 PM","fri":"9:00 AM-8:00 PM","sat":"9:00 AM-8:00 PM","sun":"9:00 AM-8:00 PM"},"photo":"https://upload.wikimedia.org/wikipedia/commons/4/4c/Santa_Maria_del_Mar%2C_Barcelona_02.jpg","poiId":"poi-spain-barcelona-basilica-de-santa-maria-del-mar"},{"id":"barcelona-day-xampanyet","name":"El Xampanyet","coordinates":[41.3847,2.1836],"description":"Move into the dive-bar category at El Xampanyet for cava, anchovies, and a packed counter that feels more Barcelona-specific than a generic aperitif. It is a short, loud, salty bridge between sightseeing and dinner-hour nightlife.","hours":{"mon":"7:00 PM-11:00 PM","tue":"12:00 PM-3:30 PM, 7:00 PM-11:00 PM","wed":"12:00 PM-3:30 PM, 7:00 PM-11:00 PM","thu":"12:00 PM-3:30 PM, 7:00 PM-11:00 PM","fri":"12:00 PM-3:30 PM, 7:00 PM-11:00 PM","sat":"12:00 PM-3:30 PM","sun":"Closed"},"photo":"https://www.elxampanyet.com/wp-content/uploads/2024/10/Iriarte_0132-2048x1353.jpg","poiId":"poi-spain-barcelona-el-xampanyet"},{"id":"barcelona-day-paradiso","name":"Paradiso","coordinates":[41.3859,2.1822],"description":"End with the popular-bar category at Paradiso when the day calls for one memorable cocktail spectacle. The line can be part of the plan, so this works best as the final stop rather than a fragile mid-route reservation.","hours":{"mon":"6:00 PM-12:30 AM","tue":"6:00 PM-12:30 AM","wed":"6:00 PM-1:00 AM","thu":"6:00 PM-1:30 AM","fri":"6:00 PM-2:30 AM","sat":"6:00 PM-2:30 AM","sun":"6:00 PM-12:00 AM"},"photo":"https://paradiso.cat/wp-content/uploads/2020/06/bck_premios-scaled_op.jpg","poiId":"poi-spain-barcelona-paradiso"}],"sources":[{"name":"Barcelona Turisme","url":"https://www.barcelonaturisme.com"},{"name":"The Infatuation - Best Restaurants in Barcelona","url":"https://www.theinfatuation.com/barcelona/guides/best-restaurants-hotels-barcelona"},{"name":"Time Out - Best bars in Barcelona","url":"https://www.timeout.com/barcelona/bars-and-pubs/best-bars-in-barcelona"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-barcelona-weekend-activities', 'barcelona-weekend-itinerary', 'Activities', 'Spain', 'Barcelona', null, '{"id":"list-barcelona-weekend-activities","slug":"barcelona-weekend-itinerary","seoSlug":"best-things-to-do","seoTitle":"Best Things to Do in Barcelona for a Weekend","seoDescription":"Best Barcelona weekend itinerary, mixing culture, restaurants, dive bars, popular nightlife, hostel/stay context, and neighborhood pacing across two days.","title":"Two Nights, Five Neighborhood Moods","description":"A weekend route with room to breathe: Gracia base energy, Eixample architecture, old-city nights, Montjuic art, Poble-sec bites, and one proper late finish. Use it when two days should feel paced, not stuffed.","url":"https://www.google.com/maps/search/barcelona+weekend+itinerary","category":"Activities","location":{"city":"Barcelona","country":"Spain","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-activities","name":"R Activities","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-04-29T00:00:00.000Z","stops":[{"id":"barcelona-weekend-casa-gracia","name":"Casa Gracia","coordinates":[41.3978,2.1578],"description":"Use Casa Gracia as the stay-category anchor for the weekend because it splits the difference between hostel social energy, private-room flexibility, and easy transit. Starting from Gràcia keeps the route from becoming only an old-city weekend.","hours":{"mon":"24 hours","tue":"24 hours","wed":"24 hours","thu":"24 hours","fri":"24 hours","sat":"24 hours","sun":"24 hours"},"photo":"https://room00hostel.com/assets/images/barcelona/slider-hotel/1.webp","poiId":"poi-spain-barcelona-casa-gracia"},{"id":"barcelona-weekend-casa-batllo","name":"Casa Batlló","coordinates":[41.3917,2.1649],"description":"Casa Batlló handles the headline culture slot on day one because it is central, visually immediate, and easy to pair with an Eixample lunch or Passeig de Gràcia walk. Book it as the major architecture moment, then let the rest of the day loosen up.","hours":{"mon":"9:00 AM-8:00 PM","tue":"9:00 AM-8:00 PM","wed":"9:00 AM-8:00 PM","thu":"9:00 AM-8:00 PM","fri":"9:00 AM-8:00 PM","sat":"9:00 AM-8:00 PM","sun":"9:00 AM-8:00 PM"},"photo":"https://casa-batllo-barcelona.com/wp-content/uploads/2026/01/19944e616eb84ad3b204463508875f98.jpeg","poiId":"poi-spain-barcelona-casa-batllo"},{"id":"barcelona-weekend-bodega-bonay","name":"Bodega Bonay","coordinates":[41.3918,2.1746],"description":"Bodega Bonay is the weekend food stop when the plan needs a stylish but manageable meal rather than a tasting-menu commitment. It keeps the route in Eixample while adding natural wine, anchovies, pastas, and a design-hotel setting.","price":"$$","priceSource":"The Infatuation / Resy","hours":{"mon":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","tue":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","wed":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","thu":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","fri":"12:30 PM-4:00 PM, 7:30 PM-11:30 PM","sat":"12:30 PM-4:00 PM, 7:30 PM-11:30 PM","sun":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM"},"photo":"https://cdn-hhbfohb.nitrocdn.com/MWVuFFQrOubRCgucqTrIdzQgXRECTcge/assets/images/optimized/rev-41ae578/casabonay.com/wp-content/uploads/2020/12/ATP9564@antp-900x1196.jpg","poiId":"poi-spain-barcelona-bodega-bonay"},{"id":"barcelona-weekend-bar-marsella","name":"Bar Marsella","coordinates":[41.3852,2.1619],"description":"Bar Marsella gives the weekend a dive-bar texture after the polished daytime stops. Its worn-in absinthe history and late-night feel work especially well before moving toward Gothic/Born nightlife.","hours":{"mon":"6:00 PM-12:30 AM","tue":"6:00 PM-12:30 AM","wed":"6:00 PM-1:00 AM","thu":"6:00 PM-1:30 AM","fri":"6:00 PM-2:30 AM","sat":"6:00 PM-2:30 AM","sun":"6:00 PM-12:00 AM"},"photo":"https://www.barcelona-life.com/wp-content/uploads/2018/02/marsella-barcelona.jpg","poiId":"poi-spain-barcelona-bar-marsella"},{"id":"barcelona-weekend-joan-miro","name":"Fundació Joan Miró","coordinates":[41.3686,2.1592],"description":"Fundació Joan Miró anchors day two with Montjuïc culture, a focused museum visit, and a hillside setting that slows the pace after a late night. It gives the weekend route a calm art stop without making the day feel underbuilt.","hours":{"mon":"Closed","tue":"10:00 AM-7:00 PM","wed":"10:00 AM-7:00 PM","thu":"10:00 AM-7:00 PM","fri":"10:00 AM-7:00 PM","sat":"10:00 AM-7:00 PM","sun":"10:00 AM-7:00 PM"},"photo":"https://upload.wikimedia.org/wikipedia/commons/9/9d/Fundaci%C3%B3_Mir%C3%B3.JPG","poiId":"poi-spain-barcelona-fundacio-joan-miro"},{"id":"barcelona-weekend-quimet-quimet","name":"Quimet & Quimet","coordinates":[41.3738,2.1635],"description":"Quimet & Quimet is the Poble-sec food-and-bar hybrid for the weekend route. Standing montaditos and bottles make it practical before Carrer de Blai or a club night while still feeling like a real Barcelona institution.","hours":{"mon":"12:00 PM-11:00 PM","tue":"12:00 PM-11:00 PM","wed":"12:00 PM-11:00 PM","thu":"12:00 PM-11:30 PM","fri":"12:00 PM-12:00 AM","sat":"12:00 PM-12:00 AM","sun":"12:00 PM-10:30 PM"},"photo":"https://quimetiquimet.com/wp-content/uploads/tapbg.jpg","poiId":"poi-spain-barcelona-quimet-and-quimet"},{"id":"barcelona-weekend-apolo","name":"Sala Apolo","coordinates":[41.3752,2.1696],"description":"Sala Apolo is the popular-nightlife finish because weekends need at least one venue with citywide pull. Check the programming, then treat it as the big final stop rather than a casual bar-hop stop.","hours":{"mon":"10:00 PM-2:30 AM","tue":"10:00 PM-2:30 AM","wed":"10:00 PM-3:30 AM","thu":"10:00 PM-4:30 AM","fri":"10:00 PM-5:00 AM","sat":"10:00 PM-5:00 AM","sun":"10:00 PM-2:30 AM"},"photo":"https://sala-apolo.com/bundles/app/newsletterImg/Newsletter-Header-Mobile-01-640x466.jpg","poiId":"poi-spain-barcelona-sala-apolo"}],"sources":[{"name":"Barcelona Turisme","url":"https://www.barcelonaturisme.com"},{"name":"The Infatuation - Best Restaurants in Barcelona","url":"https://www.theinfatuation.com/barcelona/guides/best-restaurants-hotels-barcelona"},{"name":"Time Out - Best bars in Barcelona","url":"https://www.timeout.com/barcelona/bars-and-pubs/best-bars-in-barcelona"},{"name":"Fundació Joan Miró official","url":"https://www.fmirobcn.org"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-barcelona-week-activities', 'barcelona-week-itinerary', 'Activities', 'Spain', 'Barcelona', null, '{"id":"list-barcelona-week-activities","slug":"barcelona-week-itinerary","seoSlug":"best-things-to-do","seoTitle":"Best Things to Do in Barcelona for a Week","seoDescription":"Best one-week Barcelona itinerary, using the strongest citywide picks across restaurants, culture, dive bars, popular bars, hostels, stays, neighborhoods, and Montjuïc.","title":"A Week From Gràcia to the Hill","description":"A longer route that lets the categories spread out instead of competing for one day: hostel base, Gaudi starts, old-city history, tasting-menu splurge, Born nightlife, Montjuic reset, and Poble-sec finish.","url":"https://www.google.com/maps/search/barcelona+one+week+itinerary","category":"Activities","location":{"city":"Barcelona","country":"Spain","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-activities","name":"R Activities","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-04-29T00:00:00.000Z","stops":[{"id":"barcelona-week-yeah-hostel","name":"Yeah Barcelona Hostel","coordinates":[41.3983,2.1654],"description":"Use Yeah Barcelona as the hostel-category base for a week because the location works for Eixample, Gràcia, and Sagrada Família while the social programming helps longer-stay travelers find plans. It is especially useful when the itinerary needs an affordable base that can create community without relying on random bar crawls.","hours":{"mon":"24 hours","tue":"24 hours","wed":"24 hours","thu":"24 hours","fri":"24 hours","sat":"24 hours","sun":"24 hours"},"photo":"https://yeahostels.com/web/wp-content/uploads/2025/08/Location-Reception02.jpg","poiId":"poi-spain-barcelona-yeah-barcelona-hostel"},{"id":"barcelona-week-casa-vicens","name":"Casa Vicens","coordinates":[41.4035,2.1507],"description":"Start the week in Gràcia with Casa Vicens so the architecture story begins before the giant Gaudí icons. It is smaller, more domestic, and gives the neighborhood''s village rhythm a cultural anchor.","hours":{"mon":"9:00 AM-8:00 PM","tue":"9:00 AM-8:00 PM","wed":"9:00 AM-8:00 PM","thu":"9:00 AM-8:00 PM","fri":"9:00 AM-8:00 PM","sat":"9:00 AM-8:00 PM","sun":"9:00 AM-8:00 PM"},"photo":"https://casa-vicens-barcelona.com/wp-content/uploads/2026/01/9528674f03c44fe0b5fad6f5a055e924-1.jpg","poiId":"poi-spain-barcelona-casa-vicens"},{"id":"barcelona-week-bemba","name":"Bemba Smash Burger","coordinates":[41.407,2.1583],"description":"Bemba fills the casual-food slot for a longer trip: quick, current, and useful when the week should include a cheap meal that is not another tapas fallback. It also keeps the first Gràcia day light.","price":"$","priceSource":"Eater / Instagram","hours":{"mon":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","tue":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","wed":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","thu":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","fri":"12:30 PM-4:00 PM, 7:30 PM-11:30 PM","sat":"12:30 PM-4:00 PM, 7:30 PM-11:30 PM","sun":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM"},"photo":"https://lh5.googleusercontent.com/p/AF1QipPGy52GLF6bRtn426WdJUPVsiCjbkQx_nf9_Za0=w408-h306-k-no","poiId":"poi-spain-barcelona-bemba-smash-burger"},{"id":"barcelona-week-casa-batllo","name":"Casa Batlló","coordinates":[41.3917,2.1649],"description":"Casa Batlló carries the major Eixample culture day with the strongest high-impact architecture stop in the central grid. Give it time rather than squeezing it into a rushed old-city morning.","hours":{"mon":"9:00 AM-8:00 PM","tue":"9:00 AM-8:00 PM","wed":"9:00 AM-8:00 PM","thu":"9:00 AM-8:00 PM","fri":"9:00 AM-8:00 PM","sat":"9:00 AM-8:00 PM","sun":"9:00 AM-8:00 PM"},"photo":"https://casa-batllo-barcelona.com/wp-content/uploads/2026/01/19944e616eb84ad3b204463508875f98.jpeg","poiId":"poi-spain-barcelona-casa-batllo"},{"id":"barcelona-week-disfrutar","name":"Disfrutar","coordinates":[41.3878,2.1533],"description":"Disfrutar is the destination-restaurant slot for a full week because a longer itinerary can justify one trip-defining reservation. Keep it as the special meal, not a casual add-on, and build the day around the booking.","price":"$$$","priceSource":"MICHELIN Guide / World''s 50 Best","hours":{"mon":"Closed","tue":"1:00 PM-2:15 PM, 8:00 PM-9:15 PM","wed":"1:00 PM-2:15 PM, 8:00 PM-9:15 PM","thu":"1:00 PM-2:15 PM, 8:00 PM-9:15 PM","fri":"1:00 PM-2:15 PM, 8:00 PM-9:15 PM","sat":"1:00 PM-2:15 PM, 8:00 PM-9:15 PM","sun":"Closed"},"photo":"https://www.disfrutarbarcelona.com/api/uploads/restaurant/images/original/0c171d8288ac922fcd372beaceccb58d_phpQfnqi9.jpg","poiId":"poi-spain-barcelona-disfrutar"},{"id":"barcelona-week-muhba","name":"MUHBA Plaça del Rei","coordinates":[41.3845,2.1777],"description":"MUHBA Plaça del Rei gives the old-city portion historical depth instead of letting the Gothic Quarter become only atmosphere. The underground Roman route and palace context make Barcelona''s layers easier to read for the rest of the week.","hours":{"mon":"Closed","tue":"10:00 AM-7:00 PM","wed":"10:00 AM-7:00 PM","thu":"10:00 AM-7:00 PM","fri":"10:00 AM-7:00 PM","sat":"10:00 AM-7:00 PM","sun":"10:00 AM-7:00 PM"},"photo":"https://upload.wikimedia.org/wikipedia/commons/b/be/MUHBA_Casa_Padellas_Pla%C3%A7a_del_rei_2.JPG","poiId":"poi-spain-barcelona-muhba-placa-del-rei"},{"id":"barcelona-week-la-plata","name":"Bar La Plata","coordinates":[41.3818,2.1799],"description":"Bar La Plata is the low-key Gothic bar stop for the week: simple, historic, fast, and food-adjacent. It is best used as a compact vermouth-and-bites pause before moving into the Born or waterfront.","hours":{"mon":"12:00 PM-12:30 AM","tue":"12:00 PM-12:30 AM","wed":"12:00 PM-12:30 AM","thu":"12:00 PM-1:30 AM","fri":"12:00 PM-2:00 AM","sat":"12:00 PM-2:00 AM","sun":"12:00 PM-12:00 AM"},"photo":"https://barlaplata.com/wp-content/uploads/2024/04/img_7003-1.jpg","poiId":"poi-spain-barcelona-bar-la-plata"},{"id":"barcelona-week-santa-maria","name":"Basílica de Santa Maria del Mar","coordinates":[41.3839,2.1822],"description":"Santa Maria del Mar anchors the El Born day with architecture that explains the neighborhood''s medieval merchant identity. Pair it with the Picasso Museum area, Ciutadella, or a cava stop nearby.","hours":{"mon":"9:00 AM-8:00 PM","tue":"9:00 AM-8:00 PM","wed":"9:00 AM-8:00 PM","thu":"9:00 AM-8:00 PM","fri":"9:00 AM-8:00 PM","sat":"9:00 AM-8:00 PM","sun":"9:00 AM-8:00 PM"},"photo":"https://upload.wikimedia.org/wikipedia/commons/4/4c/Santa_Maria_del_Mar%2C_Barcelona_02.jpg","poiId":"poi-spain-barcelona-basilica-de-santa-maria-del-mar"},{"id":"barcelona-week-paradiso","name":"Paradiso","coordinates":[41.3859,2.1822],"description":"Paradiso is the popular-bar slot for the Born night because a week gives you room to accept the queue and make the cocktail spectacle the event. Save it for a night with slack in the schedule so the wait feels intentional rather than disruptive.","hours":{"mon":"6:00 PM-12:30 AM","tue":"6:00 PM-12:30 AM","wed":"6:00 PM-1:00 AM","thu":"6:00 PM-1:30 AM","fri":"6:00 PM-2:30 AM","sat":"6:00 PM-2:30 AM","sun":"6:00 PM-12:00 AM"},"photo":"https://paradiso.cat/wp-content/uploads/2020/06/bck_premios-scaled_op.jpg","poiId":"poi-spain-barcelona-paradiso"},{"id":"barcelona-week-joan-miro","name":"Fundació Joan Miró","coordinates":[41.3686,2.1592],"description":"Fundació Joan Miró gives the Montjuïc day a focused art center before the route turns toward gardens, views, or Poble-sec. It is a smart midweek reset after denser old-city days.","hours":{"mon":"Closed","tue":"10:00 AM-7:00 PM","wed":"10:00 AM-7:00 PM","thu":"10:00 AM-7:00 PM","fri":"10:00 AM-7:00 PM","sat":"10:00 AM-7:00 PM","sun":"10:00 AM-7:00 PM"},"photo":"https://upload.wikimedia.org/wikipedia/commons/9/9d/Fundaci%C3%B3_Mir%C3%B3.JPG","poiId":"poi-spain-barcelona-fundacio-joan-miro"},{"id":"barcelona-week-quimet-quimet","name":"Quimet & Quimet","coordinates":[41.3738,2.1635],"description":"Quimet & Quimet is the Poble-sec food-and-dive-bar bridge, with standing montaditos and bottles that fit a weeklong itinerary better than another formal dinner. Go early and let it launch a Carrer de Blai evening.","hours":{"mon":"12:00 PM-11:00 PM","tue":"12:00 PM-11:00 PM","wed":"12:00 PM-11:00 PM","thu":"12:00 PM-11:30 PM","fri":"12:00 PM-12:00 AM","sat":"12:00 PM-12:00 AM","sun":"12:00 PM-10:30 PM"},"photo":"https://quimetiquimet.com/wp-content/uploads/tapbg.jpg","poiId":"poi-spain-barcelona-quimet-and-quimet"},{"id":"barcelona-week-apolo","name":"Sala Apolo","coordinates":[41.3752,2.1696],"description":"Sala Apolo closes the week with the city''s bigger nightlife energy: concerts, club programming, and a real reason to stay out late. It is the final category contrast after museums, restaurants, hostels, and small bars.","hours":{"mon":"10:00 PM-2:30 AM","tue":"10:00 PM-2:30 AM","wed":"10:00 PM-3:30 AM","thu":"10:00 PM-4:30 AM","fri":"10:00 PM-5:00 AM","sat":"10:00 PM-5:00 AM","sun":"10:00 PM-2:30 AM"},"photo":"https://sala-apolo.com/bundles/app/newsletterImg/Newsletter-Header-Mobile-01-640x466.jpg","poiId":"poi-spain-barcelona-sala-apolo"}],"sources":[{"name":"Barcelona Turisme","url":"https://www.barcelonaturisme.com"},{"name":"The Infatuation - Best Restaurants in Barcelona","url":"https://www.theinfatuation.com/barcelona/guides/best-restaurants-hotels-barcelona"},{"name":"Eater - Best Restaurants in Barcelona","url":"https://www.eater.com/maps/best-restaurants-barcelona-spain"},{"name":"MICHELIN Guide - Disfrutar","url":"https://guide.michelin.com/us/en/catalunya/barcelona/restaurant/disfrutar"},{"name":"Time Out - Best bars in Barcelona","url":"https://www.timeout.com/barcelona/bars-and-pubs/best-bars-in-barcelona"},{"name":"Hostelworld - Barcelona hostels","url":"https://www.hostelworld.com/st/hostels/europe/spain/barcelona/"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-gabriel-first-guide', 'gabriel-first-guide', 'Activities', 'United States', 'San Francisco', null, '{"id":"list-gabriel-first-guide","slug":"gabriel-first-guide","title":"SF Visitor Guide","description":"A first-time San Francisco route spanning waterfront landmarks, iconic parks, major museums, and city viewpoints worth planning around.","url":"https://maps.app.goo.gl/ipATDsbmTuXVr8hc9?g_st=ac","category":"Activities","location":{"city":"San Francisco","country":"United States","continent":"North America","scope":"city"},"creator":{"id":"user-gabriel-soyka","name":"Gabriel Soyka","avatar":"https://i.pravatar.cc/160?img=59"},"upvotes":1,"createdAt":"2026-04-21T00:00:00.000Z","submissionType":"guide","stops":[{"id":"gabriel-sf-ferry-building","name":"Ferry Building","coordinates":[37.7954425,-122.3936136],"description":"The Ferry Building is the right first-stop anchor for this SF guide because it combines food vendors, bayfront walking, ferry access, and an easy Market Street handoff. Use it in the morning when the waterfront is calmer and the route can open toward North Beach or the Embarcadero.","photo":"https://www.ferrybuildingmarketplace.com/wp-content/uploads/Hudson_Ferry-Building_v01_A03-web-e1673549910651.jpeg","poiId":"poi-united-states-san-francisco-ferry-building"},{"id":"gabriel-sf-fishermans-wharf","name":"Fisherman''s Wharf","coordinates":[37.8084354,-122.4157509],"description":"Fisherman''s Wharf earns a spot as the obvious first-time waterfront hit: busy, touristy, but useful for pier walks, bay views, and quick transitions toward North Beach. Treat it as a short district pass-through rather than the emotional center of the day.","photo":"https://dfht7c9lgb1wh.cloudfront.net/clients/logos/000/000/482/original/fishermans-logo-1560780383.png?1560780383","poiId":"poi-united-states-san-francisco-fisherman-s-wharf"},{"id":"gabriel-sf-palace-of-fine-arts","name":"Palace of Fine Arts","coordinates":[37.8029308,-122.4484231],"description":"The Palace of Fine Arts gives the route a slower architectural pause after denser waterfront stops. Its rotunda, lagoon, and open lawns work best around golden hour, when the stop can be about photos and decompression rather than checking off another attraction.","photo":"https://upload.wikimedia.org/wikipedia/commons/0/0c/Palace_of_Fine_Arts_San_Francisco_January_2014_003.jpg","poiId":"poi-united-states-san-francisco-palace-of-fine-arts"},{"id":"gabriel-sf-alamo-square","name":"Alamo Square Park","coordinates":[37.7763694,-122.434819],"description":"Alamo Square Park gives the guide a classic skyline-lawn view framed by the Painted Ladies and downtown beyond. Use it as a short viewpoint stop between neighborhoods, not a long park day, unless the weather is doing the work for you.","photo":"https://upload.wikimedia.org/wikipedia/commons/c/cb/Painted_Ladies%2C_Alamo_Square.jpg","poiId":"poi-united-states-san-francisco-alamo-square-park"},{"id":"gabriel-sf-de-young","name":"de Young Museum","coordinates":[37.771469,-122.4686755],"description":"The de Young Museum is the Golden Gate Park culture anchor, with permanent collections and a tower lookout that gives broad western-city views. It is most useful when the route needs an indoor museum block that still connects back to the park.","photo":"https://drupal-prod.visitcalifornia.com/sites/default/files/styles/opengraph_1200x630/public/2022-04/VC_deYoung-Museum_gty-1322127331-RM_1280x640.jpg.webp?itok=WKjMo8jr","poiId":"poi-united-states-san-francisco-de-young-museum"},{"id":"gabriel-sf-legion-of-honor","name":"Legion of Honor","coordinates":[37.7845231,-122.5007596],"description":"The Legion of Honor gives the guide a quieter fine-arts stop on the ocean edge, with a dramatic approach and a calmer pace than the central museums. Pair it with Lands End when you want culture and coastal walking in the same west-side loop.","photo":"https://www.famsf.org/storage/images/17c073c6-ccbe-4cff-9d05-83cf4d6a69cd/digital-22-image-social-share-r1.jpg?crop=1200,628,x0,y0&format=jpg&quality=80","poiId":"poi-united-states-san-francisco-legion-of-honor"},{"id":"gabriel-sf-lombard","name":"Lombard St","coordinates":[37.8020179,-122.4195579],"description":"Lombard Street is busy and overfamiliar, but it still works as a quick first-time SF marker when you frame it correctly. Pair it with a short uphill walk for better full-street views, then move on before the crowd becomes the whole experience.","photo":"https://drupal-prod.visitcalifornia.com/sites/default/files/styles/opengraph_1200x630/public/2021-12/VC_Lombard-Street_gty-1158272202-RF_1280x640.jpg.webp?itok=KkSxfJSb","poiId":"poi-united-states-san-francisco-lombard-st"},{"id":"gabriel-sf-vermont","name":"Vermont St (The real “Crookedest Street in the World.”)","coordinates":[37.7589957,-122.4039109],"description":"Vermont Street is the local counterpoint to Lombard, with tighter turns, fewer crowds, and a more neighborhood feel in Potrero Hill. It is worth saving because it gives the guide a more insider-feeling version of the crooked-street idea.","photo":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/61/Vermont_Street_%28San_Francisco%29.jpg/1280px-Vermont_Street_%28San_Francisco%29.jpg","poiId":"poi-united-states-san-francisco-vermont-st-the-real-crookedest-street-in-the-world"},{"id":"gabriel-sf-bison-paddock","name":"Bison Paddock","coordinates":[37.7696864,-122.4982325],"description":"The Bison Paddock adds a strange, memorable Golden Gate Park break that keeps the route from becoming only museums and viewpoints. Use it as a quick west-side detour when you are already crossing the park toward the ocean.","photo":"https://poloroutes.com/img_uploads/tourist-places/8071091689762129.jpg","poiId":"poi-united-states-san-francisco-bison-paddock"},{"id":"gabriel-sf-amoeba","name":"Amoeba Music","coordinates":[37.7691734,-122.4526639],"description":"Amoeba Music gives the guide an indoor Haight culture stop with deep vinyl selection and a real local-history feel. It works best as a browse-and-reset break between parks, viewpoints, and Mission-side plans.","photo":"https://upload.wikimedia.org/wikipedia/commons/f/ff/AmoebaSF.jpg","poiId":"poi-united-states-san-francisco-amoeba-music"},{"id":"gabriel-sf-rodeo-beach","name":"Rodeo Beach Coastal Trailhead","coordinates":[37.8322377,-122.5395782],"description":"Rodeo Beach Coastal Trailhead is the strongest outside-the-city nature extension in this guide, with rugged coastal walks, Pacific views, and bridge-backdrop angles from the Marin Headlands. Use it when the day can handle wind, transit or driving time, and a more physical route.","photo":"https://www.marincountyvisitor.com/wp-content/uploads/2024/11/Rodeo-Beach.jpg","poiId":"poi-united-states-san-francisco-rodeo-beach-coastal-trailhead"},{"id":"gabriel-sf-duboce","name":"Duboce Park","coordinates":[37.7695967,-122.4333344],"description":"Duboce Park is a small neighborhood reset that works because of where it sits: between Haight, the Mission, Castro-adjacent transit, and central routes. Use it for a low-pressure pause rather than a destination park visit.","photo":"https://friendsofdubocepark.org/wp-content/uploads/2022/09/screen-shot-2022-09-29-at-10.55.52-pm-1.png","poiId":"poi-united-states-san-francisco-duboce-park"},{"id":"gabriel-sf-grandview","name":"Grandview Park","coordinates":[37.7564222,-122.4717361],"description":"Grandview Park earns its place through the payoff-to-time ratio: a steep stair climb to a compact summit with city-to-ocean panoramas. It is best for travelers who want one strong viewpoint without committing to a long hike.","photo":"https://www.inside-guide-to-san-francisco-tourism.com/images/san-francisco-bay-view-from-summit-grandview-park.jpg","poiId":"poi-united-states-san-francisco-grandview-park"},{"id":"gabriel-sf-dolores","name":"Mission Dolores Park","coordinates":[37.7602015,-122.4267959],"description":"Mission Dolores Park is the social park anchor of the guide, with broad downtown views and a strong afternoon crowd. Use it before dinner in the Mission when the city should feel lived-in, sunny, and easy to linger in.","photo":"https://parksofsanfrancisco.com/static/seo/parks-thumbnail.png","poiId":"poi-united-states-san-francisco-mission-dolores-park"}],"sources":[{"name":"Google Maps shared list","url":"https://maps.app.goo.gl/ipATDsbmTuXVr8hc9?g_st=ac"}]}'::jsonb),
  ('list-gabriel-experience-dolores-sunset', 'gabriel-experience-dolores-sunset', 'Activities', 'United States', 'San Francisco', null, '{"id":"list-gabriel-experience-dolores-sunset","slug":"gabriel-experience-dolores-sunset","title":"Dolores Park Golden Hour","description":"Caught sunset on the upper slope with a full downtown skyline glow and a packed local after-work crowd.","url":"https://maps.google.com/?q=Mission+Dolores+Park+San+Francisco","category":"Activities","submissionType":"journal","journal":{"visitedAt":"2026-04-18","note":"Best around 6:30-7:30 PM with a light layer, then walked down Valencia for dinner."},"location":{"city":"San Francisco","country":"United States","continent":"North America","scope":"city"},"creator":{"id":"user-gabriel-soyka","name":"Gabriel Soyka","avatar":"https://i.pravatar.cc/160?img=59"},"upvotes":1,"createdAt":"2026-04-18T00:00:00.000Z","stops":[{"id":"gabriel-exp-dolores-stop","name":"Mission Dolores Park","coordinates":[37.7602015,-122.4267959],"description":"Mission Dolores Park is saved here for the upper-slope sunset view, where downtown, the Mission, and the after-work crowd all read at once. It is best treated as a lingering golden-hour stop before walking down toward Valencia or nearby dinner plans.","photo":"https://parksofsanfrancisco.com/static/seo/parks-thumbnail.png","poiId":"poi-united-states-san-francisco-mission-dolores-park"}],"sources":[{"name":"Personal experience","url":"https://maps.google.com/?q=Mission+Dolores+Park+San+Francisco"}]}'::jsonb),
  ('list-gabriel-experience-ferry-morning', 'gabriel-experience-ferry-morning', 'Activities', 'United States', 'San Francisco', null, '{"id":"list-gabriel-experience-ferry-morning","slug":"gabriel-experience-ferry-morning","title":"Ferry Building Morning Loop","description":"Started early at the Ferry Building, grabbed coffee, then walked north along the Embarcadero before crowds built.","url":"https://maps.google.com/?q=Ferry+Building+San+Francisco","category":"Activities","submissionType":"journal","journal":{"visitedAt":"2026-04-12","note":"Weekday mornings are easiest; great first stop before crossing into North Beach."},"location":{"city":"San Francisco","country":"United States","continent":"North America","scope":"city"},"creator":{"id":"user-gabriel-soyka","name":"Gabriel Soyka","avatar":"https://i.pravatar.cc/160?img=59"},"upvotes":1,"createdAt":"2026-04-12T00:00:00.000Z","stops":[{"id":"gabriel-exp-ferry-stop","name":"Ferry Building","coordinates":[37.7954425,-122.3936136],"description":"The Ferry Building works as a morning launch point because coffee, food-hall browsing, ferries, and the Embarcadero walk are all immediately available. Start early, then use the waterfront path to move north before the busiest visitor traffic builds.","photo":"https://www.ferrybuildingmarketplace.com/wp-content/uploads/Hudson_Ferry-Building_v01_A03-web-e1673549910651.jpeg","poiId":"poi-united-states-san-francisco-ferry-building"}],"sources":[{"name":"Personal experience","url":"https://maps.google.com/?q=Ferry+Building+San+Francisco"}]}'::jsonb),
  ('list-gabriel-experience-headlands-wind', 'gabriel-experience-headlands-wind', 'Nature', 'United States', 'San Francisco', null, '{"id":"list-gabriel-experience-headlands-wind","slug":"gabriel-experience-headlands-wind","title":"Windy Marin Headlands Run","description":"Quick headlands run from Rodeo Beach trailhead with strong wind, dramatic coastline, and clear bridge-back views.","url":"https://maps.google.com/?q=Rodeo+Beach+Coastal+Trailhead","category":"Nature","submissionType":"journal","journal":{"visitedAt":"2026-03-30","note":"Bring a windbreaker even on sunny days; visibility changes fast."},"location":{"city":"San Francisco","country":"United States","continent":"North America","scope":"city"},"creator":{"id":"user-gabriel-soyka","name":"Gabriel Soyka","avatar":"https://i.pravatar.cc/160?img=59"},"upvotes":1,"createdAt":"2026-03-30T00:00:00.000Z","stops":[{"id":"gabriel-exp-headlands-stop","name":"Rodeo Beach Coastal Trailhead","coordinates":[37.8322377,-122.5395782],"description":"Rodeo Beach Coastal Trailhead is saved here for a short, windy Headlands run with high-impact ocean views almost immediately from the start. Bring a layer and use it when the day has enough time for a wilder coastal reset outside the city core.","photo":"https://www.marincountyvisitor.com/wp-content/uploads/2024/11/Rodeo-Beach.jpg","poiId":"poi-united-states-san-francisco-rodeo-beach-coastal-trailhead"}],"sources":[{"name":"Personal experience","url":"https://maps.google.com/?q=Rodeo+Beach+Coastal+Trailhead"}]}'::jsonb)
